#Requires -Version 5.1
<#
.SYNOPSIS
    WinPE OCs - offline edition (all 38 languages): language packs, Features on Demand (FOD) and
    Windows PE optional components (WinPE_OCs) from a local repository of encrypted .bin archives.

.DESCRIPTION
    Single-file tool, started by WinPEOCs-Offline.cmd (elevated, Windows PowerShell 5.1, STA). The C# + WPF
    user interface is compiled in memory with Add-Type on every start; no DLL or EXE is written to disk.

    The catalog of every language (UUP rows, file lists, SHA-1 hashes, Windows PE builds) is embedded in
    the script; Repo\index.txt overrides it when present. The repository folder holds one .bin archive per
    UUP row, architecture and language (<version>_<arch>_<lang>.bin) and, per Windows PE build and
    architecture, one archive for the neutral packages (winpe_<build>_<arch>.bin) plus one per language
    (winpe_<build>_<arch>_<lang>.bin). Archives of the tr-tr design (<version>_<arch>.bin with neutral and
    tr-tr packages in winpe_<build>_<arch>.bin) keep working for the language of their manifest.
    When List finds files that are not in the repository yet, it offers to download them once from
    Microsoft (Windows Update FE3 / ADK CDN), verifies them with the catalog SHA-1 and adds them to the
    archive; after that everything works without an internet connection.

    Navigation:
      Language Packs  catalog rows; files are copied from the repository to Langs / OnDemand\<arch>
      Windows PE      catalog / embedded ADK index; packages are copied to WinPE\<build>\<arch>\WinPE_OCs
      Log             All operations of the session (also in %LOCALAPPDATA%\WinPEOCs\logs)
      Settings        Output folder, verification, repository check, UI language (Turkish / English)

.PARAMETER Repo
    Repository folder (default: Repo next to the script).

.PARAMETER ShowConsole
    Keep the console window visible (for troubleshooting).

.PARAMETER NoGui
    Load only the engine, catalog and archive functions without opening the UI (when dot-sourced, the
    functions stay in the session).

.EXAMPLE
    WinPEOCs-Offline.cmd

.EXAMPLE
    powershell.exe -ExecutionPolicy Bypass -Sta -File .\WinPEOCs-Offline.ps1 -Repo D:\WinPEOCs\Repo

.NOTES
    Version 3.0.0 · Windows PowerShell 5.1 / PowerShell 7.x (Windows)
#>
[CmdletBinding()]
param(
    [string]$Repo,
    [switch]$ShowConsole,
    [switch]$NoGui
)

$script:AppVersion = '3.0.0'
$script:AppStartWatch = [System.Diagnostics.Stopwatch]::StartNew()

if ([System.Environment]::OSVersion.Platform -ne [System.PlatformID]::Win32NT -and -not $NoGui) {
    Write-Error 'WinPE OCs arayüzü yalnızca Windows üzerinde çalışır.'
    return
}

$script:AppRoot = if ($PSScriptRoot) { $PSScriptRoot } else { (Get-Location).ProviderPath }
$script:AppDataDir = Join-Path ([Environment]::GetFolderPath('ApplicationData')) 'WinPEOCs'
$script:LocalDataDir = Join-Path ([Environment]::GetFolderPath('LocalApplicationData')) 'WinPEOCs'
$script:RepoDir = if ($Repo) { $Repo } else { Join-Path $script:AppRoot 'Repo' }

# --- C# source (compiled in memory by Add-Type) and XAML ---
$script:CsSource = @'
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Net;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Collections;
using System.Collections.Concurrent;
using System.Collections.ObjectModel;
using System.Collections.Specialized;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Data;
using System.Windows.Input;
using System.Windows.Interop;
using System.Windows.Markup;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Shell;
using System.Windows.Threading;

// WinPEOCs.Core - WPF-independent core: UI thread bridge, observable objects, package rows,
// TR/EN strings, formatting, resumable HTTP downloader, SHA verification, settings, native APIs.
// C# 5 compatible (Windows PowerShell 5.1 Add-Type / CodeDom); also compiles on .NET 8 (PowerShell 7).

namespace WinPEOCs
{
    // Marshals work to the UI thread. Initialized by the UI host; when it is not initialized
    // (tests) actions run inline.
    public static class UiThread
    {
        private static SynchronizationContext _context;
        private static int _threadId = -1;

        public static void Initialize(SynchronizationContext context)
        {
            _context = context;
            _threadId = Thread.CurrentThread.ManagedThreadId;
        }

        public static bool IsReady { get { return _context != null; } }

        public static bool CheckAccess()
        {
            return _context == null || Thread.CurrentThread.ManagedThreadId == _threadId;
        }

        public static void Post(Action action)
        {
            if (action == null) return;
            if (CheckAccess()) { action(); return; }
            try { _context.Post(InvokeAction, action); } catch { }
        }

        private static void InvokeAction(object state)
        {
            Action a = state as Action;
            if (a != null) a();
        }
    }

    public abstract class ObservableObject : INotifyPropertyChanged
    {
        public event PropertyChangedEventHandler PropertyChanged;

        protected void Raise([CallerMemberName] string name = null)
        {
            if (PropertyChanged == null) return;
            if (UiThread.CheckAccess()) RaiseCore(name);
            else UiThread.Post(delegate { RaiseCore(name); });
        }

        protected void RaiseMany(params string[] names)
        {
            if (names == null) return;
            foreach (string n in names) Raise(n);
        }

        private void RaiseCore(string name)
        {
            PropertyChangedEventHandler h = PropertyChanged;
            if (h != null) h(this, new PropertyChangedEventArgs(name));
        }

        protected bool Set<T>(ref T field, T value, [CallerMemberName] string name = null)
        {
            if (EqualityComparer<T>.Default.Equals(field, value)) return false;
            field = value;
            Raise(name);
            return true;
        }
    }

    // Package / file row (shared by the Language Packs and Windows PE lists)
    public enum ItemState { Idle, Queued, Resolving, Downloading, Verifying, Extracting, Partial, Done, Exists, Skipped, Error, Cancelled }

    public sealed class PackageItem : ObservableObject
    {
        private bool _isChecked;
        private ItemState _state;
        private string _statusOverride;
        private string _statusToolTip;
        private double _progress = -1;
        private int _filesDone;

        public PackageItem()
        {
            Category = "fod";
            Languages = new string[0];
            Containers = new string[0];
            Dependencies = new string[0];
        }

        public string Key { get; set; }
        public string Name { get; set; }
        public string DescTr { get; set; }
        public string DescEn { get; set; }
        public string Category { get; set; }
        public int SortIndex { get; set; }
        public long Size { get; set; }

        // Language pack / FOD fields
        public string Url { get; set; }
        public long Expire { get; set; }
        public string Sha1 { get; set; }
        public string Sha256 { get; set; }
        public string UpdateId { get; set; }
        public string Language { get; set; }
        public string Build { get; set; }
        public string Arch { get; set; }
        public int Sku { get; set; }

        // Windows PE fields
        public string BuildId { get; set; }
        public string[] Languages { get; set; }
        public string[] Containers { get; set; }
        public string[] Dependencies { get; set; }
        public int FileCount { get; set; }
        public object Data { get; set; }

        public int FilesDone
        {
            get { return _filesDone; }
            set { _filesDone = value; Raise("Status"); }
        }

        public string Description
        {
            get
            {
                if (Loc.IsEnglish && !string.IsNullOrEmpty(DescEn)) return DescEn;
                return DescTr ?? DescEn ?? string.Empty;
            }
        }

        public bool HasDescription { get { return !string.IsNullOrEmpty(Description); } }
        public string SizeText { get { return Fmt.Size(Size); } }

        public string ToolTipText
        {
            get
            {
                StringBuilder sb = new StringBuilder();
                sb.Append(Name);
                if (HasDescription) sb.Append("\n").Append(Description);
                if (Dependencies != null && Dependencies.Length > 0)
                    sb.Append("\n").Append(Loc.F("Pe_Requires", string.Join(", ", Dependencies)));
                if (FileCount > 1) sb.Append("\n").Append(Loc.F("Pe_FileCount", FileCount));
                return sb.ToString();
            }
        }

        public bool IsChecked
        {
            get { return _isChecked; }
            set
            {
                if (Set(ref _isChecked, value))
                {
                    EventHandler h = CheckedChanged;
                    if (h != null) h(this, EventArgs.Empty);
                }
            }
        }

        public event EventHandler CheckedChanged;

        public void SetCheckedSilently(bool value)
        {
            if (_isChecked == value) return;
            _isChecked = value;
            Raise("IsChecked");
        }

        public ItemState State { get { return _state; } }
        public string StateKey { get { return _state.ToString(); } }
        public double Progress { get { return _progress < 0 ? 0 : _progress; } }
        public bool ShowBar { get { return _state == ItemState.Downloading && _progress >= 0; } }
        public string StatusToolTip { get { return _statusToolTip; } }

        public string Status
        {
            get
            {
                if (!string.IsNullOrEmpty(_statusOverride)) return _statusOverride;
                switch (_state)
                {
                    case ItemState.Downloading:
                        return _progress >= 0 ? Loc.F("S_DownloadingPct", Math.Floor(_progress)) : Loc.T("S_Downloading");
                    case ItemState.Partial:
                        return Loc.F("S_Partial", _filesDone, FileCount);
                    default:
                        return Loc.T("S_" + _state.ToString());
                }
            }
        }

        public void SetState(string state)
        {
            SetState(state, null);
        }

        public void SetState(string state, string text)
        {
            ItemState s;
            if (string.IsNullOrEmpty(state) || !Enum.TryParse<ItemState>(state, true, out s)) s = ItemState.Idle;
            SetStateCore(s, text, -1);
        }

        public void SetStateCore(ItemState state, string text, double progress)
        {
            _state = state;
            _statusOverride = text;
            _statusToolTip = string.IsNullOrEmpty(text) ? null : text;
            _progress = progress;
            RaiseMany("State", "StateKey", "Status", "StatusToolTip", "Progress", "ShowBar");
        }

        public void Fail(string message)
        {
            _state = ItemState.Error;
            _statusOverride = null;
            _statusToolTip = message;
            _progress = -1;
            RaiseMany("State", "StateKey", "Status", "StatusToolTip", "Progress", "ShowBar");
        }

        public void SetProgress(double percent)
        {
            if (percent > 100) percent = 100;
            bool barChange = _progress < 0;
            if (!barChange && Math.Abs(_progress - percent) < 0.5 && percent < 100) return;
            _progress = percent;
            Raise("Progress");
            Raise("Status");
            if (barChange) Raise("ShowBar");
        }

        public void RefreshLocalized()
        {
            RaiseMany("Description", "HasDescription", "Status", "SizeText", "ToolTipText");
        }

        public override string ToString() { return Name ?? Key ?? base.ToString(); }
    }

    public sealed class OptionItem
    {
        public OptionItem(string value, string label) { Value = value; Label = label; }
        public OptionItem(string value, string label, string extra) { Value = value; Label = label; Extra = extra; }
        public string Value { get; private set; }
        public string Label { get; private set; }
        public string Extra { get; private set; }
        public override string ToString() { return Label ?? Value; }
    }

    public sealed class KeyValueRow
    {
        public KeyValueRow(string key, string value) { Key = key; Value = value; }
        public KeyValueRow(string key, string value, bool emphasis) { Key = key; Value = value; Emphasis = emphasis; }
        public string Key { get; private set; }
        public string Value { get; private set; }
        public bool Emphasis { get; private set; }
    }

    public sealed class LogEntry
    {
        public LogEntry(string level, string message)
        {
            Time = DateTime.Now;
            Level = string.IsNullOrEmpty(level) ? "info" : level.ToLowerInvariant();
            Message = message ?? string.Empty;
        }
        public DateTime Time { get; private set; }
        public string Level { get; private set; }
        public string Message { get; private set; }
        public string TimeText { get { return Time.ToString("HH:mm:ss", CultureInfo.InvariantCulture); } }
        public string Glyph
        {
            get
            {
                switch (Level)
                {
                    case "error": return "\uEA39";
                    case "warn": return "\uE7BA";
                    case "ok": return "\uE73E";
                    default: return "\uE946";
                }
            }
        }
        public override string ToString()
        {
            return Time.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture) + " [" + Level.ToUpperInvariant() + "] " + Message;
        }
    }

    // Formatting (size, speed, duration) in the culture of the UI language
    public static class Fmt
    {
        public static string Size(long bytes)
        {
            CultureInfo c = Loc.Culture;
            double b = bytes;
            if (b >= 1073741824.0) return (b / 1073741824.0).ToString("N2", c) + " GB";
            if (b >= 1048576.0) return (b / 1048576.0).ToString("N1", c) + " MB";
            if (b >= 1024.0) return (b / 1024.0).ToString("N0", c) + " KB";
            if (b < 0) return "?";
            return bytes.ToString("N0", c) + " B";
        }

        public static string Speed(double bytesPerSecond)
        {
            if (bytesPerSecond <= 0 || double.IsNaN(bytesPerSecond) || double.IsInfinity(bytesPerSecond)) return "—";
            return Size((long)bytesPerSecond) + Loc.T("U_PerSec");
        }

        public static string Duration(double seconds)
        {
            if (seconds < 0 || double.IsNaN(seconds) || double.IsInfinity(seconds) || seconds > 359999) return "—";
            int s = (int)Math.Ceiling(seconds);
            if (s < 60) return "~" + s.ToString(CultureInfo.InvariantCulture) + " " + Loc.T("U_Sec");
            int m = s / 60; s = s % 60;
            if (m < 60) return "~" + m.ToString(CultureInfo.InvariantCulture) + " " + Loc.T("U_Min") + " " + s.ToString(CultureInfo.InvariantCulture) + " " + Loc.T("U_Sec");
            int h = m / 60; m = m % 60;
            return "~" + h.ToString(CultureInfo.InvariantCulture) + " " + Loc.T("U_Hour") + " " + m.ToString(CultureInfo.InvariantCulture) + " " + Loc.T("U_Min");
        }

        public static string Percent(double value)
        {
            return Loc.F("U_Percent", Math.Floor(Math.Max(0, Math.Min(100, value))));
        }
    }

    // Localization: Turkish (default) / English
    public sealed class Loc : ObservableObject
    {
        private static readonly Loc _instance = new Loc();
        private static readonly Dictionary<string, string[]> _map = new Dictionary<string, string[]>(StringComparer.Ordinal);
        private static readonly CultureInfo _tr = CultureInfo.GetCultureInfo("tr-TR");
        private static readonly CultureInfo _en = CultureInfo.GetCultureInfo("en-US");
        private static volatile bool _english;

        public static Loc Instance { get { return _instance; } }
        public static bool IsEnglish { get { return _english; } }
        public static string Lang { get { return _english ? "en" : "tr"; } }
        public static CultureInfo Culture { get { return _english ? _en : _tr; } }
        public static event EventHandler LanguageChanged;

        public string this[string key] { get { return T(key); } }

        public static void SetLanguage(string lang)
        {
            bool en = string.Equals(lang, "en", StringComparison.OrdinalIgnoreCase);
            if (en == _english) return;
            _english = en;
            _instance.Raise("Item[]");
            EventHandler h = LanguageChanged;
            if (h != null) h(null, EventArgs.Empty);
        }

        public static string T(string key)
        {
            string[] v;
            if (key != null && _map.TryGetValue(key, out v)) return _english ? v[1] : v[0];
            return key ?? string.Empty;
        }

        public static string F(string key, params object[] args)
        {
            string fmt = T(key);
            try { return string.Format(Culture, fmt, args ?? new object[0]); }
            catch (FormatException) { return fmt; }
        }

        public static bool Has(string key) { return key != null && _map.ContainsKey(key); }

        private static void A(string key, string tr, string en) { _map[key] = new string[] { tr, en }; }

        public static void AppendTable(object table)
        {
            if (table == null) return;
            System.Collections.IEnumerable list = table as System.Collections.IEnumerable;
            if (list == null) return;
            foreach (object item in list)
            {
                System.Collections.IList row = item as System.Collections.IList;
                if (row != null && row.Count >= 3)
                {
                    string k = row[0] as string;
                    string tr = row[1] as string;
                    string en = row[2] as string;
                    if (!string.IsNullOrEmpty(k)) _map[k] = new string[] { tr, en };
                }
            }
        }

        static Loc()
        {
