    // Cancellation token (also aborts the active HTTP request)
    public sealed class CancelToken
    {
        private volatile bool _cancelled;
        private readonly object _gate = new object();
        private WebRequest _current;

        public bool IsCancelled { get { return _cancelled; } }

        public void Cancel()
        {
            _cancelled = true;
            WebRequest r;
            lock (_gate) { r = _current; }
            if (r != null) { try { r.Abort(); } catch { } }
        }

        public void Reset() { _cancelled = false; }

        internal void Attach(WebRequest request)
        {
            lock (_gate) { _current = request; }
            if (_cancelled && request != null) { try { request.Abort(); } catch { } }
        }

        internal void Detach() { lock (_gate) { _current = null; } }
    }

    public interface ITransferObserver
    {
        void OnStart(long total, long resumedFrom);
        void OnProgress(long done, long total, double bytesPerSecond);
        void OnFinish(bool success, long bytes);
    }

    public sealed class TransferResult
    {
        public bool Success { get; set; }
        public bool Cancelled { get; set; }
        public bool Resumed { get; set; }
        public long Bytes { get; set; }
        public int StatusCode { get; set; }
        public string Message { get; set; }
        public string Path { get; set; }
        public override string ToString() { return Success ? "OK" : (Message ?? "?"); }
    }

    // HTTP downloader: writes to a .part file, resumes with Range requests,
    // retries transient errors and aborts the request immediately on cancel.
    public static class Net
    {
        public static string UserAgent = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) WinPEOCs/3.0";

        static Net() { EnsureTls(); }

        public static void EnsureTls()
        {
            try { ServicePointManager.SecurityProtocol |= SecurityProtocolType.Tls12; } catch { }
            try { ServicePointManager.SecurityProtocol |= (SecurityProtocolType)12288; } catch { }
            try { if (ServicePointManager.DefaultConnectionLimit < 8) ServicePointManager.DefaultConnectionLimit = 8; } catch { }
            try { ServicePointManager.Expect100Continue = false; } catch { }
            try
            {
                IWebProxy p = WebRequest.DefaultWebProxy;
                if (p != null && p.Credentials == null) p.Credentials = CredentialCache.DefaultNetworkCredentials;
            }
            catch { }
        }

        public static TransferResult Download(string url, string destPath, long expectedSize, ITransferObserver observer, CancelToken token)
        {
            return Download(url, destPath, expectedSize, observer, token, 3);
        }

        public static TransferResult Download(string url, string destPath, long expectedSize, ITransferObserver observer, CancelToken token, int maxRetries)
        {
            TransferResult result = new TransferResult();
            result.Path = destPath;
            if (string.IsNullOrEmpty(url)) { result.Message = Loc.T("Err_NoUrl"); return result; }
            if (token == null) token = new CancelToken();

            string dir = System.IO.Path.GetDirectoryName(destPath);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            string part = destPath + ".part";
            int attempt = 0;
            bool rangeReset = false;

            while (true)
            {
                if (token.IsCancelled) return Cancelled(result);

                long existing = File.Exists(part) ? new FileInfo(part).Length : 0;
                if (expectedSize > 0 && existing > expectedSize) { TryDelete(part); existing = 0; }
                if (expectedSize > 0 && existing == expectedSize)
                {
                    Finish(part, destPath, result);
                    if (observer != null) { observer.OnStart(expectedSize, expectedSize); observer.OnProgress(expectedSize, expectedSize, 0); observer.OnFinish(true, result.Bytes); }
                    return result;
                }

                HttpWebRequest req = null;
                HttpWebResponse resp = null;
                bool retry = false;
                try
                {
                    req = (HttpWebRequest)WebRequest.Create(url);
                    req.Method = "GET";
                    req.UserAgent = UserAgent;
                    req.AllowAutoRedirect = true;
                    req.Timeout = 30000;
                    req.ReadWriteTimeout = 60000;
                    req.KeepAlive = true;
                    if (existing > 0) req.AddRange(existing);
                    token.Attach(req);

                    resp = (HttpWebResponse)req.GetResponse();
                    int code = (int)resp.StatusCode;
                    result.StatusCode = code;
                    bool append = existing > 0 && code == 206;
                    if (!append) existing = 0;
                    long len = resp.ContentLength;
                    long total = len >= 0 ? existing + len : (expectedSize > 0 ? expectedSize : -1);
                    result.Resumed = append;
                    if (observer != null) observer.OnStart(total, existing);

                    long done = existing;
                    using (Stream rs = resp.GetResponseStream())
                    using (FileStream fs = new FileStream(part, append ? FileMode.Append : FileMode.Create, FileAccess.Write, FileShare.Read, 1 << 20))
                    {
                        byte[] buf = new byte[1 << 18];
                        Stopwatch sw = Stopwatch.StartNew();
                        long lastTick = 0, lastBytes = done;
                        double speed = 0;
                        int n;
                        while ((n = rs.Read(buf, 0, buf.Length)) > 0)
                        {
                            if (token.IsCancelled) throw new OperationCanceledException();
                            fs.Write(buf, 0, n);
                            done += n;
                            long now = sw.ElapsedMilliseconds;
                            if (now - lastTick >= 150)
                            {
                                double inst = (done - lastBytes) * 1000.0 / Math.Max(1, now - lastTick);
                                speed = speed <= 0 ? inst : speed * 0.75 + inst * 0.25;
                                lastTick = now;
                                lastBytes = done;
                                if (observer != null) observer.OnProgress(done, total, speed);
                            }
                        }
                        fs.Flush();
                        if (observer != null) observer.OnProgress(done, total, speed);
                    }
                    if (total > 0 && done < total) throw new IOException(Loc.F("Err_Incomplete", done, total));

                    Finish(part, destPath, result);
                    if (observer != null) observer.OnFinish(true, result.Bytes);
                    return result;
                }
                catch (OperationCanceledException)
                {
                    return Cancelled(result);
                }
                catch (WebException wex)
                {
                    if (token.IsCancelled || wex.Status == WebExceptionStatus.RequestCanceled) return Cancelled(result);
                    HttpWebResponse hr = wex.Response as HttpWebResponse;
                    int code = 0;
                    if (hr != null) { try { code = (int)hr.StatusCode; } catch { } try { hr.Close(); } catch { } }
                    result.StatusCode = code;
                    if (code == 416 && !rangeReset) { TryDelete(part); rangeReset = true; continue; }
                    result.Message = code > 0 ? ("HTTP " + code.ToString(CultureInfo.InvariantCulture)) : wex.Message;
                    bool transient = code == 0 || code == 408 || code == 429 || code >= 500;
                    retry = transient && attempt < maxRetries;
                    if (!retry) { if (observer != null) observer.OnFinish(false, 0); return result; }
                }
                catch (IOException ioex)
                {
                    if (token.IsCancelled) return Cancelled(result);
                    result.Message = ioex.Message;
                    retry = attempt < maxRetries;
                    if (!retry) { if (observer != null) observer.OnFinish(false, 0); return result; }
                }
                catch (Exception ex)
                {
                    if (token.IsCancelled) return Cancelled(result);
                    result.Message = ex.Message;
                    if (observer != null) observer.OnFinish(false, 0);
                    return result;
                }
                finally
                {
                    token.Detach();
                    if (resp != null) { try { resp.Close(); } catch { } }
                }

                attempt++;
                int waitMs = attempt == 1 ? 1500 : (attempt == 2 ? 4000 : 8000);
                if (!Sleep(waitMs, token)) return Cancelled(result);
            }
        }

        private static TransferResult Cancelled(TransferResult r)
        {
            r.Cancelled = true;
            r.Success = false;
            r.Message = Loc.T("Job_Cancelled");
            return r;
        }

        private static void Finish(string part, string dest, TransferResult r)
        {
            if (File.Exists(dest)) File.Delete(dest);
            File.Move(part, dest);
            r.Bytes = new FileInfo(dest).Length;
            r.Success = true;
            r.Message = "OK";
        }

        public static bool Sleep(int milliseconds, CancelToken token)
        {
            Stopwatch sw = Stopwatch.StartNew();
            while (sw.ElapsedMilliseconds < milliseconds)
            {
                if (token != null && token.IsCancelled) return false;
                Thread.Sleep(100);
            }
            return token == null || !token.IsCancelled;
        }

        public static void TryDelete(string path)
        {
            try { if (File.Exists(path)) File.Delete(path); } catch { }
        }

        public static string HashFile(string path, string algorithm, CancelToken token, ITransferObserver observer)
        {
            HashAlgorithm h = string.Equals(algorithm, "SHA256", StringComparison.OrdinalIgnoreCase) ? (HashAlgorithm)SHA256.Create() : (HashAlgorithm)SHA1.Create();
            try
            {
                using (FileStream fs = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 20))
                {
                    byte[] buf = new byte[1 << 20];
                    long total = fs.Length, done = 0;
                    Stopwatch sw = Stopwatch.StartNew();
                    long lastTick = 0;
                    if (observer != null) observer.OnStart(total, 0);
                    int n;
                    while ((n = fs.Read(buf, 0, buf.Length)) > 0)
                    {
                        if (token != null && token.IsCancelled) return null;
                        h.TransformBlock(buf, 0, n, null, 0);
                        done += n;
                        if (observer != null && sw.ElapsedMilliseconds - lastTick >= 150)
                        {
                            lastTick = sw.ElapsedMilliseconds;
                            observer.OnProgress(done, total, 0);
                        }
                    }
                    h.TransformFinalBlock(buf, 0, 0);
                    StringBuilder sb = new StringBuilder(h.Hash.Length * 2);
                    foreach (byte b in h.Hash) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
                    return sb.ToString();
                }
            }
            finally
            {
                h.Dispose();
            }
        }

        // Copies a local file through a .part file (see CopyStream).
        public static TransferResult CopyFile(string sourcePath, string destPath, long expectedSize, string expectedSha1, ITransferObserver observer, CancelToken token)
        {
            if (string.IsNullOrEmpty(sourcePath) || !File.Exists(sourcePath))
            {
                TransferResult r = new TransferResult();
                r.Path = destPath;
                r.Message = Loc.F("Err_NoSource", sourcePath);
                return r;
            }
            FileStream src;
            try
            {
                src = new FileStream(sourcePath, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 20);
            }
            catch (Exception ex)
            {
                TransferResult r = new TransferResult();
                r.Path = destPath;
                r.Message = ex.Message;
                return r;
            }
            using (src)
            {
                return CopyStream(src, src.Length, destPath, expectedSize, expectedSha1, observer, token);
            }
        }

        // Writes a read stream (local file or .bin archive entry) to destPath through a .part file and hashes
        // the bytes on the way; the result is kept only when the size and (if given) the SHA-1 match.
        // Progress and cancellation work as in Download. The caller disposes the source stream.
        public static TransferResult CopyStream(Stream source, long sourceLength, string destPath, long expectedSize, string expectedSha1, ITransferObserver observer, CancelToken token)
        {
            TransferResult result = new TransferResult();
            result.Path = destPath;
            if (token == null) token = new CancelToken();
            string part = destPath + ".part";
            bool started = false;
            try
            {
                string dir = System.IO.Path.GetDirectoryName(destPath);
                if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
                string hex;
                long done = 0;
                long total = sourceLength > 0 ? sourceLength : expectedSize;
                using (SHA1 h = SHA1.Create())
                {
                    using (FileStream dst = new FileStream(part, FileMode.Create, FileAccess.Write, FileShare.None, 1 << 20))
                    {
                        if (observer != null) observer.OnStart(total, 0);
                        started = true;
                        byte[] buf = new byte[1 << 20];
                        Stopwatch sw = Stopwatch.StartNew();
                        long lastTick = 0, lastBytes = 0;
                        double speed = 0;
                        int n;
                        while ((n = source.Read(buf, 0, buf.Length)) > 0)
                        {
                            if (token.IsCancelled) throw new OperationCanceledException();
                            h.TransformBlock(buf, 0, n, null, 0);
                            dst.Write(buf, 0, n);
                            done += n;
                            long now = sw.ElapsedMilliseconds;
                            if (now - lastTick >= 150)
                            {
                                double inst = (done - lastBytes) * 1000.0 / Math.Max(1, now - lastTick);
                                speed = speed <= 0 ? inst : speed * 0.75 + inst * 0.25;
                                lastTick = now;
                                lastBytes = done;
                                if (observer != null) observer.OnProgress(done, total, speed);
                            }
                        }
                        dst.Flush();
                        if (observer != null) observer.OnProgress(done, total, speed);
                    }
                    h.TransformFinalBlock(new byte[0], 0, 0);
                    StringBuilder sb = new StringBuilder(40);
                    foreach (byte b in h.Hash) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
                    hex = sb.ToString();
                }
                if (expectedSize > 0 && done != expectedSize) throw new IOException(Loc.F("Err_Incomplete", done, expectedSize));
                if (!string.IsNullOrEmpty(expectedSha1) && !string.Equals(hex, expectedSha1.Trim(), StringComparison.OrdinalIgnoreCase))
                    throw new IOException(Loc.T("Err_Hash"));
                Finish(part, destPath, result);
                if (observer != null) observer.OnFinish(true, result.Bytes);
                return result;
            }
            catch (OperationCanceledException)
            {
                TryDelete(part);
                return Cancelled(result);
            }
            catch (InvalidDataException ex)
            {
                // Damaged .bin archive entry
                TryDelete(part);
                result.Message = Loc.F("Err_Damaged", ex.Message);
                if (observer != null && started) observer.OnFinish(false, 0);
                return result;
            }
            catch (Exception ex)
            {
                TryDelete(part);
                Exception inner = ex;
                while (inner.InnerException != null && !(inner is IOException)) inner = inner.InnerException;
                result.Message = inner.Message;
                if (observer != null && started) observer.OnFinish(false, 0);
                return result;
            }
        }

        // SHA-1 / SHA-256 of a read stream; null when cancelled. The caller disposes the stream.
        public static string HashStream(Stream source, long length, string algorithm, CancelToken token, ITransferObserver observer)
        {
            HashAlgorithm h = string.Equals(algorithm, "SHA256", StringComparison.OrdinalIgnoreCase) ? (HashAlgorithm)SHA256.Create() : (HashAlgorithm)SHA1.Create();
            try
            {
                byte[] buf = new byte[1 << 20];
                long done = 0;
                Stopwatch sw = Stopwatch.StartNew();
                long lastTick = 0;
                if (observer != null) observer.OnStart(length, 0);
                int n;
                while ((n = source.Read(buf, 0, buf.Length)) > 0)
                {
                    if (token != null && token.IsCancelled) return null;
                    h.TransformBlock(buf, 0, n, null, 0);
                    done += n;
                    if (observer != null && sw.ElapsedMilliseconds - lastTick >= 150)
                    {
                        lastTick = sw.ElapsedMilliseconds;
                        observer.OnProgress(done, length, 0);
                    }
                }
                h.TransformFinalBlock(buf, 0, 0);
                StringBuilder sb = new StringBuilder(h.Hash.Length * 2);
                foreach (byte b in h.Hash) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
                return sb.ToString();
            }
            finally
            {
                h.Dispose();
            }
        }
    }

    // UUP JSON duplicate-key remover (port of [DPI]::DeduplicateJsonKeys)
    public static class JsonTools
    {
        private static readonly Regex FileEntryRegex = new Regex(@"""([^""]+\.(?:cab|esd|appx|appxbundle|msix|wim|psf|msu|xml|txt))""\s*:\s*\{[^{}]*\}", RegexOptions.IgnoreCase | RegexOptions.Compiled);

        public static string DeduplicateJsonKeys(string json, string lang = null)
        {
            if (string.IsNullOrEmpty(json)) return json;
            int filesIdx = json.IndexOf("\"files\":", StringComparison.Ordinal);
            if (filesIdx < 0) return json;
            int braceStart = json.IndexOf('{', filesIdx);
            if (braceStart < 0) return json;
            int depth = 0;
            int braceEnd = -1;
            for (int i = braceStart; i < json.Length; i++)
            {
                char c = json[i];
                if (c == '{') depth++;
                else if (c == '}')
                {
                    depth--;
                    if (depth == 0) { braceEnd = i; break; }
                }
            }
            if (braceEnd < 0) return json;
            string filesBlock = json.Substring(braceStart, braceEnd - braceStart + 1);
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            List<string> kept = new List<string>();
            foreach (Match m in FileEntryRegex.Matches(filesBlock))
            {
                string k = m.Groups[1].Value;
                if (!string.IsNullOrEmpty(lang))
                {
                    if (k.IndexOf(lang, StringComparison.OrdinalIgnoreCase) < 0 &&
                        k.IndexOf("LanguageExperiencePack", StringComparison.OrdinalIgnoreCase) < 0)
                    {
                        continue;
                    }
                }
                if (seen.Add(k)) kept.Add(m.Value);
            }
            return json.Substring(0, braceStart) + "{" + string.Join(",", kept) + "}" + json.Substring(braceEnd + 1);
        }
    }

    // Simple key=value settings file (%APPDATA%\WinPEOCs\gui.settings)
    public sealed class AppSettings
    {
        private readonly Dictionary<string, string> _values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        private readonly object _gate = new object();

        public string FilePath { get; private set; }

        public static AppSettings Load(string path)
        {
            AppSettings s = new AppSettings();
            s.FilePath = path;
            try
            {
                if (!string.IsNullOrEmpty(path) && File.Exists(path))
                {
                    foreach (string raw in File.ReadAllLines(path, Encoding.UTF8))
                    {
                        string line = raw.Trim();
                        if (line.Length == 0 || line[0] == '#') continue;
                        int eq = line.IndexOf('=');
                        if (eq <= 0) continue;
                        s._values[line.Substring(0, eq).Trim()] = line.Substring(eq + 1).Trim();
                    }
                }
            }
            catch { }
            return s;
        }

        public string Get(string key, string defaultValue)
        {
            lock (_gate)
            {
                string v;
                return _values.TryGetValue(key, out v) && v != null ? v : defaultValue;
            }
        }

        public bool GetBool(string key, bool defaultValue)
        {
            string v = Get(key, null);
            bool b;
            return v != null && bool.TryParse(v, out b) ? b : defaultValue;
        }

        public double GetDouble(string key, double defaultValue)
        {
            string v = Get(key, null);
            double d;
            return v != null && double.TryParse(v, NumberStyles.Float, CultureInfo.InvariantCulture, out d) ? d : defaultValue;
        }

        public void Set(string key, object value)
        {
            lock (_gate) { _values[key] = Convert.ToString(value, CultureInfo.InvariantCulture); }
        }

        public void Save()
        {
            if (string.IsNullOrEmpty(FilePath)) return;
            try
            {
                string dir = System.IO.Path.GetDirectoryName(FilePath);
                if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
                List<string> lines = new List<string>();
                lines.Add("# WinPE OCs arayuz ayarlari");
                lock (_gate)
                {
                    List<string> keys = new List<string>(_values.Keys);
                    keys.Sort(StringComparer.OrdinalIgnoreCase);
                    foreach (string k in keys) lines.Add(k + "=" + _values[k]);
                }
                File.WriteAllLines(FilePath, lines.ToArray(), new UTF8Encoding(false));
            }
            catch { }
        }
    }

    // Native Windows APIs
    public static class Native
    {
        [DllImport("kernel32.dll")]
        private static extern IntPtr GetConsoleWindow();

        [DllImport("user32.dll")]
        private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

        [DllImport("user32.dll")]
        private static extern bool IsWindowVisible(IntPtr hWnd);

        [DllImport("kernel32.dll", SetLastError = true)]
        private static extern uint GetConsoleProcessList(uint[] processList, uint processCount);

        [DllImport("user32.dll")]
        private static extern bool SetProcessDPIAware();

        [DllImport("dwmapi.dll")]
        private static extern int DwmSetWindowAttribute(IntPtr hwnd, int attribute, ref int value, int size);

        public static bool HasConsole
        {
            get { try { return GetConsoleWindow() != IntPtr.Zero; } catch { return false; } }
        }

        public static bool IsConsoleVisible
        {
            get
            {
                try { IntPtr h = GetConsoleWindow(); return h != IntPtr.Zero && IsWindowVisible(h); }
                catch { return false; }
            }
        }

        public static int ConsoleProcessCount
        {
            get
            {
                try { uint[] arr = new uint[32]; return (int)GetConsoleProcessList(arr, 32); }
                catch { return -1; }
            }
        }

        public static void ShowConsole(bool show)
        {
            try
            {
                IntPtr h = GetConsoleWindow();
                if (h != IntPtr.Zero) ShowWindow(h, show ? 5 : 0);
            }
            catch { }
        }

        public static void EnableDpiAwareness()
        {
            try { SetProcessDPIAware(); } catch { }
        }

        public static bool IsWindows11
        {
            get
            {
                try { return Environment.OSVersion.Version.Major >= 10 && Environment.OSVersion.Version.Build >= 22000; }
                catch { return false; }
            }
        }

        // Dark title bar, rounded corners and border color (Windows 10 2004+ / 11)
        public static void ApplyWindowTheme(IntPtr hwnd, int borderColorRef)
        {
            if (hwnd == IntPtr.Zero) return;
            try
            {
                int on = 1;
                if (DwmSetWindowAttribute(hwnd, 20, ref on, 4) != 0) DwmSetWindowAttribute(hwnd, 19, ref on, 4);
                int round = 2;
                DwmSetWindowAttribute(hwnd, 33, ref round, 4);
                int color = borderColorRef;
                DwmSetWindowAttribute(hwnd, 34, ref color, 4);
            }
            catch { }
        }
    }
}

// WinPEOCs.UI - WPF layer: window on its own STA thread, view models,
// thread-safe request queue to the PowerShell engine, custom window chrome.

namespace WinPEOCs
{
    public sealed class RelayCommand : ICommand
    {
        private readonly Action<object> _execute;
        private readonly Func<object, bool> _canExecute;

        public RelayCommand(Action<object> execute) : this(execute, null) { }

        public RelayCommand(Action<object> execute, Func<object, bool> canExecute)
        {
            _execute = execute;
            _canExecute = canExecute;
        }

        public event EventHandler CanExecuteChanged
        {
            add { CommandManager.RequerySuggested += value; }
            remove { CommandManager.RequerySuggested -= value; }
        }

        public bool CanExecute(object parameter)
        {
            try { return _canExecute == null || _canExecute(parameter); }
            catch { return false; }
        }

        public void Execute(object parameter)
        {
            if (CanExecute(parameter)) _execute(parameter);
        }
    }

    // Request sent from the UI to the PowerShell engine
    public sealed class UiRequest
    {
        private static int _seq;

        public UiRequest(string kind)
        {
            Id = Interlocked.Increment(ref _seq);
            Kind = kind;
            Args = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        }

        public int Id { get; private set; }
        public string Kind { get; private set; }
        public string Page { get; set; }
        public Dictionary<string, object> Args { get; private set; }
        public bool IsCompleted { get; internal set; }

        public object Get(string key)
        {
            object v;
            return Args.TryGetValue(key, out v) ? v : null;
        }

        public string GetString(string key)
        {
            object v = Get(key);
            return v == null ? null : Convert.ToString(v, CultureInfo.InvariantCulture);
        }

        public bool GetBool(string key)
        {
            object v = Get(key);
            return v is bool && (bool)v;
        }

        public PackageItem[] GetItems(string key)
        {
            PackageItem[] items = Get(key) as PackageItem[];
            return items ?? new PackageItem[0];
        }

        public override string ToString() { return Kind + "#" + Id.ToString(CultureInfo.InvariantCulture); }
    }

    public sealed class UiStartOptions
    {
        public string ThemeXaml;
        public string LayoutXaml;
        public string AppVersion;
        public string AppRoot;
        public string DefaultOutputRoot;
        public string ManifestDir;
        public string SettingsPath;
        public string LogDir;
        public string RuntimeInfo;
        public string[] UupRows;
        public string[] Regions;
        public string[] PeVersions;
        public string[] OcDependencies;
        public bool ForceShowConsole;
        public bool HideConsoleOnStart;
        public bool Offline;
    }

    internal sealed class TransferObserver : ITransferObserver
    {
        private readonly UiHost _host;
        private readonly PackageItem _item;
        private readonly bool _batch;

        public TransferObserver(UiHost host, PackageItem item, bool batch)
        {
            _host = host;
            _item = item;
            _batch = batch;
        }

        public void OnStart(long total, long resumedFrom)
        {
            if (_item != null && _batch) _item.SetStateCore(ItemState.Downloading, null, total > 0 ? resumedFrom * 100.0 / total : -1);
            _host.OnTransferStart(total, resumedFrom, _batch);
        }

        public void OnProgress(long done, long total, double bytesPerSecond)
        {
            if (_item != null && total > 0 && _batch) _item.SetProgress(done * 100.0 / total);
            _host.OnTransferProgress(done, total, bytesPerSecond, _batch);
        }

        public void OnFinish(bool success, long bytes)
        {
            _host.OnTransferFinish(success, bytes, _batch);
        }
    }

    // UI host: runs the window on its own STA thread. The PowerShell main thread takes requests
    // with Next(); every feedback method is thread-safe (posted to the Dispatcher).
    public sealed class UiHost
    {
        private readonly BlockingCollection<UiRequest> _queue = new BlockingCollection<UiRequest>();
        private readonly ManualResetEventSlim _ready = new ManualResetEventSlim(false);
        private readonly CancelToken _cancel = new CancelToken();
        private readonly object _xferGate = new object();
        private readonly object _logGate = new object();
        private readonly Stopwatch _clock = Stopwatch.StartNew();
        private Thread _thread;
        private volatile bool _closed;
        private Exception _startError;
        private long _batchTotal, _batchDone, _curDone, _lastPost;
        private string _logFile;
        private bool _consoleVisibleAtStart;

        public static UiHost Current { get; private set; }
        public UiStartOptions Options { get; private set; }
        public AppSettings Settings { get; private set; }
        public MainViewModel ViewModel { get; private set; }
        public MainWindow Window { get; private set; }
        public Dispatcher Dispatcher { get; private set; }
        public CancelToken Cancel { get { return _cancel; } }
        public bool IsCancelRequested { get { return _cancel.IsCancelled; } }
        public bool IsClosed { get { return _closed; } }

        public static UiHost Start(UiStartOptions options)
        {
            if (options == null) throw new ArgumentNullException("options");
            UiHost host = new UiHost();
            host.Options = options;
            Current = host;
            host._thread = new Thread(host.ThreadMain);
            host._thread.SetApartmentState(ApartmentState.STA);
            host._thread.IsBackground = true;
            host._thread.Name = "WinPEOCs-UI";
            host._thread.Start();
            host._ready.Wait();
            if (host._startError != null) throw new InvalidOperationException(host._startError.Message, host._startError);
            return host;
        }

        private void ThreadMain()
        {
            try
            {
                Native.EnableDpiAwareness();
                Dispatcher = Dispatcher.CurrentDispatcher;
                DispatcherSynchronizationContext ctx = new DispatcherSynchronizationContext(Dispatcher);
                SynchronizationContext.SetSynchronizationContext(ctx);
                UiThread.Initialize(ctx);
                Dispatcher.UnhandledException += OnDispatcherUnhandledException;

                Settings = AppSettings.Load(Options.SettingsPath);
                Loc.SetLanguage(Settings.Get("UiLang", "tr"));
                PrepareLogFile();

                _consoleVisibleAtStart = Native.IsConsoleVisible;
                if (Options.ForceShowConsole) Native.ShowConsole(true);
                else if (Options.HideConsoleOnStart && _consoleVisibleAtStart && !Settings.GetBool("ShowConsole", false)) Native.ShowConsole(false);

                ViewModel = new MainViewModel(this);
                Window = new MainWindow(this, ViewModel);
                Window.Closed += OnWindowClosed;
                Window.Show();
                Window.Activate();
            }
            catch (Exception ex)
            {
                _startError = ex;
                _ready.Set();
                return;
            }
            _ready.Set();
            try { Dispatcher.Run(); }
            catch (Exception ex) { WriteFileLog(new LogEntry("error", "UI: " + ex)); }
            _closed = true;
        }

        private void OnWindowClosed(object sender, EventArgs e)
        {
            _closed = true;
            _cancel.Cancel();
            try { Settings.Save(); } catch { }
            _queue.Add(new UiRequest("Exit"));
            Dispatcher.BeginInvokeShutdown(DispatcherPriority.Background);
        }

        private void OnDispatcherUnhandledException(object sender, DispatcherUnhandledExceptionEventArgs e)
        {
            e.Handled = true;
            try
            {
                LogEntry entry = new LogEntry("error", "UI: " + e.Exception.Message);
                WriteFileLog(new LogEntry("error", "UI: " + e.Exception));
                if (ViewModel != null)
                {
                    ViewModel.LogVm.Add(entry);
                    ViewModel.Dialog.ShowMessage("error", Loc.T("Msg_ErrorTitle"), e.Exception.Message);
                }
            }
            catch { }
        }

        // --- Request queue ---
        public UiRequest Next(int timeoutMs)
        {
            UiRequest r;
            if (_queue.TryTake(out r, timeoutMs)) return r;
            return null;
        }

        internal bool Submit(UiRequest request, string page, string busyText)
        {
            if (request == null || ViewModel.IsBusy || _closed) return false;
            _cancel.Reset();
            request.Page = page;
            ViewModel.BeginBusy(page, busyText);
            _queue.Add(request);
            return true;
        }

        public void Done(UiRequest request, bool ok, string message, string level)
        {
            if (request != null) request.IsCompleted = true;
            string lvl = string.IsNullOrEmpty(level) ? (ok ? "ok" : "error") : level;
            if (!string.IsNullOrEmpty(message)) Log(lvl, message);
            UiThread.Post(delegate { ViewModel.EndBusy(request, ok, message, lvl); });
        }

        public void Fail(UiRequest request, string message)
        {
            Done(request, false, Loc.F("Job_Failed") + ": " + message, "error");
            ShowMessage("error", Loc.T("Msg_ErrorTitle"), message);
        }

        // --- Feedback (called from the PowerShell thread) ---
        public void Log(string level, string message)
        {
            LogEntry entry = new LogEntry(level, message);
            WriteFileLog(entry);
            UiThread.Post(delegate { if (ViewModel != null) ViewModel.LogVm.Add(entry); });
        }

        public void Status(string text)
        {
            Status(text, "busy");
        }

        public void Status(string text, string level)
        {
            UiThread.Post(delegate { ViewModel.SetStatus(text, level); });
        }

        public void Progress(double percent)
        {
            UiThread.Post(delegate { ViewModel.SetProgress(percent); });
        }

        public void Detail(string text)
        {
            UiThread.Post(delegate { ViewModel.ProgressDetail = text ?? string.Empty; });
        }

        public void ShowMessage(string kind, string title, string message)
        {
            UiThread.Post(delegate { ViewModel.Dialog.ShowMessage(kind, title, message); });
        }

        public bool Confirm(string kind, string title, string message, string okText, string note, KeyValueRow[] details)
        {
            System.Threading.ManualResetEventSlim ev = new System.Threading.ManualResetEventSlim(false);
            bool result = false;
            UiThread.Post(delegate
            {
                ViewModel.Dialog.Confirm(kind, title, message, details, note, okText, delegate(bool ok)
                {
                    result = ok;
                    ev.Set();
                });
            });
            while (!ev.Wait(200))
            {
                if (_closed) return false;
            }
            return result;
        }

        public bool Confirm(string kind, string title, string message, string okText, string note)
        {
            return Confirm(kind, title, message, okText, note, null);
        }

        public void SetLangItems(PackageItem[] items, string info)
        {
            UiThread.Post(delegate { ViewModel.Lang.SetItems(items, info); });
        }

        public void SetPeItems(PackageItem[] items, string[] containers, string info, string buildInfo)
        {
            UiThread.Post(delegate { ViewModel.Pe.SetItems(items, containers, info, buildInfo); });
        }

        public void SetPeAvailability(string[] triples)
        {
            UiThread.Post(delegate { ViewModel.Pe.SetAvailability(triples); });
        }

        public void SetEngineInfo(string catalogInfo, string indexInfo, string runtimeInfo)
        {
            UiThread.Post(delegate { ViewModel.Settings.SetEngineInfo(catalogInfo, indexInfo, runtimeInfo); });
        }

        public void EngineReady(double seconds)
        {
            UiThread.Post(delegate { ViewModel.OnEngineReady(seconds); });
        }

        public string T(string key) { return Loc.T(key); }

        public string F(string key, object[] args) { return Loc.F(key, args); }

        // --- Transfer progress ---
        public void BeginTransfer(long totalBytes)
        {
            lock (_xferGate) { _batchTotal = Math.Max(0, totalBytes); _batchDone = 0; _curDone = 0; }
            _lastPost = 0;
            UiThread.Post(delegate { ViewModel.SetProgress(0); ViewModel.ProgressDetail = string.Empty; });
        }

        public void AddTransferred(long bytes)
        {
            double pct;
            lock (_xferGate)
            {
                _batchDone += Math.Max(0, bytes);
                pct = _batchTotal > 0 ? Math.Min(100, _batchDone * 100.0 / _batchTotal) : -1;
            }
            if (pct >= 0) UiThread.Post(delegate { ViewModel.SetProgress(pct); });
        }

        public ITransferObserver Observer(PackageItem item)
        {
            return new TransferObserver(this, item, true);
        }

        public ITransferObserver HashObserver(PackageItem item)
        {
            return new TransferObserver(this, item, false);
        }

        internal void OnTransferStart(long total, long resumedFrom, bool batch)
        {
            if (!batch) return;
            lock (_xferGate) { _curDone = resumedFrom; }
        }

        internal void OnTransferProgress(long done, long total, double bytesPerSecond, bool batch)
        {
            long now = _clock.ElapsedMilliseconds;
            bool final = total > 0 && done >= total;
            if (!final && now - _lastPost < 120) return;
            _lastPost = now;
            double pct;
            string detail;
            if (batch)
            {
                lock (_xferGate)
                {
                    _curDone = done;
                    long overallDone = _batchDone + done;
                    if (_batchTotal > 0)
                    {
                        long overallTotal = Math.Max(_batchTotal, overallDone);
                        pct = overallDone * 100.0 / overallTotal;
                        double eta = bytesPerSecond > 1 ? (overallTotal - overallDone) / bytesPerSecond : -1;
                        detail = Loc.F("Prog_Detail", Fmt.Percent(pct), Fmt.Size(done), total > 0 ? Fmt.Size(total) : "?", Fmt.Speed(bytesPerSecond), Fmt.Duration(eta));
                    }
                    else
                    {
                        pct = total > 0 ? done * 100.0 / total : -1;
                        double eta = bytesPerSecond > 1 && total > 0 ? (total - done) / bytesPerSecond : -1;
                        detail = Loc.F("Prog_Detail", pct >= 0 ? Fmt.Percent(pct) : "…", Fmt.Size(done), total > 0 ? Fmt.Size(total) : "?", Fmt.Speed(bytesPerSecond), Fmt.Duration(eta));
                    }
                }
            }
            else
            {
                pct = -2;
                detail = total > 0 ? Fmt.Percent(done * 100.0 / total) + " · " + Fmt.Size(done) + " / " + Fmt.Size(total) : Fmt.Size(done);
            }
            UiThread.Post(delegate
            {
                if (pct >= 0) ViewModel.SetProgress(pct);
                else if (pct == -1) ViewModel.SetProgress(-1);
                ViewModel.ProgressDetail = detail;
            });
        }

        internal void OnTransferFinish(bool success, long bytes, bool batch)
        {
            if (!batch) return;
            lock (_xferGate)
            {
                if (success) _batchDone += bytes;
                _curDone = 0;
            }
        }

        // --- Console ---
        public void SetConsoleVisible(bool visible)
        {
            Native.ShowConsole(visible);
        }

        // --- Shutdown ---
        public void Shutdown()
        {
            try
            {
                if (Dispatcher != null && !Dispatcher.HasShutdownStarted)
                {
                    Dispatcher.Invoke(new Action(delegate
                    {
                        if (Window != null && Window.IsVisible) Window.ForceClose();
                    }));
                }
            }
            catch { }
            try { if (_thread != null) _thread.Join(3000); } catch { }
            try { if (Settings != null) Settings.Save(); } catch { }
            // Leave the console visible when started from the user's own terminal
            try { if (_consoleVisibleAtStart && !Options.HideConsoleOnStart) Native.ShowConsole(true); } catch { }
        }

        // --- File log ---
        private void PrepareLogFile()
        {
            try
            {
                if (string.IsNullOrEmpty(Options.LogDir)) return;
                Directory.CreateDirectory(Options.LogDir);
                _logFile = System.IO.Path.Combine(Options.LogDir, "WinPEOCs_" + DateTime.Now.ToString("yyyyMMdd", CultureInfo.InvariantCulture) + ".log");
            }
            catch { _logFile = null; }
        }

        internal string LogFile { get { return _logFile; } }

        private void WriteFileLog(LogEntry entry)
        {
            string file = _logFile;
            if (string.IsNullOrEmpty(file)) return;
            lock (_logGate)
            {
                try { File.AppendAllText(file, entry.ToString() + Environment.NewLine, new UTF8Encoding(false)); } catch { }
            }
        }
    }

    // In-window dialog (message / confirmation), queued
    public sealed class DialogViewModel : ObservableObject
    {
        private sealed class Pending
        {
            public string Kind, Title, Message, Note, OkText;
            public bool HasCancel;
            public KeyValueRow[] Details;
            public Action<bool> Callback;
        }

        private readonly Queue<Pending> _queue = new Queue<Pending>();
        private readonly ObservableCollection<KeyValueRow> _details = new ObservableCollection<KeyValueRow>();
        private Pending _current;

        public DialogViewModel()
        {
            OkCommand = new RelayCommand(p => Close(true), p => _current != null);
            CancelCommand = new RelayCommand(p => Close(false), p => _current != null);
        }

        public event EventHandler Opened;

        public ICommand OkCommand { get; private set; }
        public ICommand CancelCommand { get; private set; }
        public bool IsOpen { get { return _current != null; } }
        public Visibility Visibility { get { return _current != null ? Visibility.Visible : Visibility.Collapsed; } }
        public string Kind { get { return _current != null ? _current.Kind : "info"; } }
        public string Title { get { return _current != null ? _current.Title : string.Empty; } }
        public string Message { get { return _current != null ? _current.Message : string.Empty; } }
        public string Note { get { return _current != null ? _current.Note : string.Empty; } }
        public Visibility NoteVisibility { get { return _current != null && !string.IsNullOrEmpty(_current.Note) ? Visibility.Visible : Visibility.Collapsed; } }
        public string OkText { get { return _current != null ? _current.OkText : Loc.T("Btn_Ok"); } }
        public string CancelText { get { return Loc.T("Btn_Cancel"); } }
        public Visibility CancelVisibility { get { return _current != null && _current.HasCancel ? Visibility.Visible : Visibility.Collapsed; } }
        public ObservableCollection<KeyValueRow> Details { get { return _details; } }
        public Visibility DetailsVisibility { get { return _details.Count > 0 ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility MessageVisibility { get { return string.IsNullOrEmpty(Message) ? Visibility.Collapsed : Visibility.Visible; } }

        public string Glyph
        {
            get
            {
                switch (Kind)
                {
                    case "error": return "\uEA39";
                    case "warn": return "\uE7BA";
                    case "download": return "\uE896";
                    case "clean": return "\uE74D";
                    case "ok": return "\uE73E";
                    default: return "\uE946";
                }
            }
        }

        public void ShowMessage(string kind, string title, string message)
        {
            Pending p = new Pending();
            p.Kind = string.IsNullOrEmpty(kind) ? "info" : kind;
            p.Title = title;
            p.Message = message;
            p.OkText = Loc.T("Btn_Ok");
            p.HasCancel = false;
            Enqueue(p);
        }

        public void Confirm(string kind, string title, string message, KeyValueRow[] details, string note, string okText, Action<bool> callback)
        {
            Pending p = new Pending();
            p.Kind = string.IsNullOrEmpty(kind) ? "info" : kind;
            p.Title = title;
            p.Message = message;
            p.Details = details;
            p.Note = note;
            p.OkText = string.IsNullOrEmpty(okText) ? Loc.T("Btn_Ok") : okText;
            p.HasCancel = true;
            p.Callback = callback;
            Enqueue(p);
        }

        private void Enqueue(Pending p)
        {
            _queue.Enqueue(p);
            if (_current == null) ShowNext();
        }

        private void ShowNext()
        {
            _current = _queue.Count > 0 ? _queue.Dequeue() : null;
            _details.Clear();
            if (_current != null && _current.Details != null)
            {
                foreach (KeyValueRow r in _current.Details) _details.Add(r);
            }
            RaiseMany("IsOpen", "Visibility", "Kind", "Title", "Message", "MessageVisibility", "Note", "NoteVisibility", "OkText", "CancelText", "CancelVisibility", "DetailsVisibility", "Glyph");
            CommandManager.InvalidateRequerySuggested();
            if (_current != null)
            {
                EventHandler h = Opened;
                if (h != null) h(this, EventArgs.Empty);
            }
        }

        private void Close(bool result)
        {
            Pending cur = _current;
            if (cur == null) return;
            ShowNext();
            if (cur.Callback != null) cur.Callback(result);
        }
    }

    // Log page
    public sealed class LogViewModel : ObservableObject
    {
        private readonly MainViewModel _main;
        private readonly UiHost _host;
        private readonly ObservableCollection<LogEntry> _entries = new ObservableCollection<LogEntry>();
        private int _unseen;
        private bool _unseenError;

        public LogViewModel(MainViewModel main, UiHost host)
        {
            _main = main;
            _host = host;
            CopyCommand = new RelayCommand(p => Copy(), p => _entries.Count > 0);
            ClearCommand = new RelayCommand(p => { _entries.Clear(); RaiseCounts(); }, p => _entries.Count > 0);
            OpenFolderCommand = new RelayCommand(p => MainViewModel.OpenInExplorer(_host.Options.LogDir));
        }

        public Loc L { get { return Loc.Instance; } }
        public ObservableCollection<LogEntry> Entries { get { return _entries; } }
        public ICommand CopyCommand { get; private set; }
        public ICommand ClearCommand { get; private set; }
        public ICommand OpenFolderCommand { get; private set; }
        public string CountText { get { return Loc.F("Log_Count", _entries.Count); } }
        public Visibility EmptyVisibility { get { return _entries.Count == 0 ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility BadgeVisibility { get { return _unseen > 0 && !_main.IsNavCollapsed ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility DotVisibility { get { return _unseen > 0 && _main.IsNavCollapsed ? Visibility.Visible : Visibility.Collapsed; } }
        public string BadgeText { get { return _unseen > 99 ? "99+" : _unseen.ToString(CultureInfo.InvariantCulture); } }
        public bool BadgeIsError { get { return _unseenError; } }

        internal void Add(LogEntry entry)
        {
            _entries.Add(entry);
            while (_entries.Count > 3000) _entries.RemoveAt(0);
            if (!_main.IsLogPage && (entry.Level == "error" || entry.Level == "warn"))
            {
                _unseen++;
                if (entry.Level == "error") _unseenError = true;
            }
            RaiseCounts();
        }

        internal void MarkSeen()
        {
            _unseen = 0;
            _unseenError = false;
            RaiseCounts();
        }

        internal void RaiseCounts()
        {
            RaiseMany("CountText", "EmptyVisibility", "BadgeVisibility", "DotVisibility", "BadgeText", "BadgeIsError");
        }

        private void Copy()
        {
            StringBuilder sb = new StringBuilder();
            foreach (LogEntry e in _entries) sb.AppendLine(e.ToString());
            if (MainViewModel.TrySetClipboard(sb.ToString())) _main.SetStatus(Loc.T("Log_Copied"), "ok");
        }
    }

    // Settings page
    public sealed class SettingsViewModel : ObservableObject
    {
        private readonly MainViewModel _main;
        private readonly UiHost _host;
        private string _outputRoot;
        private bool _skipExisting, _verifyHash, _keepCache, _autoDeps, _showConsole;
        private string _catalogInfo = "—", _indexInfo = "—", _runtimeInfo = "—", _manifestInfo = string.Empty;

        public SettingsViewModel(MainViewModel main, UiHost host)
        {
            _main = main;
            _host = host;
            AppSettings s = host.Settings;
            _outputRoot = NormalizeRoot(s.Get("OutputRoot", host.Options.DefaultOutputRoot));
            _skipExisting = s.GetBool("SkipExisting", true);
            _verifyHash = s.GetBool("VerifyHash", true);
            _keepCache = s.GetBool("KeepCache", false);
            _autoDeps = s.GetBool("AutoDeps", true);
            _showConsole = Native.IsConsoleVisible;
            _runtimeInfo = string.IsNullOrEmpty(host.Options.RuntimeInfo) ? "—" : host.Options.RuntimeInfo;

            BrowseCommand = new RelayCommand(p => Browse());
            OpenOutputCommand = new RelayCommand(p => MainViewModel.OpenInExplorer(OutputRoot));
            OpenManifestsCommand = new RelayCommand(p => MainViewModel.OpenInExplorer(ManifestDir));
            SelfTestCommand = new RelayCommand(p => SelfTest(), p => _main.IsIdle);
            RefreshManifestInfo();
        }

        public Loc L { get { return Loc.Instance; } }
        public ICommand BrowseCommand { get; private set; }
        public ICommand OpenOutputCommand { get; private set; }
        public ICommand OpenManifestsCommand { get; private set; }
        public ICommand SelfTestCommand { get; private set; }

        public string OutputRoot
        {
            get { return _outputRoot; }
            set
            {
                string v = NormalizeRoot(value);
                if (Set(ref _outputRoot, v)) { _host.Settings.Set("OutputRoot", v); _host.Settings.Save(); }
            }
        }

        public bool SkipExisting { get { return _skipExisting; } set { if (Set(ref _skipExisting, value)) Save("SkipExisting", value); } }
        public bool VerifyHash { get { return _verifyHash; } set { if (Set(ref _verifyHash, value)) Save("VerifyHash", value); } }
        public bool KeepCache { get { return _keepCache; } set { if (Set(ref _keepCache, value)) Save("KeepCache", value); } }

        public bool AutoDeps
        {
            get { return _autoDeps; }
            set { if (Set(ref _autoDeps, value)) { Save("AutoDeps", value); _main.Pe.RaiseAutoDeps(); } }
        }

        public bool ShowConsole
        {
            get { return _showConsole; }
            set
            {
                if (Set(ref _showConsole, value))
                {
                    Native.ShowConsole(value);
                    Save("ShowConsole", value);
                }
            }
        }

        public bool ConsoleAvailable { get { return Native.HasConsole; } }
        public bool IsTurkish { get { return !Loc.IsEnglish; } set { if (value) SetLanguage("tr"); } }
        public bool IsEnglish { get { return Loc.IsEnglish; } set { if (value) SetLanguage("en"); } }
        public string ManifestDir { get { return _host.Options.ManifestDir ?? string.Empty; } }
        public string ManifestInfo { get { return _manifestInfo; } }

        public Visibility OnlineVisibility { get { return _host.Options.Offline ? Visibility.Collapsed : Visibility.Visible; } }
        public string CatalogInfo { get { return _catalogInfo; } }
        public string IndexInfo { get { return _indexInfo; } }
        public string RuntimeInfo { get { return _runtimeInfo; } }

        internal void SetEngineInfo(string catalogInfo, string indexInfo, string runtimeInfo)
        {
            if (!string.IsNullOrEmpty(catalogInfo)) _catalogInfo = catalogInfo;
            if (!string.IsNullOrEmpty(indexInfo)) _indexInfo = indexInfo;
            if (!string.IsNullOrEmpty(runtimeInfo)) _runtimeInfo = runtimeInfo;
            RaiseMany("CatalogInfo", "IndexInfo", "RuntimeInfo");
        }

        internal void RefreshManifestInfo()
        {
            int count = 0;
            try
            {
                if (!string.IsNullOrEmpty(ManifestDir) && Directory.Exists(ManifestDir))
                {
                    // Offline edition: the repository folder holds the .bin archives
                    if (_host.Options.Offline) count = Directory.GetFiles(ManifestDir, "*.bin").Length;
                    else count = Directory.GetFiles(ManifestDir, "*.json").Length + Directory.GetFiles(ManifestDir, "*.xml").Length;
                }
            }
            catch { }
            _manifestInfo = Loc.F("Set_ManifestInfo", ManifestDir, count);
            Raise("ManifestInfo");
        }

        internal void RefreshLocalized()
        {
            RaiseMany("IsTurkish", "IsEnglish");
            RefreshManifestInfo();
        }

        private void SetLanguage(string lang)
        {
            Loc.SetLanguage(lang);
            _host.Settings.Set("UiLang", lang);
            _host.Settings.Save();
            RaiseMany("IsTurkish", "IsEnglish");
        }

        private void Save(string key, bool value)
        {
            _host.Settings.Set(key, value);
            _host.Settings.Save();
        }

        private void Browse()
        {
            try
            {
                string picked = FolderPicker.Pick(_host.Window, Loc.T("Set_Output"), OutputRoot);
                if (!string.IsNullOrEmpty(picked)) OutputRoot = picked;
            }
            catch (Exception ex)
            {
                _main.Dialog.ShowMessage("error", Loc.T("Msg_ErrorTitle"), Loc.F("Msg_FolderPickFail", ex.Message));
            }
        }

        private void SelfTest()
        {
            UiRequest req = new UiRequest("SelfTest");
            _host.Submit(req, "settings", Loc.T("Job_SelfTest"));
        }

        private static string NormalizeRoot(string value)
        {
            string v = (value ?? string.Empty).Trim().Trim('"');
            if (v.Length > 3) v = v.TrimEnd('\\', '/');
            return v;
        }
    }

    // Shared logic of the list pages: filter, search, sort, selection
    public abstract class ListPageViewModel : ObservableObject
    {
        private sealed class ItemComparer : IComparer
        {
            private readonly string _key;
            private readonly bool _desc;

            public ItemComparer(string key, bool desc) { _key = key ?? string.Empty; _desc = desc; }

            public int Compare(object a, object b)
            {
                PackageItem x = a as PackageItem;
                PackageItem y = b as PackageItem;
                if (x == null || y == null) return 0;
                int r;
                if (_key == "Name") r = string.Compare(x.Name, y.Name, StringComparison.OrdinalIgnoreCase);
                else if (_key == "Size") r = x.Size.CompareTo(y.Size);
                else r = x.SortIndex.CompareTo(y.SortIndex);
                if (r == 0) r = x.SortIndex.CompareTo(y.SortIndex);
                return _desc ? -r : r;
            }
        }

        protected readonly MainViewModel Main;
        protected readonly UiHost Host;
        private ObservableCollection<PackageItem> _items = new ObservableCollection<PackageItem>();
        private ListCollectionView _view;
        private string _search = string.Empty;
        private string _filter = "all";
        private string _sortKey = string.Empty;
        private bool _sortDesc;
        private int _selectedCount;
        private long _selectedBytes;
        private bool _suspend;
        private string _infoText = string.Empty;
        private bool _isStale;
        private readonly Dictionary<string, int> _counts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        protected ListPageViewModel(MainViewModel main, UiHost host)
        {
            Main = main;
            Host = host;
            _view = CreateView(_items);
            SelectAllCommand = new RelayCommand(p => SetAllVisible(true), p => Main.IsIdle && _items.Count > 0);
            SelectNoneCommand = new RelayCommand(p => SetAll(false), p => Main.IsIdle && _selectedCount > 0);
            SortCommand = new RelayCommand(p => ToggleSort(Convert.ToString(p, CultureInfo.InvariantCulture)), p => _items.Count > 0);
            ClearListCommand = new RelayCommand(p => ClearList(), p => Main.IsIdle && CanClearList);
        }

        public Loc L { get { return Loc.Instance; } }
        public ObservableCollection<PackageItem> Items { get { return _items; } }
        public ICollectionView View { get { return _view; } }
        public ICommand SelectAllCommand { get; private set; }
        public ICommand SelectNoneCommand { get; private set; }
        public ICommand SortCommand { get; private set; }
        public ICommand ClearListCommand { get; private set; }
        public bool CanClearList { get { return _items.Count > 0 || _search.Length > 0 || _filter != "all" || _sortKey.Length > 0; } }
        public bool IsIdle { get { return Main.IsIdle; } }
        public int SelectedCount { get { return _selectedCount; } }
        public long SelectedBytes { get { return _selectedBytes; } }
        public bool HasItems { get { return _items.Count > 0; } }
        public string SelectionText { get { return Loc.F("Sel_Summary", _selectedCount, _items.Count); } }
        public string SelectionSizeText { get { return Fmt.Size(_selectedBytes); } }
        public virtual string SummaryText { get { return SelectionSizeText; } }
        public string FooterToolTip { get { return SelectionText + "  ·  " + SummaryText; } }
        public string InfoText { get { return IsStale ? Loc.T("Stale") : _infoText; } }
        public bool IsStale { get { return _isStale && _items.Count > 0; } }
        public int CountAll { get { return _items.Count; } }
        public string NameSortGlyph { get { return SortGlyph("Name"); } }
        public string SizeSortGlyph { get { return SortGlyph("Size"); } }
        protected abstract string EmptyKey { get; }

        public string EmptyText
        {
            get { return _items.Count == 0 ? Loc.T(EmptyKey) : Loc.T("Empty_Filter"); }
        }

        public Visibility EmptyVisibility
        {
            get { return _view == null || _view.IsEmpty ? Visibility.Visible : Visibility.Collapsed; }
        }

        public string Search
        {
            get { return _search; }
            set
            {
                if (Set(ref _search, value ?? string.Empty)) RefreshView();
            }
        }

        public string Filter
        {
            get { return _filter; }
            set
            {
                if (Set(ref _filter, string.IsNullOrEmpty(value) ? "all" : value))
                {
                    RaiseFilterFlags();
                    RefreshView();
                }
            }
        }

        public bool? HeaderChecked
        {
            get
            {
                int visible = 0, checkedCount = 0;
                foreach (object o in _view)
                {
                    visible++;
                    PackageItem it = o as PackageItem;
                    if (it != null && it.IsChecked) checkedCount++;
                }
                if (visible == 0 || checkedCount == 0) return false;
                if (checkedCount == visible) return true;
                return null;
            }
            set
            {
                bool? current = HeaderChecked;
                SetAllVisible(current == null ? true : value == true);
            }
        }

        protected int Count(string category)
        {
            int c;
            return _counts.TryGetValue(category, out c) ? c : 0;
        }

        protected bool IsFilter(string key) { return string.Equals(_filter, key, StringComparison.OrdinalIgnoreCase); }

        protected virtual void RaiseFilterFlags() { }
        protected virtual void OnItemCheckedCore(PackageItem item) { }
        protected virtual void OnSelectionChanged() { }
        protected virtual void OnItemsReplaced() { }

        protected void SetInfo(string text, bool stale)
        {
            _infoText = text ?? string.Empty;
            _isStale = stale;
            RaiseMany("InfoText", "IsStale");
        }

        protected void MarkStale()
        {
            if (_items.Count == 0 || _isStale) return;
            _isStale = true;
            RaiseMany("InfoText", "IsStale");
        }

        // Back to the state of a fresh start: no rows, no search, no filter, default order.
        public void ClearList()
        {
            ReplaceItems(new PackageItem[0]);
            Search = string.Empty;
            Filter = "all";
            if (_sortKey.Length > 0)
            {
                _sortKey = string.Empty;
                _sortDesc = false;
                _view.CustomSort = new ItemComparer(_sortKey, _sortDesc);
                RaiseMany("NameSortGlyph", "SizeSortGlyph");
            }
            SetInfo(string.Empty, false);
            OnListCleared();
            Main.SetStatus(Loc.T("St_ListCleared"), "info");
            CommandManager.InvalidateRequerySuggested();
        }

        protected virtual void OnListCleared() { }

        // After the output folders were cleaned the downloaded files are gone: show every row as not downloaded.
        internal void ResetStates()
        {
            foreach (PackageItem it in _items)
            {
                if (it.State == ItemState.Idle && it.FilesDone == 0) continue;
                it.FilesDone = 0;
                it.SetStateCore(ItemState.Idle, null, -1);
            }
        }

        // When a job ends (also on error or cancel), settle rows left in a transient state
        // so that no row stays "Queued" or "Downloading".
        internal void SettleTransient(bool cancelled, string message)
        {
            foreach (PackageItem it in _items)
            {
                switch (it.State)
                {
                    case ItemState.Queued:
                        it.SetStateCore(cancelled ? ItemState.Cancelled : ItemState.Idle, null, -1);
                        break;
                    case ItemState.Resolving:
                    case ItemState.Downloading:
                    case ItemState.Verifying:
                    case ItemState.Extracting:
                        if (cancelled) it.SetStateCore(ItemState.Cancelled, null, -1);
                        else it.Fail(string.IsNullOrEmpty(message) ? Loc.T("Job_Failed") : message);
                        break;
                }
            }
        }

        protected void ReplaceItems(IEnumerable<PackageItem> items)
        {
            foreach (PackageItem old in _items) old.CheckedChanged -= OnItemChecked;
            _items = new ObservableCollection<PackageItem>(items ?? new PackageItem[0]);
            foreach (PackageItem it in _items) it.CheckedChanged += OnItemChecked;
            _view = CreateView(_items);
            _counts.Clear();
            foreach (PackageItem it in _items)
            {
                string cat = it.Category ?? string.Empty;
                int c;
                _counts[cat] = _counts.TryGetValue(cat, out c) ? c + 1 : 1;
            }
            if (_filter != "all" && Count(_filter) == 0)
            {
                _filter = "all";
                Raise("Filter");
                RaiseFilterFlags();
                _view.Refresh();
            }
            Raise("Items");
            Raise("View");
            RaiseMany("HasItems", "CountAll", "EmptyText", "EmptyVisibility", "IsStale", "InfoText");
            RaiseFilterFlags();
            OnItemsReplaced();
            RecalcSelection();
            CommandManager.InvalidateRequerySuggested();
        }

        private ListCollectionView CreateView(ObservableCollection<PackageItem> items)
        {
            ListCollectionView v = new ListCollectionView(items);
            v.Filter = FilterItem;
            v.CustomSort = new ItemComparer(_sortKey, _sortDesc);
            return v;
        }

        private bool FilterItem(object o)
        {
            PackageItem it = o as PackageItem;
            if (it == null) return false;
            if (_filter != "all" && !string.Equals(it.Category, _filter, StringComparison.OrdinalIgnoreCase)) return false;
            if (_search.Length == 0) return true;
            string s = _search.Trim();
            if (s.Length == 0) return true;
            return (it.Name ?? string.Empty).IndexOf(s, StringComparison.OrdinalIgnoreCase) >= 0
                || (it.Description ?? string.Empty).IndexOf(s, StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private void RefreshView()
        {
            if (_view != null) _view.Refresh();
            RaiseMany("HeaderChecked", "EmptyVisibility", "EmptyText");
        }

        private void ToggleSort(string key)
        {
            if (string.IsNullOrEmpty(key)) return;
            if (_sortKey == key)
            {
                if (!_sortDesc) _sortDesc = true;
                else { _sortKey = string.Empty; _sortDesc = false; }
            }
            else
            {
                _sortKey = key;
                _sortDesc = false;
            }
            if (_view != null) _view.CustomSort = new ItemComparer(_sortKey, _sortDesc);
            RaiseMany("NameSortGlyph", "SizeSortGlyph");
        }

        private string SortGlyph(string key)
        {
            if (_sortKey != key) return string.Empty;
            return _sortDesc ? "\uE70D" : "\uE70E";
        }

        private void OnItemChecked(object sender, EventArgs e)
        {
            if (_suspend) return;
            OnItemCheckedCore(sender as PackageItem);
            RecalcSelection();
        }

        protected void BeginBatch() { _suspend = true; }

        protected void EndBatch()
        {
            _suspend = false;
            RecalcSelection();
        }

        protected bool IsBatching { get { return _suspend; } }

        protected virtual void AfterBulkCheck(bool value) { }

        public void SetAllVisible(bool value)
        {
            BeginBatch();
            try
            {
                foreach (object o in _view)
                {
                    PackageItem it = o as PackageItem;
                    if (it != null) it.IsChecked = value;
                }
                AfterBulkCheck(value);
            }
            finally { EndBatch(); }
        }

        public void SetAll(bool value)
        {
            BeginBatch();
            try
            {
                foreach (PackageItem it in _items) it.IsChecked = value;
            }
            finally { EndBatch(); }
        }

        public void ToggleItems(IList<PackageItem> items)
        {
            if (items == null || items.Count == 0) return;
            bool allChecked = items.All(i => i.IsChecked);
            if (items.Count == 1)
            {
                items[0].IsChecked = !allChecked;
                return;
            }
            BeginBatch();
            try
            {
                foreach (PackageItem it in items) it.IsChecked = !allChecked;
                AfterBulkCheck(!allChecked);
            }
            finally { EndBatch(); }
        }

        protected void RecalcSelection()
        {
            int c = 0;
            long b = 0;
            foreach (PackageItem it in _items)
            {
                if (it.IsChecked) { c++; b += it.Size; }
            }
            _selectedCount = c;
            _selectedBytes = b;
            OnSelectionChanged();
            RaiseMany("SelectedCount", "SelectedBytes", "SelectionText", "SelectionSizeText", "SummaryText", "FooterToolTip", "HeaderChecked");
            if (UiThread.IsReady && UiThread.CheckAccess()) CommandManager.InvalidateRequerySuggested();
        }

        internal virtual void OnBusyChanged()
        {
            Raise("IsIdle");
        }

        internal virtual void RefreshLocalized()
        {
            foreach (PackageItem it in _items) it.RefreshLocalized();
            if (_view != null && _search.Length > 0) _view.Refresh();
            RaiseMany("SelectionText", "SelectionSizeText", "SummaryText", "FooterToolTip", "InfoText", "EmptyText");
        }

        protected PackageItem[] CheckedItems()
        {
            return _items.Where(i => i.IsChecked).ToArray();
        }
    }

    // Language packs and FOD page
    public sealed class LangPageViewModel : ListPageViewModel
    {
        private sealed class UupRow
        {
            public string UpdateId, Version, Arch;
            public bool IsWin11, IsServer;
        }

        private readonly List<UupRow> _rows = new List<UupRow>();
        private readonly ObservableCollection<OptionItem> _versions = new ObservableCollection<OptionItem>();
        private readonly ObservableCollection<OptionItem> _archs = new ObservableCollection<OptionItem>();
        private readonly ObservableCollection<OptionItem> _languages = new ObservableCollection<OptionItem>();
        private OptionItem _version, _arch, _language;
        private UiRequest _pendingFetch;
        private string _listedVersion, _listedArch, _listedLang;

        public LangPageViewModel(MainViewModel main, UiHost host) : base(main, host)
        {
            foreach (string line in host.Options.UupRows ?? new string[0])
            {
                string[] p = (line ?? string.Empty).Split('|');
                if (p.Length < 5) continue;
                UupRow r = new UupRow();
                r.UpdateId = p[0]; r.Version = p[1]; r.Arch = p[2];
                r.IsWin11 = string.Equals(p[3], "true", StringComparison.OrdinalIgnoreCase);
                r.IsServer = string.Equals(p[4], "true", StringComparison.OrdinalIgnoreCase);
                _rows.Add(r);
                if (!_versions.Any(v => v.Value == r.Version)) _versions.Add(new OptionItem(r.Version, r.Version));
            }
            foreach (string line in host.Options.Regions ?? new string[0])
            {
                string[] p = (line ?? string.Empty).Split('|');
                if (p.Length < 2) continue;
                if (p.Length > 2 && string.Equals(p[2], "peonly", StringComparison.OrdinalIgnoreCase)) continue;
                _languages.Add(new OptionItem(p[0], p[0] + "  ·  " + p[1]));
            }

            AppSettings s = host.Settings;
            _version = Pick(_versions, s.Get("LangVersion", null)) ?? _versions.FirstOrDefault();
            RefreshArchs(s.Get("LangArch", null));
            _language = Pick(_languages, s.Get("LangLang", null)) ?? Pick(_languages, "tr-tr") ?? _languages.FirstOrDefault();

            FetchCommand = new RelayCommand(p => Fetch(), p => Main.IsIdle && _version != null && _arch != null && _language != null);
            DownloadCommand = new RelayCommand(p => Download(), p => Main.IsIdle && SelectedCount > 0);
            CleanCommand = new RelayCommand(p => Clean(), p => Main.IsIdle);
            OpenFolderCommand = new RelayCommand(p => MainViewModel.OpenInExplorer(Main.Settings.OutputRoot, true));
        }

        public ICommand FetchCommand { get; private set; }
        public ICommand DownloadCommand { get; private set; }
        public ICommand CleanCommand { get; private set; }
        public ICommand OpenFolderCommand { get; private set; }
        public ObservableCollection<OptionItem> Versions { get { return _versions; } }
