        protected override void RaiseFilterFlags()
        {
            RaiseMany("FilterAll", "FilterLp", "FilterCore", "FilterOther", "FilterServer",
                      "CountLp", "CountCore", "CountOther", "CountServer",
                      "LpChipVisibility", "CoreChipVisibility", "OtherChipVisibility", "ServerChipVisibility");
        }

        private static OptionItem Pick(IEnumerable<OptionItem> list, string value)
        {
            if (string.IsNullOrEmpty(value)) return null;
            return list.FirstOrDefault(o => string.Equals(o.Value, value, StringComparison.OrdinalIgnoreCase));
        }

        private PeVersion CurrentVersion
        {
            get { return _version == null ? null : _peVersions.FirstOrDefault(v => v.Label == _version.Value); }
        }

        private static List<string> RuleArchs(PeVersion v)
        {
            string l = v.Label ?? string.Empty;
            if (v.IsServer)
            {
                if (l.Contains("2025") || l.Contains("24H2")) return new List<string> { "amd64", "arm64" };
                return new List<string> { "amd64" };
            }
            if (l == "W11 21H2") return new List<string> { "amd64", "x86", "arm64", "arm" };     // ADK 22000 still ships x86 and 32-bit ARM WinPE
            if (l.StartsWith("W11", StringComparison.OrdinalIgnoreCase)) return new List<string> { "amd64", "arm64" };
            if (l == "W10 1607") return new List<string> { "amd64", "x86" };
            // 32-bit ARM (ADK 1709-2004) is shown only where the availability list has it
            return new List<string> { "amd64", "x86", "arm64", "arm" };
        }

        internal void SetAvailability(string[] triples)
        {
            _avail.Clear();
            foreach (string t in triples ?? new string[0])
            {
                string[] p = (t ?? string.Empty).Split('|');
                if (p.Length < 3) continue;
                Dictionary<string, List<string>> archs;
                if (!_avail.TryGetValue(p[0], out archs)) { archs = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase); _avail[p[0]] = archs; }
                List<string> langs;
                if (!archs.TryGetValue(p[1], out langs)) { langs = new List<string>(); archs[p[1]] = langs; }
                if (!langs.Contains(p[2], StringComparer.OrdinalIgnoreCase)) langs.Add(p[2]);
            }
            RefreshArchs(_arch != null ? _arch.Value : null);
            RefreshLanguages(_language != null ? _language.Value : null);
        }

        private void RefreshArchs(string preferred)
        {
            _archs.Clear();
            PeVersion v = CurrentVersion;
            if (v != null)
            {
                List<string> rule = RuleArchs(v);
                Dictionary<string, List<string>> archs;
                bool known = _avail.TryGetValue(v.BuildId, out archs);
                foreach (string a in rule)
                {
                    if (!known || archs.ContainsKey(a)) _archs.Add(new OptionItem(a, a));
                }
                if (_archs.Count == 0) foreach (string a in rule) _archs.Add(new OptionItem(a, a));
            }
            _arch = Pick(_archs, preferred) ?? _archs.FirstOrDefault();
            Raise("SelectedArch");
        }

        private void RefreshLanguages(string preferred)
        {
            List<string> codes = new List<string>();
            PeVersion v = CurrentVersion;
            Dictionary<string, List<string>> archs;
            List<string> langs;
            if (v != null && _arch != null && _avail.TryGetValue(v.BuildId, out archs) && archs.TryGetValue(_arch.Value, out langs))
            {
                foreach (string l in langs) if (!string.Equals(l, "neutral", StringComparison.OrdinalIgnoreCase)) codes.Add(l);
                codes.Sort(StringComparer.OrdinalIgnoreCase);
            }
            if (codes.Count == 0) codes.AddRange(_regionNames.Keys);
            string keep = preferred;
            _languages.Clear();
            foreach (string c in codes)
            {
                string name;
                _languages.Add(new OptionItem(c, _regionNames.TryGetValue(c, out name) ? c + "  ·  " + name : c));
            }
            _language = Pick(_languages, keep) ?? Pick(_languages, "tr-tr") ?? Pick(_languages, "en-us") ?? _languages.FirstOrDefault();
            Raise("SelectedLanguage");
        }

        private void Fetch()
        {
            PeVersion v = CurrentVersion;
            if (v == null || _arch == null || _language == null) return;
            UiRequest req = new UiRequest("PeFetch");
            req.Args["Version"] = v.Label;
            req.Args["BuildId"] = v.BuildId;
            req.Args["Arch"] = _arch.Value;
            req.Args["Lang"] = _language.Value;
            req.Args["IsServer"] = v.IsServer;
            if (Host.Submit(req, "pe", Loc.F("Job_PeFetch", v.BuildId, _arch.Value, _language.Value))) _pendingFetch = req;
        }

        internal void SetItems(PackageItem[] items, string[] containers, string info, string buildInfo)
        {
            if (_pendingFetch != null)
            {
                _listedVersion = _pendingFetch.GetString("Version");
                _listedBuild = _pendingFetch.GetString("BuildId");
                _listedArch = _pendingFetch.GetString("Arch");
                _listedLang = _pendingFetch.GetString("Lang");
                _pendingFetch = null;
            }
            _containerSizes.Clear();
            foreach (string c in containers ?? new string[0])
            {
                string[] p = (c ?? string.Empty).Split('|');
                long size;
                if (p.Length >= 2 && long.TryParse(p[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out size)) _containerSizes[p[0]] = size;
                else if (p.Length >= 1 && p[0].Length > 0) _containerSizes[p[0]] = 0;
            }
            if (items != null)
            {
                foreach (PackageItem it in items)
                {
                    string[] d;
                    if (it.Dependencies == null || it.Dependencies.Length == 0)
                    {
                        if (_deps.TryGetValue(it.Name ?? string.Empty, out d)) it.Dependencies = d;
                    }
                }
            }
            _buildInfo = buildInfo ?? string.Empty;
            Raise("BuildInfoText");
            ReplaceItems(items);
            SetInfo(string.IsNullOrEmpty(_buildInfo) || string.IsNullOrEmpty(info) ? info : info + " · " + _buildInfo, false);
        }

        protected override void OnSelectionChanged()
        {
            HashSet<string> cabs = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (PackageItem it in Items)
            {
                if (!it.IsChecked || it.Containers == null) continue;
                foreach (string c in it.Containers) if (!string.IsNullOrEmpty(c)) cabs.Add(c);
            }
            long total = 0;
            foreach (string c in cabs)
            {
                long s;
                if (_containerSizes.TryGetValue(c, out s)) total += s;
            }
            _dlBytes = total;
            _dlCount = cabs.Count;
            RaiseMany("PackageSizeText", "DownloadSizeText", "DownloadSizeVisibility");
        }

        protected override void OnItemCheckedCore(PackageItem item)
        {
            if (item == null || !Main.Settings.AutoDeps) return;
            List<string> changed = new List<string>();
            BeginBatch();
            try
            {
                if (item.IsChecked) AddDependencies(new PackageItem[] { item }, changed);
                else RemoveDependents(item, changed);
            }
            finally { EndBatch(); }
            if (changed.Count > 0)
            {
                Main.SetStatus(Loc.F(item.IsChecked ? "Pe_DepsAdded" : "Pe_DepsRemoved", string.Join(", ", changed)), "info");
            }
        }

        protected override void AfterBulkCheck(bool value)
        {
            if (!value || !Main.Settings.AutoDeps) return;
            List<string> changed = new List<string>();
            AddDependencies(CheckedItems(), changed);
            if (changed.Count > 0) Main.SetStatus(Loc.F("Pe_DepsAdded", string.Join(", ", changed)), "info");
        }

        private Dictionary<string, PackageItem> ByName()
        {
            Dictionary<string, PackageItem> map = new Dictionary<string, PackageItem>(StringComparer.OrdinalIgnoreCase);
            foreach (PackageItem it in Items) if (!string.IsNullOrEmpty(it.Name)) map[it.Name] = it;
            return map;
        }

        private void AddDependencies(IEnumerable<PackageItem> roots, List<string> changed)
        {
            Dictionary<string, PackageItem> byName = ByName();
            Stack<PackageItem> stack = new Stack<PackageItem>(roots);
            while (stack.Count > 0)
            {
                PackageItem cur = stack.Pop();
                string[] deps;
                if (!_deps.TryGetValue(cur.Name ?? string.Empty, out deps)) continue;
                foreach (string d in deps)
                {
                    PackageItem di;
                    if (byName.TryGetValue(d, out di) && !di.IsChecked)
                    {
                        di.IsChecked = true;
                        changed.Add(di.Name);
                        stack.Push(di);
                    }
                }
            }
        }

        private void RemoveDependents(PackageItem root, List<string> changed)
        {
            Dictionary<string, PackageItem> byName = ByName();
            Stack<string> stack = new Stack<string>();
            stack.Push(root.Name ?? string.Empty);
            while (stack.Count > 0)
            {
                string cur = stack.Pop();
                foreach (KeyValuePair<string, string[]> kv in _deps)
                {
                    if (!kv.Value.Contains(cur, StringComparer.OrdinalIgnoreCase)) continue;
                    PackageItem di;
                    if (byName.TryGetValue(kv.Key, out di) && di.IsChecked)
                    {
                        di.IsChecked = false;
                        changed.Add(di.Name);
                        stack.Push(di.Name);
                    }
                }
            }
        }

        private void Download()
        {
            PackageItem[] sel = CheckedItems();
            if (sel.Length == 0)
            {
                Main.Dialog.ShowMessage("warn", Loc.T("Msg_WarnTitle"), Loc.T("Msg_SelectFiles"));
                return;
            }
            string root = Main.Settings.OutputRoot ?? string.Empty;
            string build = _listedBuild ?? string.Empty;
            string arch = _listedArch ?? string.Empty;
            string lang = _listedLang ?? string.Empty;
            string target = Path.Combine(Path.Combine(Path.Combine(root, "WinPE"), build), arch);
            List<string> names = sel.Select(i => i.Name).ToList();
            string compText = names.Count <= 3 ? string.Join(", ", names) : string.Join(", ", names.Take(3)) + ", +" + (names.Count - 3).ToString(CultureInfo.InvariantCulture);
            List<KeyValueRow> rows = new List<KeyValueRow>();
            rows.Add(new KeyValueRow(Loc.T("Dlg_Build"), string.IsNullOrEmpty(_buildInfo) ? build : build + " · " + _buildInfo));
            rows.Add(new KeyValueRow(Loc.T("Dlg_Arch"), arch));
            rows.Add(new KeyValueRow(Loc.T("Dlg_Langs"), "neutral, " + lang));
            rows.Add(new KeyValueRow(Loc.T("Dlg_Components"), names.Count.ToString(CultureInfo.InvariantCulture) + " — " + compText));
            rows.Add(new KeyValueRow(Loc.T("Dlg_PkgSize"), Fmt.Size(SelectedBytes)));
            if (_dlCount > 0) rows.Add(new KeyValueRow(Loc.T("Dlg_Download"), Loc.F("Dlg_Containers", Fmt.Size(_dlBytes), _dlCount), true));
            rows.Add(new KeyValueRow(Loc.T("Dlg_Target"), target));
            bool keep = Main.Settings.KeepCache;
            Main.Dialog.Confirm("download", Loc.T("Dlg_PeTitle"), Loc.T("Dlg_PeText"), rows.ToArray(),
                Host.Options.Offline ? null : Loc.T(keep ? "Dlg_CacheOn" : "Dlg_CacheOff"), Loc.T("Btn_Download"),
                delegate(bool ok)
                {
                    if (!ok) return;
                    foreach (PackageItem it in sel) { it.FilesDone = 0; it.SetStateCore(ItemState.Queued, null, -1); }
                    UiRequest req = new UiRequest("PeDownload");
                    req.Args["Items"] = sel;
                    req.Args["BuildId"] = build;
                    req.Args["Version"] = _listedVersion;
                    req.Args["Arch"] = arch;
                    req.Args["Lang"] = lang;
                    req.Args["Root"] = root;
                    req.Args["KeepCache"] = keep;
                    req.Args["SkipExisting"] = Main.Settings.SkipExisting;
                    req.Args["Verify"] = Main.Settings.VerifyHash;
                    if (!Host.Submit(req, "pe", Loc.F("Job_PeStart", sel.Length)))
                    {
                        foreach (PackageItem it in sel) it.SetStateCore(ItemState.Idle, null, -1);
                    }
                });
        }

        private void Clean()
        {
            string root = Main.Settings.OutputRoot;
            Main.Dialog.Confirm("clean", Loc.T("Dlg_CleanTitle"), Loc.T("Dlg_CleanPe"),
                new KeyValueRow[] { new KeyValueRow(Loc.T("Dlg_Folder"), Path.Combine(root ?? string.Empty, "WinPE")) }, null, Loc.T("Btn_Delete"),
                delegate(bool ok)
                {
                    if (!ok) return;
                    UiRequest req = new UiRequest("PeClean");
                    req.Args["Root"] = root;
                    Host.Submit(req, "pe", Loc.T("Job_Clean"));
                });
        }

        internal override void RefreshLocalized()
        {
            base.RefreshLocalized();
            RaiseMany("PackageSizeText", "DownloadSizeText");
        }
    }

    // Main view model
    public sealed class MainViewModel : ObservableObject
    {
        private readonly UiHost _host;
        private string _page;
        private bool _navCollapsed;
        private bool _isBusy;
        private string _busyPage = string.Empty;
        private bool _canCancel;
        private string _statusText = string.Empty;
        private string _statusLevel = "ok";
        private double _progressValue;
        private bool _progressIndeterminate;
        private bool _progressVisible;
        private string _progressDetail = string.Empty;
        private bool _engineReady;

        public MainViewModel(UiHost host)
        {
            _host = host;
            Dialog = new DialogViewModel();
            Settings = new SettingsViewModel(this, host);
            LogVm = new LogViewModel(this, host);
            Lang = new LangPageViewModel(this, host);
            Pe = new PePageViewModel(this, host);

            string page = host.Settings.Get("Page", "lang");
            _page = page == "pe" || page == "log" || page == "settings" ? page : "lang";
            _navCollapsed = host.Settings.GetBool("NavCollapsed", false);

            NavigateCommand = new RelayCommand(p => Page = Convert.ToString(p, CultureInfo.InvariantCulture));
            ToggleNavCommand = new RelayCommand(p => IsNavCollapsed = !IsNavCollapsed);
            CancelCommand = new RelayCommand(p => RequestCancel(), p => _isBusy && _canCancel);

            Loc.LanguageChanged += OnLanguageChanged;
            _statusText = Loc.T("St_Starting");
            _statusLevel = "busy";
            _progressVisible = true;
            _progressIndeterminate = true;
        }

        public Loc L { get { return Loc.Instance; } }
        public UiHost Host { get { return _host; } }
        public DialogViewModel Dialog { get; private set; }
        public SettingsViewModel Settings { get; private set; }
        public LogViewModel LogVm { get; private set; }
        public LangPageViewModel Lang { get; private set; }
        public PePageViewModel Pe { get; private set; }
        public ICommand NavigateCommand { get; private set; }
        public ICommand ToggleNavCommand { get; private set; }
        public ICommand CancelCommand { get; private set; }
        public string VersionText { get { return "v" + (_host.Options.AppVersion ?? "3.0") + " · " + (_host.Options.RuntimeInfo ?? string.Empty); } }

        // --- Navigation ---
        public string Page
        {
            get { return _page; }
            set
            {
                string v = value == "pe" || value == "log" || value == "settings" ? value : "lang";
                if (!Set(ref _page, v)) return;
                RaiseMany("IsLangPage", "IsPePage", "IsLogPage", "IsSettingsPage", "LangVisibility", "PeVisibility", "LogVisibility", "SettingsVisibility", "PageTitle", "PageSubtitle");
                _host.Settings.Set("Page", v);
                if (v == "log") LogVm.MarkSeen();
                if (v == "settings") Settings.RefreshManifestInfo();
                EventHandler h = PageChanged;
                if (h != null) h(this, EventArgs.Empty);
            }
        }

        public event EventHandler PageChanged;

        public bool IsLangPage { get { return _page == "lang"; } set { if (value) Page = "lang"; } }
        public bool IsPePage { get { return _page == "pe"; } set { if (value) Page = "pe"; } }
        public bool IsLogPage { get { return _page == "log"; } set { if (value) Page = "log"; } }
        public bool IsSettingsPage { get { return _page == "settings"; } set { if (value) Page = "settings"; } }
        public Visibility LangVisibility { get { return _page == "lang" ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility PeVisibility { get { return _page == "pe" ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility LogVisibility { get { return _page == "log" ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility SettingsVisibility { get { return _page == "settings" ? Visibility.Visible : Visibility.Collapsed; } }

        public string PageTitle
        {
            get
            {
                switch (_page)
                {
                    case "pe": return Loc.T("Pe_Title");
                    case "log": return Loc.T("Log_Title");
                    case "settings": return Loc.T("Set_Title");
                    default: return Loc.T("Lang_Title");
                }
            }
        }

        public string PageSubtitle
        {
            get
            {
                switch (_page)
                {
                    case "pe": return Loc.T("Pe_Sub");
                    case "log": return Loc.T("Log_Sub");
                    case "settings": return Loc.T("Set_Sub");
                    default: return Loc.T("Lang_Sub");
                }
            }
        }

        public bool IsNavCollapsed
        {
            get { return _navCollapsed; }
            set
            {
                if (!Set(ref _navCollapsed, value)) return;
                RaiseMany("NavWidth", "NavLabelVisibility", "NavCollapseGlyph", "NavCollapseText");
                LogVm.RaiseCounts();
                _host.Settings.Set("NavCollapsed", value);
            }
        }

        public double NavWidth { get { return _navCollapsed ? 52 : 160; } }
        public Visibility NavLabelVisibility { get { return _navCollapsed ? Visibility.Collapsed : Visibility.Visible; } }
        public string NavCollapseGlyph { get { return _navCollapsed ? "\uE76C" : "\uE76B"; } }
        public string NavCollapseText { get { return Loc.T(_navCollapsed ? "Nav_Expand" : "Nav_Collapse"); } }

        // --- Busy state ---
        public bool IsBusy { get { return _isBusy; } }
        public bool IsIdle { get { return !_isBusy; } }
        public bool CanCancel { get { return _canCancel; } }
        public Visibility CancelVisibility { get { return _isBusy && _canCancel ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility IdleVisibility { get { return _isBusy ? Visibility.Collapsed : Visibility.Visible; } }
        public Visibility LangBusyVisibility { get { return _isBusy && _busyPage == "lang" ? Visibility.Visible : Visibility.Collapsed; } }
        public Visibility PeBusyVisibility { get { return _isBusy && _busyPage == "pe" ? Visibility.Visible : Visibility.Collapsed; } }

        internal void BeginBusy(string page, string text)
        {
            _isBusy = true;
            _busyPage = page ?? string.Empty;
            _canCancel = true;
            _progressVisible = true;
            _progressIndeterminate = true;
            _progressValue = 0;
            _progressDetail = string.Empty;
            _statusText = text ?? string.Empty;
            _statusLevel = "busy";
            RaiseBusy();
        }

        internal void EndBusy(UiRequest request, bool ok, string message, string level)
        {
            ListPageViewModel page = _busyPage == "lang" ? (ListPageViewModel)Lang : _busyPage == "pe" ? (ListPageViewModel)Pe : null;
            if (page != null)
            {
                page.SettleTransient(_host.IsCancelRequested, FirstLine(message));
                if (ok && request != null && request.Kind.EndsWith("Clean", StringComparison.Ordinal)) page.ResetStates();
            }
            _isBusy = false;
            _busyPage = string.Empty;
            _canCancel = false;
            _progressVisible = false;
            _progressIndeterminate = false;
            _progressValue = 0;
            _progressDetail = string.Empty;
            _statusText = string.IsNullOrEmpty(message) ? Loc.T(ok ? "St_Ready" : "Job_Failed") : FirstLine(message);
            _statusLevel = string.IsNullOrEmpty(level) ? (ok ? "ok" : "error") : level;
            RaiseBusy();
        }

        private void RaiseBusy()
        {
            RaiseMany("IsBusy", "IsIdle", "CanCancel", "CancelVisibility", "IdleVisibility", "LangBusyVisibility", "PeBusyVisibility",
                      "StatusText", "StatusLevel", "ProgressVisibility", "ProgressIndeterminate", "ProgressValue", "ProgressDetail");
            Lang.OnBusyChanged();
            Pe.OnBusyChanged();
            CommandManager.InvalidateRequerySuggested();
        }

        internal void OnEngineReady(double seconds)
        {
            _engineReady = true;
            if (_isBusy) return;
            _progressVisible = false;
            _progressIndeterminate = false;
            _statusText = Loc.F("St_EngineReady", seconds.ToString("0.0", Loc.Culture));
            _statusLevel = "ok";
            RaiseMany("StatusText", "StatusLevel", "ProgressVisibility", "ProgressIndeterminate");
        }

        public bool EngineIsReady { get { return _engineReady; } }

        // --- Status bar ---
        public string StatusText { get { return _statusText; } }
        public string StatusLevel { get { return _statusLevel; } }
        public double ProgressValue { get { return _progressValue; } }
        public bool ProgressIndeterminate { get { return _progressIndeterminate; } }
        public Visibility ProgressVisibility { get { return _progressVisible ? Visibility.Visible : Visibility.Collapsed; } }

        public string ProgressDetail
        {
            get { return _progressDetail; }
            set { Set(ref _progressDetail, value ?? string.Empty); }
        }

        internal void SetStatus(string text, string level)
        {
            _statusText = FirstLine(text);
            _statusLevel = string.IsNullOrEmpty(level) ? "info" : level;
            RaiseMany("StatusText", "StatusLevel");
        }

        internal void SetProgress(double percent)
        {
            if (percent < 0)
            {
                _progressIndeterminate = true;
            }
            else
            {
                _progressIndeterminate = false;
                _progressValue = Math.Min(100, percent);
            }
            _progressVisible = true;
            RaiseMany("ProgressIndeterminate", "ProgressValue", "ProgressVisibility");
        }

        private void RequestCancel()
        {
            _host.Cancel.Cancel();
            _canCancel = false;
            SetStatus(Loc.T("St_Cancelling"), "warn");
            RaiseMany("CanCancel", "CancelVisibility");
            CommandManager.InvalidateRequerySuggested();
        }

        private static string FirstLine(string text)
        {
            if (string.IsNullOrEmpty(text)) return string.Empty;
            int i = text.IndexOfAny(new char[] { '\r', '\n' });
            return i < 0 ? text : text.Substring(0, i);
        }

        private void OnLanguageChanged(object sender, EventArgs e)
        {
            RaiseMany("PageTitle", "PageSubtitle", "NavCollapseText", "VersionText");
            Lang.RefreshLocalized();
            Pe.RefreshLocalized();
            Settings.RefreshLocalized();
            LogVm.RaiseCounts();
            if (!_isBusy) SetStatus(Loc.T("St_Ready"), "ok");
            EventHandler h = LanguageApplied;
            if (h != null) h(this, EventArgs.Empty);
        }

        public event EventHandler LanguageApplied;

        // --- Helpers ---
        public static void OpenInExplorer(string path)
        {
            OpenInExplorer(path, false);
        }

        public static void OpenInExplorer(string path, bool create)
        {
            try
            {
                if (string.IsNullOrEmpty(path)) return;
                if (create && !Directory.Exists(path)) Directory.CreateDirectory(path);
                if (!Directory.Exists(path)) return;
                ProcessStartInfo psi = new ProcessStartInfo("explorer.exe", "\"" + path + "\"");
                psi.UseShellExecute = true;
                Process.Start(psi);
            }
            catch { }
        }

        public static bool TrySetClipboard(string text)
        {
            for (int i = 0; i < 5; i++)
            {
                try { Clipboard.SetText(text ?? string.Empty); return true; }
                catch { Thread.Sleep(60); }
            }
            return false;
        }
    }

    // Main window: loads the XAML at runtime and handles the custom chrome and keyboard shortcuts.
    public sealed class MainWindow : Window
    {
        [DllImport("user32.dll")]
        private static extern int GetSystemMetrics(int index);

        private readonly UiHost _host;
        private readonly MainViewModel _vm;
        private readonly FrameworkElement _root;
        private Border _frame;
        private TextBlock _maxGlyph;
        private Button _btnMax;
        private ListBox _langList, _peList, _logList;
        private TextBox _langSearch, _peSearch;
        private Button _dlgOk;
        private bool _forceClose;

        public MainWindow(UiHost host, MainViewModel vm)
        {
            _host = host;
            _vm = vm;
            AppSettings s = host.Settings;

            Title = Loc.T("App_Title");
            Width = Clamp(s.GetDouble("WinW", 860), 760, 6000);
            Height = Clamp(s.GetDouble("WinH", 540), 480, 4000);
            MinWidth = 760;
            MinHeight = 480;
            WindowStartupLocation = WindowStartupLocation.CenterScreen;
            ResizeMode = ResizeMode.CanResize;
            UseLayoutRounding = true;
            SnapsToDevicePixels = true;
            TextOptions.SetTextFormattingMode(this, TextFormattingMode.Display);

            WindowChrome chrome = new WindowChrome();
            chrome.CaptionHeight = 46;
            chrome.ResizeBorderThickness = new Thickness(6);
            chrome.CornerRadius = new CornerRadius(0);
            chrome.GlassFrameThickness = new Thickness(0, 0, 0, 1);
            chrome.UseAeroCaptionButtons = false;
            WindowChrome.SetWindowChrome(this, chrome);

            ResourceDictionary theme = (ResourceDictionary)XamlReader.Parse(host.Options.ThemeXaml);
            Resources.MergedDictionaries.Add(theme);
            Background = theme["B.Bg"] as Brush;
            Foreground = theme["B.Text"] as Brush;
            FontFamily = new FontFamily("Segoe UI");
            FontSize = 12;

            _root = (FrameworkElement)XamlReader.Parse(host.Options.LayoutXaml);
            Content = _root;
            DataContext = vm;

            _frame = _root as Border;
            if (_frame != null && Native.IsWindows11) _frame.BorderThickness = new Thickness(0);
            _maxGlyph = Find<TextBlock>("MaxGlyph");
            _btnMax = Find<Button>("BtnMax");
            _langList = Find<ListBox>("LangList");
            _peList = Find<ListBox>("PeList");
            _logList = Find<ListBox>("LogList");
            _langSearch = Find<TextBox>("LangSearch");
            _peSearch = Find<TextBox>("PeSearch");
            _dlgOk = Find<Button>("DlgOk");

            Button bMin = Find<Button>("BtnMin");
            if (bMin != null) bMin.Click += delegate { WindowState = WindowState.Minimized; };
            if (_btnMax != null) _btnMax.Click += delegate { WindowState = WindowState == WindowState.Maximized ? WindowState.Normal : WindowState.Maximized; };
            Button bClose = Find<Button>("BtnClose");
            if (bClose != null) bClose.Click += delegate { Close(); };

            WireList(_langList, vm.Lang);
            WireList(_peList, vm.Pe);
            if (_logList != null) _logList.PreviewKeyDown += OnLogKeyDown;

            try { Icon = CreateIcon(); } catch { }

            SourceInitialized += OnSourceInitialized;
            StateChanged += delegate { UpdateMaxState(); };
            Closing += OnClosing;
            PreviewKeyDown += OnPreviewKeyDown;
            Loaded += delegate { UpdateMaxState(); };
            vm.Dialog.Opened += delegate { Dispatcher.BeginInvoke(DispatcherPriority.Input, new Action(FocusDialog)); };
            vm.LanguageApplied += delegate { Title = Loc.T("App_Title"); UpdateMaxState(); };
            vm.LogVm.Entries.CollectionChanged += OnLogChanged;
            vm.PageChanged += delegate { if (_vm.IsLogPage) Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(ScrollLogToEnd)); };
            Loaded += delegate { if (_vm.IsLogPage) Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(ScrollLogToEnd)); };

            if (s.GetBool("WinMax", false)) WindowState = WindowState.Maximized;
        }

        private T Find<T>(string name) where T : class
        {
            return _root.FindName(name) as T;
        }

        private static double Clamp(double v, double min, double max)
        {
            if (double.IsNaN(v)) return min;
            return Math.Max(min, Math.Min(max, v));
        }

        internal void ForceClose()
        {
            _forceClose = true;
            Close();
        }

        private void OnSourceInitialized(object sender, EventArgs e)
        {
            try
            {
                IntPtr hwnd = new WindowInteropHelper(this).Handle;
                Native.ApplyWindowTheme(hwnd, 0x00372F2A);
            }
            catch { }
        }

        private void UpdateMaxState()
        {
            bool max = WindowState == WindowState.Maximized;
            if (max)
            {
                double scale = 1.0;
                try
                {
                    PresentationSource src = PresentationSource.FromVisual(this);
                    if (src != null && src.CompositionTarget != null) scale = src.CompositionTarget.TransformToDevice.M11;
                }
                catch { }
                int px = 8;
                try { px = GetSystemMetrics(32) + GetSystemMetrics(92); } catch { }
                if (px <= 0) px = 8;
                double dip = px / (scale <= 0 ? 1.0 : scale);
                _root.Margin = new Thickness(dip);
                if (_frame != null) _frame.BorderThickness = new Thickness(0);
            }
            else
            {
                _root.Margin = new Thickness(0);
                if (_frame != null) _frame.BorderThickness = Native.IsWindows11 ? new Thickness(0) : new Thickness(1);
            }
            if (_maxGlyph != null) _maxGlyph.Text = max ? "\uE923" : "\uE922";
            if (_btnMax != null) _btnMax.ToolTip = Loc.T(max ? "Win_Restore" : "Win_Max");
        }

        private void OnClosing(object sender, CancelEventArgs e)
        {
            if (!_forceClose && _vm.IsBusy)
            {
                e.Cancel = true;
                _vm.Dialog.Confirm("warn", Loc.T("Msg_ExitTitle"), Loc.T("Msg_ConfirmExit"), null, null, Loc.T("Btn_Exit"),
                    delegate(bool ok)
                    {
                        if (!ok) return;
                        _host.Cancel.Cancel();
                        _forceClose = true;
                        Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(Close));
                    });
                return;
            }
            try
            {
                AppSettings s = _host.Settings;
                bool max = WindowState == WindowState.Maximized;
                Rect r = max ? RestoreBounds : new Rect(Left, Top, ActualWidth, ActualHeight);
                if (r.Width > 0 && r.Height > 0)
                {
                    s.Set("WinW", Math.Round(r.Width));
                    s.Set("WinH", Math.Round(r.Height));
                }
                s.Set("WinMax", max);
                s.Save();
            }
            catch { }
        }

        private void FocusDialog()
        {
            if (_dlgOk != null && _vm.Dialog.IsOpen) _dlgOk.Focus();
        }

        private void OnPreviewKeyDown(object sender, KeyEventArgs e)
        {
            bool ctrl = (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            if (_vm.Dialog.IsOpen)
            {
                if (e.Key == Key.Escape) { _vm.Dialog.CancelCommand.Execute(null); e.Handled = true; }
                else if (e.Key == Key.Enter) { _vm.Dialog.OkCommand.Execute(null); e.Handled = true; }
                else if (e.Key == Key.F5 || (ctrl && (e.Key == Key.F || e.Key == Key.R || (e.Key >= Key.D1 && e.Key <= Key.D4)))) e.Handled = true;
                return;
            }
            if (e.Key == Key.F5)
            {
                ICommand cmd = _vm.IsPePage ? _vm.Pe.FetchCommand : (_vm.IsLangPage ? _vm.Lang.FetchCommand : null);
                if (cmd != null && cmd.CanExecute(null)) cmd.Execute(null);
                e.Handled = true;
                return;
            }
            if (ctrl && e.Key == Key.F)
            {
                TextBox box = _vm.IsPePage ? _peSearch : (_vm.IsLangPage ? _langSearch : null);
                if (box != null) { box.Focus(); box.SelectAll(); e.Handled = true; }
                return;
            }
            if (ctrl && e.Key == Key.R)
            {
                ICommand cmd = _vm.IsPePage ? _vm.Pe.ClearListCommand : (_vm.IsLangPage ? _vm.Lang.ClearListCommand : null);
                if (cmd != null && cmd.CanExecute(null)) cmd.Execute(null);
                e.Handled = true;
                return;
            }
            if (ctrl && e.Key >= Key.D1 && e.Key <= Key.D4)
            {
                string[] pages = new string[] { "lang", "pe", "log", "settings" };
                _vm.Page = pages[e.Key - Key.D1];
                e.Handled = true;
                return;
            }
            if (e.Key == Key.Escape)
            {
                TextBox focused = Keyboard.FocusedElement as TextBox;
                if (focused != null && (focused == _langSearch || focused == _peSearch) && focused.Text.Length > 0)
                {
                    focused.Clear();
                    e.Handled = true;
                }
            }
        }

        private void WireList(ListBox list, ListPageViewModel page)
        {
            if (list == null) return;
            list.PreviewMouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e) { OnListMouseUp(page, e); };
            list.PreviewKeyDown += delegate(object sender, KeyEventArgs e) { OnListKeyDown(list, page, e); };
        }

        private void OnListMouseUp(ListPageViewModel page, MouseButtonEventArgs e)
        {
            if (!_vm.IsIdle) return;
            if ((Keyboard.Modifiers & (ModifierKeys.Control | ModifierKeys.Shift)) != ModifierKeys.None) return;
            DependencyObject src = e.OriginalSource as DependencyObject;
            if (src == null || FindAncestor<ButtonBase>(src) != null || FindAncestor<ScrollBar>(src) != null) return;
            ListBoxItem lbi = FindAncestor<ListBoxItem>(src);
            if (lbi == null) return;
            PackageItem it = lbi.DataContext as PackageItem;
            if (it != null) it.IsChecked = !it.IsChecked;
        }

        private void OnListKeyDown(ListBox list, ListPageViewModel page, KeyEventArgs e)
        {
            bool ctrl = (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            if (e.Key == Key.Space && _vm.IsIdle)
            {
                List<PackageItem> sel = list.SelectedItems.OfType<PackageItem>().ToList();
                if (sel.Count > 0) page.ToggleItems(sel);
                e.Handled = true;
            }
            else if (ctrl && e.Key == Key.C)
            {
                List<PackageItem> sel = list.SelectedItems.OfType<PackageItem>().ToList();
                if (sel.Count == 0) sel = page.Items.Where(i => i.IsChecked).ToList();
                if (sel.Count > 0) MainViewModel.TrySetClipboard(string.Join(Environment.NewLine, sel.Select(i => i.Name)));
                e.Handled = true;
            }
        }

        private void OnLogKeyDown(object sender, KeyEventArgs e)
        {
            if ((Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control && e.Key == Key.C && _logList != null)
            {
                List<LogEntry> sel = _logList.SelectedItems.OfType<LogEntry>().OrderBy(x => x.Time).ToList();
                if (sel.Count > 0) MainViewModel.TrySetClipboard(string.Join(Environment.NewLine, sel.Select(x => x.ToString())));
                e.Handled = true;
            }
        }

        private void ScrollLogToEnd()
        {
            int n = _vm.LogVm.Entries.Count;
            if (_logList != null && n > 0) _logList.ScrollIntoView(_vm.LogVm.Entries[n - 1]);
        }

        private void OnLogChanged(object sender, NotifyCollectionChangedEventArgs e)
        {
            if (e.Action != NotifyCollectionChangedAction.Add || _logList == null || !_vm.IsLogPage) return;
            object last = _vm.LogVm.Entries.Count > 0 ? _vm.LogVm.Entries[_vm.LogVm.Entries.Count - 1] : null;
            if (last != null) Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate { _logList.ScrollIntoView(last); }));
        }

        private static T FindAncestor<T>(DependencyObject d) where T : DependencyObject
        {
            while (d != null)
            {
                T t = d as T;
                if (t != null) return t;
                DependencyObject parent = null;
                if (d is Visual || d is System.Windows.Media.Media3D.Visual3D) parent = VisualTreeHelper.GetParent(d);
                if (parent == null) parent = LogicalTreeHelper.GetParent(d);
                d = parent;
            }
            return null;
        }

        // Window / taskbar icon. Kept as a vector drawing so Windows renders every icon size
        // (16, 20, 24, 32, 48 px ...) from the shapes instead of scaling a bitmap.
        private static ImageSource CreateIcon()
        {
            DrawingGroup g = new DrawingGroup();
            g.Transform = new ScaleTransform(4, 4);    // 64-unit design, 256 px image: always scaled down
            g.Children.Add(new GeometryDrawing(Brushes.Transparent, null, new RectangleGeometry(new Rect(0, 0, 64, 64))));

            Pen rim = new Pen(new SolidColorBrush(Rgb(0x2F3541)), 1.2);
            g.Children.Add(new GeometryDrawing(new LinearGradientBrush(Rgb(0x22262F), Rgb(0x14171D), 90.0), rim,
                new RectangleGeometry(new Rect(2, 2, 60, 60), 15, 15)));

            AddTile(g, 10, 10, 19, 3.2, 0x75BFFF, 0x2E8AE6);
            AddTile(g, 33, 10, 19, 3.2, 0x5AA8FF, 0x1874D0);
            AddTile(g, 10, 33, 19, 3.2, 0x4A9EFF, 0x0F6CBD);
            AddTile(g, 33, 33, 21, 3.6, 0xF7BD56, 0xDF921E);

            // Filled arrow instead of a stroke: head and shaft stay apart even at 16 px
            g.Children.Add(new GeometryDrawing(new SolidColorBrush(Rgb(0x15171C)), null,
                Geometry.Parse("M41.7,37.5 H45.3 V43.8 H49.5 L43.5,50 L37.5,43.8 H41.7 Z")));

            DrawingImage icon = new DrawingImage(g);
            icon.Freeze();
            return icon;
        }

        private static void AddTile(DrawingGroup g, double x, double y, double size, double radius, int from, int to)
        {
            LinearGradientBrush fill = new LinearGradientBrush(Rgb(from), Rgb(to), 45.0);
            g.Children.Add(new GeometryDrawing(fill, null, new RectangleGeometry(new Rect(x, y, size, size), radius, radius)));
        }

        private static Color Rgb(int rgb)
        {
            return Color.FromRgb((byte)((rgb >> 16) & 0xFF), (byte)((rgb >> 8) & 0xFF), (byte)(rgb & 0xFF));
        }
    }

    // Modern folder picker (IFileOpenDialog, FOS_PICKFOLDERS)
    internal static class FolderPicker
    {
        [ComImport, Guid("DC1C5A9C-E88A-4dde-A5A1-60F82A20AEF7")]
        private class FileOpenDialogCom { }

        [ComImport, Guid("42f85136-db7e-439c-85f1-e4075d135fc8"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IFileDialog
        {
            [PreserveSig] int Show(IntPtr parent);
            void SetFileTypes(uint cFileTypes, IntPtr rgFilterSpec);
            void SetFileTypeIndex(uint iFileType);
            void GetFileTypeIndex(out uint piFileType);
            void Advise(IntPtr pfde, out uint pdwCookie);
            void Unadvise(uint dwCookie);
            void SetOptions(uint fos);
            void GetOptions(out uint pfos);
            void SetDefaultFolder(IShellItem psi);
            void SetFolder(IShellItem psi);
            void GetFolder(out IShellItem ppsi);
            void GetCurrentSelection(out IShellItem ppsi);
            void SetFileName([MarshalAs(UnmanagedType.LPWStr)] string pszName);
            void GetFileName([MarshalAs(UnmanagedType.LPWStr)] out string pszName);
            void SetTitle([MarshalAs(UnmanagedType.LPWStr)] string pszTitle);
            void SetOkButtonLabel([MarshalAs(UnmanagedType.LPWStr)] string pszText);
            void SetFileNameLabel([MarshalAs(UnmanagedType.LPWStr)] string pszLabel);
            void GetResult(out IShellItem ppsi);
            void AddPlace(IShellItem psi, int fdap);
            void SetDefaultExtension([MarshalAs(UnmanagedType.LPWStr)] string pszDefaultExtension);
            void Close(int hr);
            void SetClientGuid(ref Guid guid);
            void ClearClientData();
            void SetFilter(IntPtr pFilter);
        }

        [ComImport, Guid("43826D1E-E718-42EE-BC55-A1E261C37BFE"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
        private interface IShellItem
        {
            void BindToHandler(IntPtr pbc, ref Guid bhid, ref Guid riid, out IntPtr ppv);
            void GetParent(out IShellItem ppsi);
            void GetDisplayName(uint sigdnName, [MarshalAs(UnmanagedType.LPWStr)] out string ppszName);
            void GetAttributes(uint sfgaoMask, out uint psfgaoAttribs);
            void Compare(IShellItem psi, uint hint, out int piOrder);
        }

        [DllImport("shell32.dll", CharSet = CharSet.Unicode, PreserveSig = false)]
        private static extern void SHCreateItemFromParsingName([MarshalAs(UnmanagedType.LPWStr)] string pszPath, IntPtr pbc, [MarshalAs(UnmanagedType.LPStruct)] Guid riid, out IShellItem ppv);

        private const uint FOS_PICKFOLDERS = 0x20;
        private const uint FOS_FORCEFILESYSTEM = 0x40;
        private const uint FOS_PATHMUSTEXIST = 0x800;
        private const uint SIGDN_FILESYSPATH = 0x80058000;

        public static string Pick(Window owner, string title, string initialPath)
        {
            IFileDialog dlg = (IFileDialog)new FileOpenDialogCom();
            try
            {
                uint opts;
                dlg.GetOptions(out opts);
                dlg.SetOptions(opts | FOS_PICKFOLDERS | FOS_FORCEFILESYSTEM | FOS_PATHMUSTEXIST);
                if (!string.IsNullOrEmpty(title)) dlg.SetTitle(title);
                if (!string.IsNullOrEmpty(initialPath) && Directory.Exists(initialPath))
                {
                    try
                    {
                        IShellItem folder;
                        SHCreateItemFromParsingName(initialPath, IntPtr.Zero, typeof(IShellItem).GUID, out folder);
                        if (folder != null) dlg.SetFolder(folder);
                    }
                    catch { }
                }
                IntPtr hwnd = owner != null ? new WindowInteropHelper(owner).Handle : IntPtr.Zero;
                int hr = dlg.Show(hwnd);
                if (hr != 0) return null;
                IShellItem result;
                dlg.GetResult(out result);
                if (result == null) return null;
                string path;
                result.GetDisplayName(SIGDN_FILESYSPATH, out path);
                return path;
            }
            finally
            {
                try { Marshal.FinalReleaseComObject(dlg); } catch { }
            }
        }
    }
}
'@

$script:XamlTheme = @'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">

    <!-- Colors -->
    <SolidColorBrush x:Key="B.Bg" Color="#15171C"/>
    <SolidColorBrush x:Key="B.Side" Color="#0F1115"/>
    <SolidColorBrush x:Key="B.SideLine" Color="#22262D"/>
    <SolidColorBrush x:Key="B.Card" Color="#191C22"/>
    <SolidColorBrush x:Key="B.CardHead" Color="#1C1F26"/>
    <SolidColorBrush x:Key="B.CardLine" Color="#23272E"/>
    <SolidColorBrush x:Key="B.HeadLine" Color="#262A31"/>
    <SolidColorBrush x:Key="B.RowLine" Color="#1E2228"/>
    <SolidColorBrush x:Key="B.Input" Color="#1F2329"/>
    <SolidColorBrush x:Key="B.InputLine" Color="#2F343D"/>
    <SolidColorBrush x:Key="B.InputLineHover" Color="#434A55"/>
    <SolidColorBrush x:Key="B.Raised" Color="#262B33"/>
    <SolidColorBrush x:Key="B.RaisedHover" Color="#2D333C"/>
    <SolidColorBrush x:Key="B.RaisedPressed" Color="#21252C"/>
    <SolidColorBrush x:Key="B.RaisedLine" Color="#353B45"/>
    <SolidColorBrush x:Key="B.NavHover" Color="#171A20"/>
    <SolidColorBrush x:Key="B.NavActive" Color="#1C2027"/>
    <SolidColorBrush x:Key="B.Divider" Color="#2A2F37"/>
    <SolidColorBrush x:Key="B.Divider2" Color="#1F232A"/>
    <SolidColorBrush x:Key="B.Frame" Color="#2A2F37"/>
    <SolidColorBrush x:Key="B.Text" Color="#E7EAF0"/>
    <SolidColorBrush x:Key="B.Text2" Color="#A7AFBC"/>
    <SolidColorBrush x:Key="B.Text3" Color="#808898"/>
    <SolidColorBrush x:Key="B.Text4" Color="#5F6776"/>
    <SolidColorBrush x:Key="B.Accent" Color="#F2A431"/>
    <SolidColorBrush x:Key="B.AccentHover" Color="#F6B652"/>
    <SolidColorBrush x:Key="B.AccentPressed" Color="#DB9220"/>
    <SolidColorBrush x:Key="B.AccentInk" Color="#1B1405"/>
    <SolidColorBrush x:Key="B.AccentSoft" Color="#24F2A431"/>
    <SolidColorBrush x:Key="B.AccentRow" Color="#10F2A431"/>
    <SolidColorBrush x:Key="B.AccentDisabledBg" Color="#3A3427"/>
    <SolidColorBrush x:Key="B.AccentDisabledInk" Color="#8D7A55"/>
    <SolidColorBrush x:Key="B.Ok" Color="#3FB97A"/>
    <SolidColorBrush x:Key="B.OkText" Color="#6FCF97"/>
    <SolidColorBrush x:Key="B.Warn" Color="#E5C451"/>
    <SolidColorBrush x:Key="B.Err" Color="#F2685C"/>
    <SolidColorBrush x:Key="B.Info" Color="#5AA8FF"/>
    <SolidColorBrush x:Key="B.ErrSoft" Color="#26F2685C"/>
    <SolidColorBrush x:Key="B.InfoSoft" Color="#245AA8FF"/>
    <SolidColorBrush x:Key="B.WarnSoft" Color="#24E5C451"/>
    <SolidColorBrush x:Key="B.CatLp" Color="#3FB97A"/>
    <SolidColorBrush x:Key="B.CatFeature" Color="#5AA8FF"/>
    <SolidColorBrush x:Key="B.CatFod" Color="#8A93A3"/>
    <SolidColorBrush x:Key="B.CatServer" Color="#B98CFF"/>
    <SolidColorBrush x:Key="B.Overlay" Color="#A306070A"/>
    <SolidColorBrush x:Key="B.Status" Color="#121419"/>
    <SolidColorBrush x:Key="B.Popup" Color="#1D2027"/>
    <SolidColorBrush x:Key="B.PopupLine" Color="#323843"/>
    <SolidColorBrush x:Key="B.PopupHover" Color="#2A2F38"/>
    <SolidColorBrush x:Key="B.Tooltip" Color="#22262E"/>
    <SolidColorBrush x:Key="B.ScrollThumb" Color="#3A404A"/>
    <SolidColorBrush x:Key="B.ScrollThumbHover" Color="#4A515D"/>
    <SolidColorBrush x:Key="B.ScrollThumbDrag" Color="#5A6270"/>
    <SolidColorBrush x:Key="B.CloseHover" Color="#C42B1C"/>
    <SolidColorBrush x:Key="B.CheckLine" Color="#4A515D"/>
    <SolidColorBrush x:Key="B.CheckLineHover" Color="#6B7383"/>
    <SolidColorBrush x:Key="B.SegOn" Color="#343A44"/>
    <SolidColorBrush x:Key="B.Detail" Color="#171A1F"/>
    <SolidColorBrush x:Key="B.RowHover" Color="#0BFFFFFF"/>
    <SolidColorBrush x:Key="B.RowSelected" Color="#14FFFFFF"/>

    <FontFamily x:Key="F.Icon">Segoe Fluent Icons, Segoe MDL2 Assets</FontFamily>
    <FontFamily x:Key="F.Mono">Cascadia Mono, Consolas, Courier New</FontFamily>

    <BooleanToVisibilityConverter x:Key="BoolToVis"/>

    <!-- Focus ring -->
    <Style x:Key="FocusRing">
        <Setter Property="Control.Template">
            <Setter.Value>
                <ControlTemplate>
                    <Rectangle Margin="-2" RadiusX="7" RadiusY="7" Stroke="{StaticResource B.Accent}" StrokeThickness="1.5" SnapsToDevicePixels="True"/>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Buttons -->
    <Style x:Key="Btn.Base" TargetType="{x:Type ButtonBase}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderBrush" Value="Transparent"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding" Value="12,0"/>
        <Setter Property="Height" Value="30"/>
        <Setter Property="MinWidth" Value="30"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Center"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="SnapsToDevicePixels" Value="True"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ButtonBase}">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="6" SnapsToDevicePixels="True">
                        <ContentPresenter Margin="{TemplateBinding Padding}" RecognizesAccessKey="True"
                                          HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                          VerticalAlignment="{TemplateBinding VerticalContentAlignment}"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Btn.Primary" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Base}">
        <Setter Property="Background" Value="{StaticResource B.Accent}"/>
        <Setter Property="Foreground" Value="{StaticResource B.AccentInk}"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Padding" Value="16,0"/>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.AccentHover}"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="{StaticResource B.AccentPressed}"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Background" Value="{StaticResource B.AccentDisabledBg}"/>
                <Setter Property="Foreground" Value="{StaticResource B.AccentDisabledInk}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.Secondary" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Base}">
        <Setter Property="Background" Value="{StaticResource B.Raised}"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.RaisedLine}"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Padding" Value="14,0"/>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.RaisedHover}"/>
                <Setter Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="{StaticResource B.RaisedPressed}"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Opacity" Value="0.5"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.Outline" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Base}">
        <Setter Property="BorderBrush" Value="{StaticResource B.InputLine}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.Raised}"/>
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                <Setter Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="{StaticResource B.RaisedPressed}"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Foreground" Value="{StaticResource B.Text4}"/>
                <Setter Property="BorderBrush" Value="{StaticResource B.Divider}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.Ghost" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Base}">
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Height" Value="26"/>
        <Setter Property="Padding" Value="8,0"/>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.Raised}"/>
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="{StaticResource B.RaisedPressed}"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Foreground" Value="{StaticResource B.Text4}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.Icon" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Outline}">
        <Setter Property="Width" Value="30"/>
        <Setter Property="Padding" Value="0"/>
        <Setter Property="FontFamily" Value="{StaticResource F.Icon}"/>
        <Setter Property="FontSize" Value="13"/>
    </Style>

    <Style x:Key="Btn.Small" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Outline}">
        <Setter Property="Height" Value="22"/>
        <Setter Property="Padding" Value="9,0"/>
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
    </Style>

    <Style x:Key="Btn.Header" TargetType="{x:Type Button}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text3}"/>
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type Button}">
                    <Border Background="Transparent" Padding="{TemplateBinding Padding}">
                        <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.HeaderIcon" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Header}">
        <Setter Property="FontFamily" Value="{StaticResource F.Icon}"/>
        <Setter Property="FontSize" Value="12"/>
        <Setter Property="Width" Value="28"/>
        <Setter Property="Height" Value="24"/>
        <Setter Property="Margin" Value="0,0,4,0"/>
        <Setter Property="HorizontalContentAlignment" Value="Center"/>
        <Style.Triggers>
            <Trigger Property="IsEnabled" Value="False">
                <Setter Property="Foreground" Value="{StaticResource B.Text4}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.Caption" TargetType="{x:Type Button}">
        <Setter Property="Width" Value="42"/>
        <Setter Property="Height" Value="32"/>
        <Setter Property="Focusable" Value="False"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type Button}">
                    <Border Background="{TemplateBinding Background}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.Raised}"/>
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="{StaticResource B.RaisedHover}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.CaptionClose" TargetType="{x:Type Button}" BasedOn="{StaticResource Btn.Caption}">
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
                <Setter Property="Background" Value="{StaticResource B.CloseHover}"/>
                <Setter Property="Foreground" Value="White"/>
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
                <Setter Property="Background" Value="#A3271A"/>
                <Setter Property="Foreground" Value="White"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Btn.NavSmall" TargetType="{x:Type Button}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text3}"/>
        <Setter Property="Height" Value="30"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type Button}">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="6" Padding="10,0">
                        <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.NavHover}"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Navigation item -->
    <Style x:Key="Nav.Item" TargetType="{x:Type RadioButton}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="Height" Value="34"/>
        <Setter Property="Margin" Value="0,0,0,2"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type RadioButton}">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="6">
                        <Grid>
                            <Border x:Name="Ind" Width="3" Height="16" CornerRadius="1.5" HorizontalAlignment="Left"
                                    VerticalAlignment="Center" Background="{StaticResource B.Accent}" Visibility="Collapsed"/>
                            <ContentPresenter Margin="10,0" VerticalAlignment="Center"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.NavHover}"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.NavActive}"/>
                            <Setter TargetName="Ind" Property="Visibility" Value="Visible"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Nav.Icon" TargetType="{x:Type TextBlock}">
        <Setter Property="FontFamily" Value="{StaticResource F.Icon}"/>
        <Setter Property="FontSize" Value="16"/>
        <Setter Property="Width" Value="16"/>
        <Setter Property="TextAlignment" Value="Center"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding IsChecked, RelativeSource={RelativeSource AncestorType={x:Type RadioButton}}}" Value="True">
                <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <!-- Filter chip / segment -->
    <Style x:Key="Chip" TargetType="{x:Type RadioButton}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="Height" Value="24"/>
        <Setter Property="Margin" Value="0,0,6,0"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type RadioButton}">
                    <Border x:Name="Bd" Background="Transparent" BorderBrush="{StaticResource B.HeadLine}" BorderThickness="1" CornerRadius="12" Padding="8,0">
                        <ContentPresenter VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.Raised}"/>
                            <Setter TargetName="Bd" Property="BorderBrush" Value="#3A404A"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Opacity" Value="0.5"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Segment" TargetType="{x:Type RadioButton}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="FontSize" Value="11.5"/>
        <Setter Property="Height" Value="22"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type RadioButton}">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Padding="10,0">
                        <ContentPresenter VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.SegOn}"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Check box / toggle switch -->
    <Style x:Key="Check" TargetType="{x:Type CheckBox}">
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type CheckBox}">
                    <Grid Background="Transparent">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>
                        <Border x:Name="Box" Width="14" Height="14" CornerRadius="3" BorderThickness="1"
                                BorderBrush="{StaticResource B.CheckLine}" Background="Transparent" VerticalAlignment="Center" SnapsToDevicePixels="True">
                            <Grid>
                                <Path x:Name="Mark" Data="M 2,6.2 L 4.7,8.9 L 9.9,3.4" Stroke="{StaticResource B.AccentInk}" StrokeThickness="1.8"
                                      StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed"/>
                                <Rectangle x:Name="Dash" Width="7" Height="1.8" RadiusX="0.9" RadiusY="0.9" Fill="{StaticResource B.AccentInk}" Visibility="Collapsed"/>
                            </Grid>
                        </Border>
                        <ContentPresenter x:Name="Cp" Grid.Column="1" Margin="8,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="HasContent" Value="False">
                            <Setter TargetName="Cp" Property="Visibility" Value="Collapsed"/>
                        </Trigger>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource B.CheckLineHover}"/>
                            <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
                        </Trigger>
                        <Trigger Property="IsKeyboardFocused" Value="True">
                            <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Box" Property="Background" Value="{StaticResource B.Accent}"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                            <Setter TargetName="Mark" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="{x:Null}">
                            <Setter TargetName="Box" Property="Background" Value="{StaticResource B.Accent}"/>
                            <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                            <Setter TargetName="Dash" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Opacity" Value="0.45"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Switch" TargetType="{x:Type CheckBox}">
        <Setter Property="FocusVisualStyle" Value="{StaticResource FocusRing}"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type CheckBox}">
                    <Border x:Name="Track" Width="32" Height="18" CornerRadius="9" Background="{StaticResource B.InputLine}">
                        <Ellipse x:Name="Knob" Width="12" Height="12" Margin="3,0" HorizontalAlignment="Left" Fill="{StaticResource B.Text3}"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Knob" Property="Fill" Value="{StaticResource B.Text2}"/>
                        </Trigger>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="Track" Property="Background" Value="{StaticResource B.Accent}"/>
                            <Setter TargetName="Knob" Property="HorizontalAlignment" Value="Right"/>
                            <Setter TargetName="Knob" Property="Fill" Value="{StaticResource B.AccentInk}"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Opacity" Value="0.45"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Scroll bar -->
    <Style x:Key="Scroll.Thumb" TargetType="{x:Type Thumb}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="IsTabStop" Value="False"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type Thumb}">
                    <Border x:Name="T" Background="{StaticResource B.ScrollThumb}" CornerRadius="3"/>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="T" Property="Background" Value="{StaticResource B.ScrollThumbHover}"/>
                        </Trigger>
                        <Trigger Property="IsDragging" Value="True">
                            <Setter TargetName="T" Property="Background" Value="{StaticResource B.ScrollThumbDrag}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Scroll.Page" TargetType="{x:Type RepeatButton}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="Focusable" Value="False"/>
        <Setter Property="IsTabStop" Value="False"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type RepeatButton}">
                    <Border Background="Transparent"/>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <ControlTemplate x:Key="Scroll.VTemplate" TargetType="{x:Type ScrollBar}">
        <Grid Background="Transparent" Margin="1,3,1,3">
            <Track x:Name="PART_Track" IsDirectionReversed="True">
                <Track.DecreaseRepeatButton>
                    <RepeatButton Command="ScrollBar.PageUpCommand" Style="{StaticResource Scroll.Page}"/>
                </Track.DecreaseRepeatButton>
                <Track.IncreaseRepeatButton>
                    <RepeatButton Command="ScrollBar.PageDownCommand" Style="{StaticResource Scroll.Page}"/>
                </Track.IncreaseRepeatButton>
                <Track.Thumb>
                    <Thumb Style="{StaticResource Scroll.Thumb}" MinHeight="24"/>
                </Track.Thumb>
            </Track>
        </Grid>
    </ControlTemplate>

    <ControlTemplate x:Key="Scroll.HTemplate" TargetType="{x:Type ScrollBar}">
        <Grid Background="Transparent" Margin="3,1,3,1">
            <Track x:Name="PART_Track" IsDirectionReversed="False">
                <Track.DecreaseRepeatButton>
                    <RepeatButton Command="ScrollBar.PageLeftCommand" Style="{StaticResource Scroll.Page}"/>
                </Track.DecreaseRepeatButton>
                <Track.IncreaseRepeatButton>
                    <RepeatButton Command="ScrollBar.PageRightCommand" Style="{StaticResource Scroll.Page}"/>
                </Track.IncreaseRepeatButton>
                <Track.Thumb>
                    <Thumb Style="{StaticResource Scroll.Thumb}" MinWidth="24"/>
                </Track.Thumb>
            </Track>
        </Grid>
    </ControlTemplate>

    <Style x:Key="Scroll.Bar" TargetType="{x:Type ScrollBar}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="SnapsToDevicePixels" Value="True"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Width" Value="9"/>
        <Setter Property="MinWidth" Value="9"/>
        <Setter Property="Height" Value="Auto"/>
        <Setter Property="Template" Value="{StaticResource Scroll.VTemplate}"/>
        <Style.Triggers>
            <Trigger Property="Orientation" Value="Horizontal">
                <Setter Property="Width" Value="Auto"/>
                <Setter Property="MinWidth" Value="0"/>
                <Setter Property="Height" Value="9"/>
                <Setter Property="MinHeight" Value="9"/>
                <Setter Property="Template" Value="{StaticResource Scroll.HTemplate}"/>
            </Trigger>
        </Style.Triggers>
    </Style>

    <Style TargetType="{x:Type ScrollBar}" BasedOn="{StaticResource Scroll.Bar}"/>

    <Style x:Key="Scroll.Thin" TargetType="{x:Type ScrollViewer}">
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ScrollViewer}">
                    <Grid>
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="*"/>
                            <RowDefinition Height="Auto"/>
                        </Grid.RowDefinitions>
                        <ScrollContentPresenter x:Name="PART_ScrollContentPresenter" Margin="{TemplateBinding Padding}"
                                                CanContentScroll="{TemplateBinding CanContentScroll}"/>
                        <ScrollBar x:Name="PART_VerticalScrollBar" Grid.Column="1" Orientation="Vertical"
                                   Maximum="{TemplateBinding ScrollableHeight}" ViewportSize="{TemplateBinding ViewportHeight}"
                                   Value="{TemplateBinding VerticalOffset}" Visibility="{TemplateBinding ComputedVerticalScrollBarVisibility}"
                                   Style="{StaticResource Scroll.Bar}"/>
                        <ScrollBar x:Name="PART_HorizontalScrollBar" Grid.Row="1" Orientation="Horizontal"
                                   Maximum="{TemplateBinding ScrollableWidth}" ViewportSize="{TemplateBinding ViewportWidth}"
                                   Value="{TemplateBinding HorizontalOffset}" Visibility="{TemplateBinding ComputedHorizontalScrollBarVisibility}"
                                   Style="{StaticResource Scroll.Bar}"/>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style TargetType="{x:Type ScrollViewer}" BasedOn="{StaticResource Scroll.Thin}"/>

    <Style x:Key="Scroll.Overlay" TargetType="{x:Type ScrollViewer}">
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ScrollViewer}">
                    <Grid>
                        <ScrollContentPresenter x:Name="PART_ScrollContentPresenter" Margin="{TemplateBinding Padding}"
                                                CanContentScroll="{TemplateBinding CanContentScroll}"/>
                        <ScrollBar x:Name="PART_VerticalScrollBar" HorizontalAlignment="Right" Orientation="Vertical"
                                   Maximum="{TemplateBinding ScrollableHeight}" ViewportSize="{TemplateBinding ViewportHeight}"
                                   Value="{TemplateBinding VerticalOffset}" Visibility="{TemplateBinding ComputedVerticalScrollBarVisibility}"
                                   Style="{StaticResource Scroll.Bar}"/>
                        <ScrollBar x:Name="PART_HorizontalScrollBar" VerticalAlignment="Bottom" Orientation="Horizontal"
                                   Maximum="{TemplateBinding ScrollableWidth}" ViewportSize="{TemplateBinding ViewportWidth}"
                                   Value="{TemplateBinding HorizontalOffset}" Visibility="{TemplateBinding ComputedHorizontalScrollBarVisibility}"
                                   Style="{StaticResource Scroll.Bar}"/>
                    </Grid>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Combo box -->
    <Style x:Key="Combo.Item" TargetType="{x:Type ComboBoxItem}">
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Padding" Value="8,5"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ComboBoxItem}">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="5" Padding="{TemplateBinding Padding}">
                        <ContentPresenter/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsHighlighted" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.PopupHover}"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <DataTemplate x:Key="Combo.OptionTemplate">
        <TextBlock Text="{Binding Label}" TextTrimming="CharacterEllipsis"/>
    </DataTemplate>

    <Style x:Key="Combo.Field" TargetType="{x:Type ComboBox}">
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Background" Value="{StaticResource B.Input}"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.InputLine}"/>
        <Setter Property="Height" Value="30"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="MaxDropDownHeight" Value="320"/>
        <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
        <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Auto"/>
        <Setter Property="ItemContainerStyle" Value="{StaticResource Combo.Item}"/>
        <Setter Property="ItemTemplate" Value="{StaticResource Combo.OptionTemplate}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ComboBox}">
                    <Grid SnapsToDevicePixels="True">
                        <ToggleButton x:Name="Toggle" Focusable="False" ClickMode="Press"
                                      Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                                      IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                            <ToggleButton.Template>
                                <ControlTemplate TargetType="{x:Type ToggleButton}">
                                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                                            BorderThickness="1" CornerRadius="6">
                                        <TextBlock Text="&#xE70D;" FontFamily="{StaticResource F.Icon}" FontSize="9" Margin="0,0,10,0"
                                                   HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="{StaticResource B.Text3}"/>
                                    </Border>
                                    <ControlTemplate.Triggers>
                                        <Trigger Property="IsMouseOver" Value="True">
                                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
                                        </Trigger>
                                        <Trigger Property="IsChecked" Value="True">
                                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                                        </Trigger>
                                    </ControlTemplate.Triggers>
                                </ControlTemplate>
                            </ToggleButton.Template>
                        </ToggleButton>
                        <Grid Margin="10,0,26,0" IsHitTestVisible="False" VerticalAlignment="Center">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <TextBlock Text="{TemplateBinding Tag}" Foreground="{StaticResource B.Text3}" FontSize="11" Margin="0,0,8,0" VerticalAlignment="Center"/>
                            <ContentPresenter Grid.Column="1" VerticalAlignment="Center"
                                              Content="{TemplateBinding SelectionBoxItem}"
                                              ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"
                                              ContentStringFormat="{TemplateBinding SelectionBoxItemStringFormat}"/>
                        </Grid>
                        <Popup x:Name="PART_Popup" Placement="Bottom" VerticalOffset="4" AllowsTransparency="True" Focusable="False"
                               PopupAnimation="Fade" IsOpen="{TemplateBinding IsDropDownOpen}">
                            <Border Background="{StaticResource B.Popup}" BorderBrush="{StaticResource B.PopupLine}" BorderThickness="1"
                                    CornerRadius="7" Padding="4" SnapsToDevicePixels="True"
                                    MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}"
                                    MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                <ScrollViewer Style="{StaticResource Scroll.Thin}" CanContentScroll="True">
                                    <ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/>
                                </ScrollViewer>
                            </Border>
                        </Popup>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsKeyboardFocusWithin" Value="True">
                            <Setter TargetName="Toggle" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                        </Trigger>
                        <Trigger Property="HasItems" Value="False">
                            <Setter Property="Opacity" Value="0.6"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Opacity" Value="0.5"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Text boxes -->
    <Style x:Key="Text.Search" TargetType="{x:Type TextBox}">
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="CaretBrush" Value="{StaticResource B.Text}"/>
        <Setter Property="SelectionBrush" Value="{StaticResource B.Accent}"/>
        <Setter Property="Background" Value="{StaticResource B.Card}"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.Divider}"/>
        <Setter Property="Height" Value="26"/>
        <Setter Property="FontSize" Value="11.5"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type TextBox}">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="6">
                        <Grid Margin="9,0,6,0">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <TextBlock Text="&#xE721;" FontFamily="{StaticResource F.Icon}" FontSize="11" Foreground="{StaticResource B.Text3}"
                                       VerticalAlignment="Center" Margin="0,0,7,0"/>
                            <TextBlock x:Name="Ph" Grid.Column="1" Text="{TemplateBinding Tag}" Foreground="{StaticResource B.Text3}"
                                       VerticalAlignment="Center" Visibility="Collapsed" IsHitTestVisible="False" TextTrimming="CharacterEllipsis"/>
                            <ScrollViewer x:Name="PART_ContentHost" Grid.Column="1" VerticalAlignment="Center" Focusable="False"
                                          HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="Text" Value="">
                            <Setter TargetName="Ph" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
                        </Trigger>
                        <Trigger Property="IsKeyboardFocused" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Text.Field" TargetType="{x:Type TextBox}">
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="CaretBrush" Value="{StaticResource B.Text}"/>
        <Setter Property="SelectionBrush" Value="{StaticResource B.Accent}"/>
        <Setter Property="Background" Value="{StaticResource B.Input}"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.InputLine}"/>
        <Setter Property="Height" Value="28"/>
        <Setter Property="FontFamily" Value="{StaticResource F.Mono}"/>
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type TextBox}">
                    <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="6" Padding="7,0">
                        <ScrollViewer x:Name="PART_ContentHost" VerticalAlignment="Center" Focusable="False"
                                      HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.InputLineHover}"/>
                        </Trigger>
                        <Trigger Property="IsKeyboardFocused" Value="True">
                            <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource B.Accent}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Row lists -->
    <Style x:Key="List.Rows" TargetType="{x:Type ListBox}">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="SelectionMode" Value="Extended"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
        <Setter Property="ScrollViewer.CanContentScroll" Value="True"/>
        <Setter Property="VirtualizingPanel.IsVirtualizing" Value="True"/>
        <Setter Property="VirtualizingPanel.VirtualizationMode" Value="Recycling"/>
        <Setter Property="VirtualizingPanel.ScrollUnit" Value="Pixel"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ListBox}">
                    <ScrollViewer Style="{StaticResource Scroll.Overlay}" Focusable="False" CanContentScroll="True" Padding="0"
                                  HorizontalScrollBarVisibility="Disabled">
                        <ItemsPresenter/>
                    </ScrollViewer>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="List.RowItem" TargetType="{x:Type ListBoxItem}">
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Padding" Value="0"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ListBoxItem}">
                    <Border x:Name="Bd" Background="Transparent" BorderBrush="{StaticResource B.RowLine}" BorderThickness="0,0,0,1" SnapsToDevicePixels="True">
                        <Grid>
                            <Border x:Name="Tint" Background="{StaticResource B.AccentRow}" Visibility="Collapsed"/>
                            <Border x:Name="Hover" Background="{StaticResource B.RowHover}" Visibility="Collapsed"/>
                            <Border x:Name="Sel" Background="{StaticResource B.RowSelected}" Visibility="Collapsed"/>
                            <Border x:Name="SelBar" Width="2" HorizontalAlignment="Left" Background="{StaticResource B.Accent}" Visibility="Collapsed"/>
                            <ContentPresenter/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <DataTrigger Binding="{Binding IsChecked}" Value="True">
                            <Setter TargetName="Tint" Property="Visibility" Value="Visible"/>
                        </DataTrigger>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Hover" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter TargetName="Sel" Property="Visibility" Value="Visible"/>
                        </Trigger>
                        <MultiTrigger>
                            <MultiTrigger.Conditions>
                                <Condition Property="IsSelected" Value="True"/>
                                <Condition Property="IsKeyboardFocusWithin" Value="True"/>
                            </MultiTrigger.Conditions>
                            <Setter TargetName="SelBar" Property="Visibility" Value="Visible"/>
                        </MultiTrigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="List.LogItem" TargetType="{x:Type ListBoxItem}">
        <Setter Property="FocusVisualStyle" Value="{x:Null}"/>
        <Setter Property="Padding" Value="0"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ListBoxItem}">
                    <Border x:Name="Bd" Background="Transparent" BorderBrush="{StaticResource B.RowLine}" BorderThickness="0,0,0,1" SnapsToDevicePixels="True">
                        <ContentPresenter/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.RowHover}"/>
                        </Trigger>
                        <Trigger Property="IsSelected" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.RowSelected}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Progress bars -->
    <Style x:Key="Progress.Line" TargetType="{x:Type ProgressBar}">
        <Setter Property="Height" Value="2"/>
        <Setter Property="Minimum" Value="0"/>
        <Setter Property="Maximum" Value="100"/>
        <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="IsHitTestVisible" Value="False"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ProgressBar}">
                    <Grid ClipToBounds="True" Background="{TemplateBinding Background}">
                        <Border x:Name="PART_Track"/>
                        <Border x:Name="PART_Indicator" HorizontalAlignment="Left" Background="{TemplateBinding Foreground}"/>
                        <Border x:Name="Glow" Width="140" HorizontalAlignment="Left" Background="{TemplateBinding Foreground}" Visibility="Collapsed">
                            <Border.RenderTransform>
                                <TranslateTransform X="-140"/>
                            </Border.RenderTransform>
                        </Border>
                    </Grid>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsIndeterminate" Value="True">
                            <Setter TargetName="PART_Indicator" Property="Visibility" Value="Collapsed"/>
                            <Setter TargetName="Glow" Property="Visibility" Value="Visible"/>
                            <Trigger.EnterActions>
                                <BeginStoryboard x:Name="Sweep">
                                    <Storyboard RepeatBehavior="Forever">
                                        <DoubleAnimation Storyboard.TargetName="Glow"
                                                         Storyboard.TargetProperty="(UIElement.RenderTransform).(TranslateTransform.X)"
                                                         From="-140" To="1900" Duration="0:0:2.2"/>
                                    </Storyboard>
                                </BeginStoryboard>
                            </Trigger.EnterActions>
                            <Trigger.ExitActions>
                                <StopStoryboard BeginStoryboardName="Sweep"/>
                            </Trigger.ExitActions>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="Progress.Mini" TargetType="{x:Type ProgressBar}">
        <Setter Property="Height" Value="4"/>
        <Setter Property="Minimum" Value="0"/>
        <Setter Property="Maximum" Value="100"/>
        <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
        <Setter Property="Background" Value="{StaticResource B.Divider}"/>
        <Setter Property="IsHitTestVisible" Value="False"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ProgressBar}">
                    <Border CornerRadius="2" Background="{TemplateBinding Background}" ClipToBounds="True">
                        <Grid>
                            <Border x:Name="PART_Track"/>
                            <Border x:Name="PART_Indicator" HorizontalAlignment="Left" CornerRadius="2" Background="{TemplateBinding Foreground}"/>
                        </Grid>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Tooltip / context menu -->
    <Style TargetType="{x:Type ToolTip}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Background" Value="{StaticResource B.Tooltip}"/>
        <Setter Property="BorderBrush" Value="#3A404A"/>
        <Setter Property="FontSize" Value="11.5"/>
        <Setter Property="Padding" Value="9,6"/>
        <Setter Property="HasDropShadow" Value="False"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ToolTip}">
                    <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1"
                            CornerRadius="6" Padding="{TemplateBinding Padding}" MaxWidth="460">
                        <ContentPresenter>
                            <ContentPresenter.Resources>
                                <Style TargetType="{x:Type TextBlock}">
                                    <Setter Property="TextWrapping" Value="Wrap"/>
                                </Style>
                            </ContentPresenter.Resources>
                        </ContentPresenter>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style TargetType="{x:Type ContextMenu}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="FontSize" Value="12"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type ContextMenu}">
                    <Border Background="{StaticResource B.Popup}" BorderBrush="{StaticResource B.PopupLine}" BorderThickness="1" CornerRadius="7" Padding="4">
                        <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style TargetType="{x:Type MenuItem}">
        <Setter Property="OverridesDefaultStyle" Value="True"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="{x:Type MenuItem}">
                    <Border x:Name="Bd" Background="Transparent" CornerRadius="5" Padding="10,5" MinWidth="150">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="Auto"/>
                            </Grid.ColumnDefinitions>
                            <ContentPresenter ContentSource="Header" RecognizesAccessKey="True" VerticalAlignment="Center"/>
                            <TextBlock Grid.Column="1" Text="{TemplateBinding InputGestureText}" Foreground="{StaticResource B.Text3}" Margin="18,0,0,0" VerticalAlignment="Center"/>
                        </Grid>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsHighlighted" Value="True">
                            <Setter TargetName="Bd" Property="Background" Value="{StaticResource B.PopupHover}"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Foreground" Value="{StaticResource B.Text4}"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Text styles -->
    <Style x:Key="T.Section" TargetType="{x:Type TextBlock}">
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text3}"/>
        <Setter Property="Margin" Value="0,0,0,10"/>
    </Style>

    <Style x:Key="T.Hint" TargetType="{x:Type TextBlock}">
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text3}"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
    </Style>

    <Style x:Key="T.Label" TargetType="{x:Type TextBlock}">
        <Setter Property="FontWeight" Value="SemiBold"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
    </Style>

    <Style x:Key="T.RowName" TargetType="{x:Type TextBlock}">
        <Setter Property="FontWeight" Value="Normal"/>
        <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Category}" Value="lp">
                <Setter Property="FontWeight" Value="SemiBold"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <!-- Listed-selection info in the list header; switches to the warning color when the selection changes -->
    <Style x:Key="T.ListInfo" TargetType="{x:Type TextBlock}">
        <Setter Property="FontSize" Value="10.5"/>
        <Setter Property="Foreground" Value="{StaticResource B.Text4}"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
        <Setter Property="Margin" Value="8,0,10,0"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding IsStale}" Value="True">
                <Setter Property="Foreground" Value="{StaticResource B.Warn}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="T.Status" TargetType="{x:Type TextBlock}">
        <Setter Property="Foreground" Value="{StaticResource B.Text3}"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding StateKey}" Value="Queued">
                <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Resolving">
                <Setter Property="Foreground" Value="{StaticResource B.Info}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Downloading">
                <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Verifying">
                <Setter Property="Foreground" Value="{StaticResource B.Info}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Extracting">
                <Setter Property="Foreground" Value="{StaticResource B.Info}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Partial">
                <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Done">
                <Setter Property="Foreground" Value="{StaticResource B.OkText}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Exists">
                <Setter Property="Foreground" Value="{StaticResource B.OkText}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Error">
                <Setter Property="Foreground" Value="{StaticResource B.Err}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StateKey}" Value="Cancelled">
                <Setter Property="Foreground" Value="{StaticResource B.Warn}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="T.LogLevel" TargetType="{x:Type TextBlock}">
        <Setter Property="FontFamily" Value="{StaticResource F.Icon}"/>
        <Setter Property="FontSize" Value="11"/>
        <Setter Property="Foreground" Value="{StaticResource B.Info}"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Level}" Value="error">
                <Setter Property="Foreground" Value="{StaticResource B.Err}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Level}" Value="warn">
                <Setter Property="Foreground" Value="{StaticResource B.Warn}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Level}" Value="ok">
                <Setter Property="Foreground" Value="{StaticResource B.Ok}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="T.LogMessage" TargetType="{x:Type TextBlock}">
        <Setter Property="Foreground" Value="{StaticResource B.Text2}"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
        <Setter Property="VerticalAlignment" Value="Center"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Level}" Value="error">
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Level}" Value="ok">
                <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="T.DetailValue" TargetType="{x:Type TextBlock}">
        <Setter Property="Foreground" Value="{StaticResource B.Text}"/>
        <Setter Property="TextTrimming" Value="CharacterEllipsis"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Emphasis}" Value="True">
                <Setter Property="Foreground" Value="{StaticResource B.Accent}"/>
                <Setter Property="FontWeight" Value="SemiBold"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <!-- Dots / badges -->
    <Style x:Key="Dot.Category" TargetType="{x:Type Ellipse}">
        <Setter Property="Width" Value="7"/>
        <Setter Property="Height" Value="7"/>
        <Setter Property="Fill" Value="{StaticResource B.CatFod}"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Category}" Value="lp">
                <Setter Property="Fill" Value="{StaticResource B.CatLp}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Category}" Value="feature">
                <Setter Property="Fill" Value="{StaticResource B.CatFeature}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Category}" Value="core">
                <Setter Property="Fill" Value="{StaticResource B.CatFeature}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Category}" Value="server">
                <Setter Property="Fill" Value="{StaticResource B.CatServer}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Dot.Status" TargetType="{x:Type Ellipse}">
        <Setter Property="Width" Value="7"/>
        <Setter Property="Height" Value="7"/>
        <Setter Property="Fill" Value="{StaticResource B.Ok}"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding StatusLevel}" Value="busy">
                <Setter Property="Fill" Value="{StaticResource B.Accent}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StatusLevel}" Value="info">
                <Setter Property="Fill" Value="{StaticResource B.Info}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StatusLevel}" Value="warn">
                <Setter Property="Fill" Value="{StaticResource B.Warn}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding StatusLevel}" Value="error">
                <Setter Property="Fill" Value="{StaticResource B.Err}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Badge" TargetType="{x:Type Border}">
        <Setter Property="MinWidth" Value="18"/>
        <Setter Property="Height" Value="16"/>
        <Setter Property="CornerRadius" Value="8"/>
        <Setter Property="Padding" Value="5,0"/>
        <Setter Property="Background" Value="{StaticResource B.Raised}"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding LogVm.BadgeIsError}" Value="True">
                <Setter Property="Background" Value="{StaticResource B.ErrSoft}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>

    <Style x:Key="Card" TargetType="{x:Type Border}">
        <Setter Property="Background" Value="{StaticResource B.Card}"/>
        <Setter Property="BorderBrush" Value="{StaticResource B.CardLine}"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="CornerRadius" Value="7"/>
    </Style>

    <Style x:Key="Card.Section" TargetType="{x:Type Border}" BasedOn="{StaticResource Card}">
        <Setter Property="Padding" Value="14,12"/>
        <Setter Property="Margin" Value="0,0,0,10"/>
    </Style>

    <Style x:Key="Dialog.IconBg" TargetType="{x:Type Border}">
        <Setter Property="Width" Value="28"/>
        <Setter Property="Height" Value="28"/>
        <Setter Property="CornerRadius" Value="14"/>
        <Setter Property="Background" Value="{StaticResource B.InfoSoft}"/>
        <Setter Property="TextElement.Foreground" Value="{StaticResource B.Info}"/>
        <Style.Triggers>
            <DataTrigger Binding="{Binding Kind}" Value="download">
                <Setter Property="Background" Value="{StaticResource B.AccentSoft}"/>
                <Setter Property="TextElement.Foreground" Value="{StaticResource B.Accent}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Kind}" Value="clean">
                <Setter Property="Background" Value="{StaticResource B.ErrSoft}"/>
                <Setter Property="TextElement.Foreground" Value="{StaticResource B.Err}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Kind}" Value="error">
                <Setter Property="Background" Value="{StaticResource B.ErrSoft}"/>
                <Setter Property="TextElement.Foreground" Value="{StaticResource B.Err}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Kind}" Value="warn">
                <Setter Property="Background" Value="{StaticResource B.WarnSoft}"/>
                <Setter Property="TextElement.Foreground" Value="{StaticResource B.Warn}"/>
            </DataTrigger>
            <DataTrigger Binding="{Binding Kind}" Value="ok">
                <Setter Property="Background" Value="#243FB97A"/>
                <Setter Property="TextElement.Foreground" Value="{StaticResource B.Ok}"/>
            </DataTrigger>
        </Style.Triggers>
    </Style>
</ResourceDictionary>
'@

$script:XamlLayout = @'
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        xmlns:shell="clr-namespace:System.Windows.Shell;assembly=PresentationFramework"
        x:Name="WindowFrame" Background="{DynamicResource B.Bg}" BorderBrush="{DynamicResource B.Frame}" BorderThickness="1">
    <Border.Resources>
        <BooleanToVisibilityConverter x:Key="BoolToVisL"/>
    </Border.Resources>
    <Grid x:Name="RootGrid">
        <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto"/>
            <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <!-- Navigation -->
        <Border Grid.Column="0" Width="{Binding NavWidth}" Background="{DynamicResource B.Side}"
                BorderBrush="{DynamicResource B.SideLine}" BorderThickness="0,0,1,0">
            <DockPanel Margin="8,10,8,10" LastChildFill="True">
                <Grid DockPanel.Dock="Top" Height="32" Margin="5,0,0,12">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="Auto"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>
                    <Border Width="26" Height="26" CornerRadius="7" Background="#1C2028" BorderBrush="#2F3541" BorderThickness="1"
                            VerticalAlignment="Center">
                        <Viewbox Width="18" Height="18">
                            <Canvas Width="64" Height="64">
                                <Rectangle Canvas.Left="10" Canvas.Top="10" Width="19" Height="19" RadiusX="3.2" RadiusY="3.2" Fill="#6EB4FF"/>
                                <Rectangle Canvas.Left="33" Canvas.Top="10" Width="19" Height="19" RadiusX="3.2" RadiusY="3.2" Fill="#479EF5"/>
                                <Rectangle Canvas.Left="10" Canvas.Top="33" Width="19" Height="19" RadiusX="3.2" RadiusY="3.2" Fill="#2880DA"/>
                                <Rectangle Canvas.Left="33" Canvas.Top="33" Width="21" Height="21" RadiusX="3.6" RadiusY="3.6" Fill="{DynamicResource B.Accent}"/>
                                <Path Data="M41.7,37.5 H45.3 V43.8 H49.5 L43.5,50 L37.5,43.8 H41.7 Z" Fill="#15171C"/>
                            </Canvas>
                        </Viewbox>
                    </Border>
                    <StackPanel Grid.Column="1" Margin="9,0,0,0" VerticalAlignment="Center" Visibility="{Binding NavLabelVisibility}">
                        <TextBlock Text="{Binding L[App_Name]}" FontSize="13" FontWeight="SemiBold"/>
                        <TextBlock Text="{Binding L[App_Sub]}" FontSize="10.5" Foreground="{DynamicResource B.Text3}"/>
                    </StackPanel>
                </Grid>

                <StackPanel DockPanel.Dock="Bottom">
                    <Button Style="{DynamicResource Btn.NavSmall}" Command="{Binding ToggleNavCommand}" ToolTip="{Binding NavCollapseText}">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Text="{Binding NavCollapseGlyph}" FontFamily="{DynamicResource F.Icon}" FontSize="12" Width="16"
                                       TextAlignment="Center" VerticalAlignment="Center"/>
                            <TextBlock Text="{Binding NavCollapseText}" FontSize="11.5" Margin="10,0,0,0" VerticalAlignment="Center"
                                       Visibility="{Binding NavLabelVisibility}"/>
                        </StackPanel>
                    </Button>
                    <TextBlock Text="{Binding VersionText}" FontSize="10.5" Foreground="{DynamicResource B.Text3}" Margin="10,4,0,0"
                               TextTrimming="CharacterEllipsis" Visibility="{Binding NavLabelVisibility}"/>
                </StackPanel>

                <StackPanel>
                    <RadioButton GroupName="nav" Style="{DynamicResource Nav.Item}" IsChecked="{Binding IsLangPage, Mode=TwoWay}"
                                 ToolTip="{Binding L[Nav_Lang]}" AutomationProperties.Name="{Binding L[Nav_Lang]}">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <Grid>
                                <TextBlock Text="&#xE774;" Style="{DynamicResource Nav.Icon}"/>
                                <Ellipse Width="6" Height="6" Fill="{DynamicResource B.Accent}" HorizontalAlignment="Right" VerticalAlignment="Top"
                                         Margin="0,-2,-3,0" Visibility="{Binding LangBusyVisibility}"/>
                            </Grid>
                            <TextBlock Grid.Column="1" Text="{Binding L[Nav_Lang]}" Margin="10,0,0,0" VerticalAlignment="Center"
                                       TextTrimming="CharacterEllipsis" Visibility="{Binding NavLabelVisibility}"/>
                        </Grid>
                    </RadioButton>
                    <RadioButton GroupName="nav" Style="{DynamicResource Nav.Item}" IsChecked="{Binding IsPePage, Mode=TwoWay}"
                                 ToolTip="{Binding L[Nav_Pe]}" AutomationProperties.Name="{Binding L[Nav_Pe]}">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <Grid>
                                <TextBlock Text="&#xE7B8;" Style="{DynamicResource Nav.Icon}"/>
                                <Ellipse Width="6" Height="6" Fill="{DynamicResource B.Accent}" HorizontalAlignment="Right" VerticalAlignment="Top"
                                         Margin="0,-2,-3,0" Visibility="{Binding PeBusyVisibility}"/>
                            </Grid>
                            <TextBlock Grid.Column="1" Text="{Binding L[Nav_Pe]}" Margin="10,0,0,0" VerticalAlignment="Center"
                                       TextTrimming="CharacterEllipsis" Visibility="{Binding NavLabelVisibility}"/>
                        </Grid>
                    </RadioButton>
                    <Rectangle Height="1" Fill="{DynamicResource B.Divider2}" Margin="6,6,6,8"/>
                    <RadioButton GroupName="nav" Style="{DynamicResource Nav.Item}" IsChecked="{Binding IsLogPage, Mode=TwoWay}"
                                 ToolTip="{Binding L[Nav_Log]}" AutomationProperties.Name="{Binding L[Nav_Log]}">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="Auto"/>
                            </Grid.ColumnDefinitions>
                            <Grid>
                                <TextBlock Text="&#xE8FD;" Style="{DynamicResource Nav.Icon}"/>
                                <Ellipse Width="6" Height="6" Fill="{DynamicResource B.Err}" HorizontalAlignment="Right" VerticalAlignment="Top"
                                         Margin="0,-2,-3,0" Visibility="{Binding LogVm.DotVisibility}"/>
                            </Grid>
                            <TextBlock Grid.Column="1" Text="{Binding L[Nav_Log]}" Margin="10,0,0,0" VerticalAlignment="Center"
                                       TextTrimming="CharacterEllipsis" Visibility="{Binding NavLabelVisibility}"/>
                            <Border Grid.Column="2" Style="{DynamicResource Badge}" Visibility="{Binding LogVm.BadgeVisibility}" VerticalAlignment="Center">
                                <TextBlock Text="{Binding LogVm.BadgeText}" FontSize="10" Foreground="{DynamicResource B.Text2}"
                                           HorizontalAlignment="Center" VerticalAlignment="Center"/>
                            </Border>
                        </Grid>
                    </RadioButton>
                    <RadioButton GroupName="nav" Style="{DynamicResource Nav.Item}" IsChecked="{Binding IsSettingsPage, Mode=TwoWay}"
                                 ToolTip="{Binding L[Nav_Settings]}" AutomationProperties.Name="{Binding L[Nav_Settings]}">
                        <Grid>
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <TextBlock Text="&#xE713;" Style="{DynamicResource Nav.Icon}"/>
                            <TextBlock Grid.Column="1" Text="{Binding L[Nav_Settings]}" Margin="10,0,0,0" VerticalAlignment="Center"
                                       TextTrimming="CharacterEllipsis" Visibility="{Binding NavLabelVisibility}"/>
                        </Grid>
                    </RadioButton>
                </StackPanel>
            </DockPanel>
        </Border>

        <!-- Content -->
        <Grid Grid.Column="1">
            <Grid.RowDefinitions>
                <RowDefinition Height="46"/>
                <RowDefinition Height="*"/>
                <RowDefinition Height="30"/>
            </Grid.RowDefinitions>

            <!-- Page title -->
            <Grid Grid.Row="0">
                <StackPanel Margin="16,9,140,0" VerticalAlignment="Top">
                    <TextBlock Text="{Binding PageTitle}" FontSize="14" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/>
                    <TextBlock Text="{Binding PageSubtitle}" FontSize="11" Foreground="{DynamicResource B.Text3}" TextTrimming="CharacterEllipsis"/>
                </StackPanel>
            </Grid>

            <!-- Pages -->
            <Grid Grid.Row="1">

                <!-- Language packs -->
                <Grid Visibility="{Binding LangVisibility}">
                <Grid DataContext="{Binding Lang}">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="46"/>
                    </Grid.RowDefinitions>

                    <Grid Grid.Row="0" Margin="16,2,16,0" IsEnabled="{Binding IsIdle}">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="1.25*"/>
                            <ColumnDefinition Width="128"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <ComboBox Grid.Column="0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Version]}"
                                  ItemsSource="{Binding Versions}" SelectedItem="{Binding SelectedVersion, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Version]}"/>
                        <ComboBox Grid.Column="1" Margin="8,0,0,0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Arch]}"
                                  ItemsSource="{Binding Archs}" SelectedItem="{Binding SelectedArch, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Arch]}"/>
                        <ComboBox Grid.Column="2" Margin="8,0,0,0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Lang]}"
                                  ItemsSource="{Binding Languages}" SelectedItem="{Binding SelectedLanguage, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Lang]}"/>
                        <Button Grid.Column="3" Margin="8,0,0,0" Style="{DynamicResource Btn.Secondary}" Command="{Binding FetchCommand}"
                                ToolTip="{Binding L[Tip_Fetch]}">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE72C;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Btn_List]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                    </Grid>

                    <Grid Grid.Row="1" Margin="16,10,16,8">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="1000*" MinWidth="120" MaxWidth="210"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>
                        <TextBox x:Name="LangSearch" Grid.Column="0" Style="{DynamicResource Text.Search}"
                                 Tag="{Binding L[Lang_Search]}" ToolTip="{Binding L[Tip_Search]}"
                                 Text="{Binding Search, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged, Delay=150}"
                                 AutomationProperties.Name="{Binding L[Lang_Search]}"/>
                        <Rectangle Grid.Column="1" Width="1" Height="16" Fill="{DynamicResource B.Divider}" Margin="10,0,10,0"/>
                        <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                            <RadioButton GroupName="langFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterAll, Mode=TwoWay}">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="{Binding L[Chip_All]}"/>
                                    <TextBlock Text="{Binding CountAll}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="langFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterLp, Mode=TwoWay}"
                                         Visibility="{Binding LpChipVisibility}" ToolTip="{Binding L[Cat_lp]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatLp}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Lp]}"/>
                                    <TextBlock Text="{Binding CountLp}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="langFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterFeature, Mode=TwoWay}"
                                         Visibility="{Binding FeatureChipVisibility}" ToolTip="{Binding L[Cat_feature]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatFeature}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Feature]}"/>
                                    <TextBlock Text="{Binding CountFeature}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="langFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterFod, Mode=TwoWay}"
                                         Visibility="{Binding FodChipVisibility}" ToolTip="{Binding L[Cat_fod]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatFod}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Fod]}"/>
                                    <TextBlock Text="{Binding CountFod}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="langFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterServer, Mode=TwoWay}"
                                         Visibility="{Binding ServerChipVisibility}" ToolTip="{Binding L[Cat_server]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatServer}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Server]}"/>
                                    <TextBlock Text="{Binding CountServer}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                        </StackPanel>
                    </Grid>

                    <Border Grid.Row="2" Margin="16,0,16,0" Style="{DynamicResource Card}">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="28"/>
                                <RowDefinition Height="*"/>
                            </Grid.RowDefinitions>
                            <Border Grid.Row="0" Background="{DynamicResource B.CardHead}" BorderBrush="{DynamicResource B.HeadLine}"
                                    BorderThickness="0,0,0,1" CornerRadius="7,7,0,0">
                                <Grid>
                                    <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="34"/>
                                        <ColumnDefinition Width="*"/>
                                        <ColumnDefinition Width="80"/>
                                        <ColumnDefinition Width="128"/>
                                    </Grid.ColumnDefinitions>
                                    <CheckBox Grid.Column="0" Style="{DynamicResource Check}" HorizontalAlignment="Center" VerticalAlignment="Center"
                                              IsChecked="{Binding HeaderChecked, Mode=TwoWay}" IsEnabled="{Binding IsIdle}"
                                              ToolTip="{Binding L[Tip_ToggleVisible]}" AutomationProperties.Name="{Binding L[Tip_ToggleVisible]}"/>
                                    <DockPanel Grid.Column="1" LastChildFill="True">
                                        <Button DockPanel.Dock="Left" Style="{DynamicResource Btn.Header}" Command="{Binding SortCommand}" CommandParameter="Name">
                                            <StackPanel Orientation="Horizontal">
                                                <TextBlock Text="{Binding L[Col_File]}"/>
                                                <TextBlock Text="{Binding NameSortGlyph}" FontFamily="{DynamicResource F.Icon}" FontSize="8" Margin="5,1,0,0" VerticalAlignment="Center"/>
                                            </StackPanel>
                                        </Button>
                                        <TextBlock Text="{Binding InfoText}" Style="{DynamicResource T.ListInfo}" ToolTip="{Binding InfoText}"/>
                                    </DockPanel>
                                    <Button Grid.Column="2" Style="{DynamicResource Btn.Header}" Command="{Binding SortCommand}" CommandParameter="Size"
                                            HorizontalContentAlignment="Right" Padding="0,0,14,0">
                                        <StackPanel Orientation="Horizontal">
                                            <TextBlock Text="{Binding SizeSortGlyph}" FontFamily="{DynamicResource F.Icon}" FontSize="8" Margin="0,1,5,0" VerticalAlignment="Center"/>
                                            <TextBlock Text="{Binding L[Col_Size]}"/>
                                        </StackPanel>
                                    </Button>
                                    <DockPanel Grid.Column="3" LastChildFill="True">
                                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.HeaderIcon}" Command="{Binding ClearListCommand}" Content="&#xE75C;"
                                                ToolTip="{Binding L[Tip_ClearList]}" AutomationProperties.Name="{Binding L[Tip_ClearList]}"/>
                                        <TextBlock Text="{Binding L[Col_Status]}" FontSize="11" Foreground="{DynamicResource B.Text3}" VerticalAlignment="Center"/>
                                    </DockPanel>
                                </Grid>
                            </Border>
                            <ListBox x:Name="LangList" Grid.Row="1" Style="{DynamicResource List.Rows}" VirtualizingPanel.IsVirtualizing="False" ItemContainerStyle="{DynamicResource List.RowItem}"
                                     ItemsSource="{Binding View}" AutomationProperties.Name="{Binding L[Nav_Lang]}">
                                <ListBox.ItemTemplate>
                                    <DataTemplate>
                                        <Grid Height="28" Background="Transparent" ToolTip="{Binding ToolTipText}">
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="34"/>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="80"/>
                                                <ColumnDefinition Width="128"/>
                                            </Grid.ColumnDefinitions>
                                            <CheckBox Grid.Column="0" Style="{DynamicResource Check}" HorizontalAlignment="Center" VerticalAlignment="Center" Focusable="False"
                                                      IsChecked="{Binding IsChecked, Mode=TwoWay}" AutomationProperties.Name="{Binding Name}"
                                                      IsEnabled="{Binding DataContext.IsIdle, RelativeSource={RelativeSource AncestorType={x:Type ListBox}}}"/>
                                            <Grid Grid.Column="1">
                                                <Grid.ColumnDefinitions>
                                                    <ColumnDefinition Width="Auto"/>
                                                    <ColumnDefinition Width="*"/>
                                                </Grid.ColumnDefinitions>
                                                <Ellipse Style="{DynamicResource Dot.Category}" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                <TextBlock Grid.Column="1" Text="{Binding Name}" Style="{DynamicResource T.RowName}"/>
                                            </Grid>
                                            <TextBlock Grid.Column="2" Text="{Binding SizeText}" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,14,0"
                                                       Foreground="{DynamicResource B.Text2}" Typography.NumeralAlignment="Tabular"/>
                                            <StackPanel Grid.Column="3" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,10,0">
                                                <ProgressBar Width="42" Style="{DynamicResource Progress.Mini}" Value="{Binding Progress, Mode=OneWay}"
                                                             Margin="0,0,7,0" VerticalAlignment="Center"
                                                             Visibility="{Binding ShowBar, Converter={StaticResource BoolToVisL}}"/>
                                                <TextBlock Text="{Binding Status}" Style="{DynamicResource T.Status}" ToolTip="{Binding StatusToolTip}"/>
                                            </StackPanel>
                                        </Grid>
                                    </DataTemplate>
                                </ListBox.ItemTemplate>
                            </ListBox>
                            <StackPanel Grid.Row="1" HorizontalAlignment="Center" VerticalAlignment="Center" IsHitTestVisible="False"
                                        Visibility="{Binding EmptyVisibility}" MaxWidth="340">
                                <TextBlock Text="&#xE774;" FontFamily="{DynamicResource F.Icon}" FontSize="22" Foreground="{DynamicResource B.Text4}"
                                           HorizontalAlignment="Center" Margin="0,0,0,10"/>
                                <TextBlock Text="{Binding EmptyText}" Foreground="{DynamicResource B.Text3}" TextAlignment="Center" TextWrapping="Wrap"/>
                            </StackPanel>
                        </Grid>
                    </Border>

                    <Grid Grid.Row="3" Margin="16,0,16,0">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Grid.Column="0" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" ToolTip="{Binding FooterToolTip}"
                                   Typography.NumeralAlignment="Tabular"><Run Text="{Binding SelectionText, Mode=OneWay}" FontWeight="SemiBold"/><Run Text="  ·  " Foreground="{DynamicResource B.Text3}"/><Run Text="{Binding SummaryText, Mode=OneWay}" Foreground="{DynamicResource B.Text2}"/></TextBlock>
                        <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="6,0,0,0">
                            <Rectangle Width="1" Height="16" Fill="{DynamicResource B.Divider}" Margin="0,0,6,0"/>
                            <Button Style="{DynamicResource Btn.Ghost}" Content="{Binding L[Btn_SelectAll]}" Command="{Binding SelectAllCommand}"/>
                            <Button Style="{DynamicResource Btn.Ghost}" Content="{Binding L[Btn_SelectNone]}" Command="{Binding SelectNoneCommand}"/>
                        </StackPanel>
                        <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" Margin="8,0,0,0">
                            <Button Style="{DynamicResource Btn.Icon}" Command="{Binding OpenFolderCommand}" Content="&#xE838;"
                                    ToolTip="{Binding L[Btn_OpenFolder]}" AutomationProperties.Name="{Binding L[Btn_OpenFolder]}"/>
                            <Button Style="{DynamicResource Btn.Outline}" Command="{Binding CleanCommand}" Margin="8,0,0,0">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="&#xE74D;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Btn_Clean]}" VerticalAlignment="Center"/>
                                </StackPanel>
                            </Button>
                            <Button Style="{DynamicResource Btn.Primary}" Command="{Binding DownloadCommand}" Margin="8,0,0,0">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="&#xE896;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Btn_Download]}" VerticalAlignment="Center"/>
                                </StackPanel>
                            </Button>
                        </StackPanel>
                    </Grid>
                </Grid>

                </Grid>

                <!-- Windows PE -->
                <Grid Visibility="{Binding PeVisibility}">
                <Grid DataContext="{Binding Pe}">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                        <RowDefinition Height="46"/>
                    </Grid.RowDefinitions>

                    <Grid Grid.Row="0" Margin="16,2,16,0" IsEnabled="{Binding IsIdle}">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="1.25*"/>
                            <ColumnDefinition Width="128"/>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <ComboBox Grid.Column="0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Version]}"
                                  ItemsSource="{Binding Versions}" SelectedItem="{Binding SelectedVersion, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Version]}"/>
                        <ComboBox Grid.Column="1" Margin="8,0,0,0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Arch]}"
                                  ItemsSource="{Binding Archs}" SelectedItem="{Binding SelectedArch, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Arch]}"/>
                        <ComboBox Grid.Column="2" Margin="8,0,0,0" Style="{DynamicResource Combo.Field}" Tag="{Binding L[Field_Lang]}"
                                  ItemsSource="{Binding Languages}" SelectedItem="{Binding SelectedLanguage, Mode=TwoWay}"
                                  AutomationProperties.Name="{Binding L[Field_Lang]}"/>
                        <Button Grid.Column="3" Margin="8,0,0,0" Style="{DynamicResource Btn.Secondary}" Command="{Binding FetchCommand}"
                                ToolTip="{Binding L[Tip_Fetch]}">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE72C;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Btn_List]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                    </Grid>

                    <Grid Grid.Row="1" Margin="16,10,16,8">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="1000*" MinWidth="120" MaxWidth="210"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>
                        <TextBox x:Name="PeSearch" Grid.Column="0" Style="{DynamicResource Text.Search}"
                                 Tag="{Binding L[Pe_Search]}" ToolTip="{Binding L[Tip_Search]}"
                                 Text="{Binding Search, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged, Delay=150}"
                                 AutomationProperties.Name="{Binding L[Pe_Search]}"/>
                        <Rectangle Grid.Column="1" Width="1" Height="16" Fill="{DynamicResource B.Divider}" Margin="10,0,10,0"/>
                        <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center">
                            <RadioButton GroupName="peFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterAll, Mode=TwoWay}">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="{Binding L[Chip_All]}"/>
                                    <TextBlock Text="{Binding CountAll}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="peFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterLp, Mode=TwoWay}"
                                         Visibility="{Binding LpChipVisibility}" ToolTip="{Binding L[Cat_lp]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatLp}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Lp]}"/>
                                    <TextBlock Text="{Binding CountLp}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="peFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterCore, Mode=TwoWay}"
                                         Visibility="{Binding CoreChipVisibility}" ToolTip="{Binding L[Cat_core]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatFeature}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Core]}"/>
                                    <TextBlock Text="{Binding CountCore}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="peFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterOther, Mode=TwoWay}"
                                         Visibility="{Binding OtherChipVisibility}" ToolTip="{Binding L[Cat_other]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatFod}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Other]}"/>
                                    <TextBlock Text="{Binding CountOther}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                            <RadioButton GroupName="peFilter" Style="{DynamicResource Chip}" IsChecked="{Binding FilterServer, Mode=TwoWay}"
                                         Visibility="{Binding ServerChipVisibility}" ToolTip="{Binding L[Cat_server]}">
                                <StackPanel Orientation="Horizontal">
                                    <Ellipse Width="6" Height="6" Fill="{DynamicResource B.CatServer}" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Chip_Server]}"/>
                                    <TextBlock Text="{Binding CountServer}" Margin="6,0,0,0" Foreground="{DynamicResource B.Text3}"/>
                                </StackPanel>
                            </RadioButton>
                        </StackPanel>
                    </Grid>

                    <Border Grid.Row="2" Margin="16,0,16,0" Style="{DynamicResource Card}">
                        <Grid>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="28"/>
                                <RowDefinition Height="*"/>
                            </Grid.RowDefinitions>
                            <Border Grid.Row="0" Background="{DynamicResource B.CardHead}" BorderBrush="{DynamicResource B.HeadLine}"
                                    BorderThickness="0,0,0,1" CornerRadius="7,7,0,0">
                                <Grid>
                                    <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="34"/>
                                        <ColumnDefinition Width="*"/>
                                        <ColumnDefinition Width="80"/>
                                        <ColumnDefinition Width="128"/>
                                    </Grid.ColumnDefinitions>
                                    <CheckBox Grid.Column="0" Style="{DynamicResource Check}" HorizontalAlignment="Center" VerticalAlignment="Center"
                                              IsChecked="{Binding HeaderChecked, Mode=TwoWay}" IsEnabled="{Binding IsIdle}"
                                              ToolTip="{Binding L[Tip_ToggleVisible]}" AutomationProperties.Name="{Binding L[Tip_ToggleVisible]}"/>
                                    <DockPanel Grid.Column="1" LastChildFill="True">
                                        <Button DockPanel.Dock="Left" Style="{DynamicResource Btn.Header}" Command="{Binding SortCommand}" CommandParameter="Name">
                                            <StackPanel Orientation="Horizontal">
                                                <TextBlock Text="{Binding L[Col_Component]}"/>
                                                <TextBlock Text="{Binding NameSortGlyph}" FontFamily="{DynamicResource F.Icon}" FontSize="8" Margin="5,1,0,0" VerticalAlignment="Center"/>
                                            </StackPanel>
                                        </Button>
                                        <TextBlock Text="{Binding InfoText}" Style="{DynamicResource T.ListInfo}" ToolTip="{Binding InfoText}"/>
                                    </DockPanel>
                                    <Button Grid.Column="2" Style="{DynamicResource Btn.Header}" Command="{Binding SortCommand}" CommandParameter="Size"
                                            HorizontalContentAlignment="Right" Padding="0,0,14,0">
                                        <StackPanel Orientation="Horizontal">
                                            <TextBlock Text="{Binding SizeSortGlyph}" FontFamily="{DynamicResource F.Icon}" FontSize="8" Margin="0,1,5,0" VerticalAlignment="Center"/>
                                            <TextBlock Text="{Binding L[Col_Size]}"/>
                                        </StackPanel>
                                    </Button>
                                    <DockPanel Grid.Column="3" LastChildFill="True">
                                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.HeaderIcon}" Command="{Binding ClearListCommand}" Content="&#xE75C;"
                                                ToolTip="{Binding L[Tip_ClearList]}" AutomationProperties.Name="{Binding L[Tip_ClearList]}"/>
                                        <TextBlock Text="{Binding L[Col_Status]}" FontSize="11" Foreground="{DynamicResource B.Text3}" VerticalAlignment="Center"/>
                                    </DockPanel>
                                </Grid>
                            </Border>
                            <ListBox x:Name="PeList" Grid.Row="1" Style="{DynamicResource List.Rows}" VirtualizingPanel.IsVirtualizing="False" ItemContainerStyle="{DynamicResource List.RowItem}"
                                     ItemsSource="{Binding View}" AutomationProperties.Name="{Binding L[Nav_Pe]}">
                                <ListBox.ItemTemplate>
                                    <DataTemplate>
                                        <Grid Height="28" Background="Transparent" ToolTip="{Binding ToolTipText}">
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="34"/>
                                                <ColumnDefinition Width="*"/>
                                                <ColumnDefinition Width="80"/>
                                                <ColumnDefinition Width="128"/>
                                            </Grid.ColumnDefinitions>
                                            <CheckBox Grid.Column="0" Style="{DynamicResource Check}" HorizontalAlignment="Center" VerticalAlignment="Center" Focusable="False"
                                                      IsChecked="{Binding IsChecked, Mode=TwoWay}" AutomationProperties.Name="{Binding Name}"
                                                      IsEnabled="{Binding DataContext.IsIdle, RelativeSource={RelativeSource AncestorType={x:Type ListBox}}}"/>
                                            <Grid Grid.Column="1">
                                                <Grid.ColumnDefinitions>
                                                    <ColumnDefinition Width="Auto"/>
                                                    <ColumnDefinition Width="Auto"/>
                                                    <ColumnDefinition Width="*"/>
                                                </Grid.ColumnDefinitions>
                                                <Ellipse Style="{DynamicResource Dot.Category}" VerticalAlignment="Center" Margin="0,0,8,0"/>
                                                <TextBlock Grid.Column="1" Text="{Binding Name}" Style="{DynamicResource T.RowName}" FontWeight="SemiBold"/>
                                                <TextBlock Grid.Column="2" Text="{Binding Description}" Foreground="{DynamicResource B.Text3}" Margin="8,0,8,0"
                                                           VerticalAlignment="Center" TextTrimming="CharacterEllipsis"/>
                                            </Grid>
                                            <TextBlock Grid.Column="2" Text="{Binding SizeText}" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,14,0"
                                                       Foreground="{DynamicResource B.Text2}" Typography.NumeralAlignment="Tabular"/>
                                            <StackPanel Grid.Column="3" Orientation="Horizontal" VerticalAlignment="Center" Margin="0,0,10,0">
                                                <ProgressBar Width="42" Style="{DynamicResource Progress.Mini}" Value="{Binding Progress, Mode=OneWay}"
                                                             Margin="0,0,7,0" VerticalAlignment="Center"
                                                             Visibility="{Binding ShowBar, Converter={StaticResource BoolToVisL}}"/>
                                                <TextBlock Text="{Binding Status}" Style="{DynamicResource T.Status}" ToolTip="{Binding StatusToolTip}"/>
                                            </StackPanel>
                                        </Grid>
                                    </DataTemplate>
                                </ListBox.ItemTemplate>
                            </ListBox>
                            <StackPanel Grid.Row="1" HorizontalAlignment="Center" VerticalAlignment="Center" IsHitTestVisible="False"
                                        Visibility="{Binding EmptyVisibility}" MaxWidth="360">
                                <TextBlock Text="&#xE7B8;" FontFamily="{DynamicResource F.Icon}" FontSize="22" Foreground="{DynamicResource B.Text4}"
                                           HorizontalAlignment="Center" Margin="0,0,0,10"/>
                                <TextBlock Text="{Binding EmptyText}" Foreground="{DynamicResource B.Text3}" TextAlignment="Center" TextWrapping="Wrap"/>
                            </StackPanel>
                        </Grid>
                    </Border>

                    <Grid Grid.Row="3" Margin="16,0,16,0">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="Auto"/>
                            <ColumnDefinition Width="Auto"/>
                        </Grid.ColumnDefinitions>
                        <TextBlock Grid.Column="0" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" ToolTip="{Binding FooterToolTip}"
                                   Typography.NumeralAlignment="Tabular"><Run Text="{Binding SelectionText, Mode=OneWay}" FontWeight="SemiBold"/><Run Text="  ·  " Foreground="{DynamicResource B.Text3}"/><Run Text="{Binding SummaryText, Mode=OneWay}" Foreground="{DynamicResource B.Text2}"/></TextBlock>
                        <StackPanel Grid.Column="1" Orientation="Horizontal" VerticalAlignment="Center" Margin="6,0,0,0">
                            <Rectangle Width="1" Height="16" Fill="{DynamicResource B.Divider}" Margin="0,0,6,0"/>
                            <Button Style="{DynamicResource Btn.Ghost}" Content="{Binding L[Btn_SelectAll]}" Command="{Binding SelectAllCommand}"/>
                            <Button Style="{DynamicResource Btn.Ghost}" Content="{Binding L[Btn_SelectNone]}" Command="{Binding SelectNoneCommand}"/>
                        </StackPanel>
                        <StackPanel Grid.Column="2" Orientation="Horizontal" VerticalAlignment="Center" Margin="8,0,0,0">
                            <Button Style="{DynamicResource Btn.Icon}" Command="{Binding OpenFolderCommand}" Content="&#xE838;"
                                    ToolTip="{Binding L[Btn_OpenFolder]}" AutomationProperties.Name="{Binding L[Btn_OpenFolder]}"/>
                            <Button Style="{DynamicResource Btn.Outline}" Command="{Binding CleanCommand}" Margin="8,0,0,0">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="&#xE74D;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Btn_Clean]}" VerticalAlignment="Center"/>
                                </StackPanel>
                            </Button>
                            <Button Style="{DynamicResource Btn.Primary}" Command="{Binding DownloadCommand}" Margin="8,0,0,0">
                                <StackPanel Orientation="Horizontal">
                                    <TextBlock Text="&#xE896;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                    <TextBlock Text="{Binding L[Btn_Download]}" VerticalAlignment="Center"/>
                                </StackPanel>
                            </Button>
                        </StackPanel>
                    </Grid>
                </Grid>

                </Grid>

                <!-- Log -->
                <Grid Visibility="{Binding LogVisibility}">
                <Grid DataContext="{Binding LogVm}">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto"/>
                        <RowDefinition Height="*"/>
                    </Grid.RowDefinitions>
                    <DockPanel Grid.Row="0" Margin="16,2,16,10" LastChildFill="False">
                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.Outline}" Command="{Binding OpenFolderCommand}" Margin="8,0,0,0">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE838;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Log_OpenFolder]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.Outline}" Command="{Binding ClearCommand}" Margin="8,0,0,0">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE74D;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Log_Clear]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.Secondary}" Command="{Binding CopyCommand}">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE8C8;" FontFamily="{DynamicResource F.Icon}" FontSize="12" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Log_Copy]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <TextBlock DockPanel.Dock="Left" Text="{Binding CountText}" FontWeight="SemiBold" VerticalAlignment="Center"/>
                    </DockPanel>
                    <Border Grid.Row="1" Margin="16,0,16,14" Style="{DynamicResource Card}">
                        <Grid>
                            <ListBox x:Name="LogList" Style="{DynamicResource List.Rows}" ItemContainerStyle="{DynamicResource List.LogItem}"
                                     ItemsSource="{Binding Entries}" AutomationProperties.Name="{Binding L[Log_Title]}">
                                <ListBox.ItemTemplate>
                                    <DataTemplate>
                                        <Grid MinHeight="26" Margin="12,4,14,4">
                                            <Grid.ColumnDefinitions>
                                                <ColumnDefinition Width="62"/>
                                                <ColumnDefinition Width="20"/>
                                                <ColumnDefinition Width="*"/>
                                            </Grid.ColumnDefinitions>
                                            <TextBlock Grid.Column="0" Text="{Binding TimeText}" FontFamily="{DynamicResource F.Mono}" FontSize="10.5"
                                                       Foreground="{DynamicResource B.Text3}" VerticalAlignment="Center"/>
                                            <TextBlock Grid.Column="1" Text="{Binding Glyph}" Style="{DynamicResource T.LogLevel}"/>
                                            <TextBlock Grid.Column="2" Text="{Binding Message}" Style="{DynamicResource T.LogMessage}"/>
                                        </Grid>
                                    </DataTemplate>
                                </ListBox.ItemTemplate>
                            </ListBox>
                            <TextBlock Text="{Binding L[Log_Empty]}" Foreground="{DynamicResource B.Text3}" HorizontalAlignment="Center" VerticalAlignment="Center"
                                       Visibility="{Binding EmptyVisibility}" IsHitTestVisible="False"/>
                        </Grid>
                    </Border>
                </Grid>

                </Grid>

                <!-- Settings -->
                <ScrollViewer Visibility="{Binding SettingsVisibility}" VerticalScrollBarVisibility="Auto"
                              HorizontalScrollBarVisibility="Disabled" Focusable="False">
                    <Grid Margin="16,4,16,4" DataContext="{Binding Settings}">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="*"/>
                            <ColumnDefinition Width="10"/>
                            <ColumnDefinition Width="*"/>
                        </Grid.ColumnDefinitions>

                        <StackPanel Grid.Column="0">
                            <Border Style="{DynamicResource Card.Section}">
                                <StackPanel>
                                    <TextBlock Text="{Binding L[Set_Folders]}" Style="{DynamicResource T.Section}"/>
                                    <TextBlock Text="{Binding L[Set_Output]}" Style="{DynamicResource T.Label}" Margin="0,0,0,5"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <TextBox Grid.Column="0" Style="{DynamicResource Text.Field}"
                                                 Text="{Binding OutputRoot, Mode=TwoWay, UpdateSourceTrigger=LostFocus}"
                                                 AutomationProperties.Name="{Binding L[Set_Output]}"/>
                                        <Button Grid.Column="1" Style="{DynamicResource Btn.Icon}" Height="28" Width="28" Margin="6,0,0,0" Content="&#xE8B7;"
                                                Command="{Binding BrowseCommand}" ToolTip="{Binding L[Set_Browse]}" AutomationProperties.Name="{Binding L[Set_Browse]}"/>
                                        <Button Grid.Column="2" Style="{DynamicResource Btn.Icon}" Height="28" Width="28" Margin="6,0,0,0" Content="&#xE8A7;"
                                                Command="{Binding OpenOutputCommand}" ToolTip="{Binding L[Set_OpenOutput]}" AutomationProperties.Name="{Binding L[Set_OpenOutput]}"/>
                                    </Grid>
                                    <TextBlock Text="{Binding L[Set_OutputHint]}" Style="{DynamicResource T.Hint}" Margin="0,5,0,0"/>
                                    <Rectangle Height="1" Fill="{DynamicResource B.SideLine}" Margin="0,12,0,12"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Manifests]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding ManifestInfo}" Style="{DynamicResource T.Hint}" TextWrapping="NoWrap" TextTrimming="CharacterEllipsis"
                                                       ToolTip="{Binding ManifestDir}"/>
                                        </StackPanel>
                                        <Button Grid.Column="1" Style="{DynamicResource Btn.Outline}" Height="26" Padding="10,0" Margin="8,0,0,0"
                                                Content="{Binding L[Set_Open]}" Command="{Binding OpenManifestsCommand}" VerticalAlignment="Center"/>
                                    </Grid>
                                </StackPanel>
                            </Border>

                            <Border Style="{DynamicResource Card.Section}">
                                <StackPanel>
                                    <TextBlock Text="{Binding L[Set_Ui]}" Style="{DynamicResource T.Section}"/>
                                    <Grid Margin="0,0,0,12">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <TextBlock Text="{Binding L[Set_Language]}" Style="{DynamicResource T.Label}" VerticalAlignment="Center"/>
                                        <Border Grid.Column="1" Background="{DynamicResource B.Input}" BorderBrush="{DynamicResource B.InputLine}" BorderThickness="1"
                                                CornerRadius="6" Padding="2">
                                            <StackPanel Orientation="Horizontal">
                                                <RadioButton GroupName="uiLang" Style="{DynamicResource Segment}" Content="Türkçe" IsChecked="{Binding IsTurkish, Mode=TwoWay}"/>
                                                <RadioButton GroupName="uiLang" Style="{DynamicResource Segment}" Content="English" IsChecked="{Binding IsEnglish, Mode=TwoWay}"/>
                                            </StackPanel>
                                        </Border>
                                    </Grid>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Console]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding L[Set_ConsoleHint]}" Style="{DynamicResource T.Hint}"/>
                                        </StackPanel>
                                        <CheckBox Grid.Column="1" Style="{DynamicResource Switch}" IsChecked="{Binding ShowConsole, Mode=TwoWay}"
                                                  IsEnabled="{Binding ConsoleAvailable}" AutomationProperties.Name="{Binding L[Set_Console]}" Margin="8,0,0,0"/>
                                    </Grid>
                                </StackPanel>
                            </Border>
                        </StackPanel>

                        <StackPanel Grid.Column="2">
                            <Border Style="{DynamicResource Card.Section}">
                                <StackPanel>
                                    <TextBlock Text="{Binding L[Set_Download]}" Style="{DynamicResource T.Section}"/>
                                    <Grid Margin="0,0,0,11">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Skip]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding L[Set_SkipHint]}" Style="{DynamicResource T.Hint}"/>
                                        </StackPanel>
                                        <CheckBox Grid.Column="1" Style="{DynamicResource Switch}" IsChecked="{Binding SkipExisting, Mode=TwoWay}"
                                                  AutomationProperties.Name="{Binding L[Set_Skip]}" Margin="8,0,0,0"/>
                                    </Grid>
                                    <Grid Margin="0,0,0,11">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Verify]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding L[Set_VerifyHint]}" Style="{DynamicResource T.Hint}"/>
                                        </StackPanel>
                                        <CheckBox Grid.Column="1" Style="{DynamicResource Switch}" IsChecked="{Binding VerifyHash, Mode=TwoWay}"
                                                  AutomationProperties.Name="{Binding L[Set_Verify]}" Margin="8,0,0,0"/>
                                    </Grid>
                                    <Grid Margin="0,0,0,11" Visibility="{Binding OnlineVisibility}">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Keep]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding L[Set_KeepHint]}" Style="{DynamicResource T.Hint}"/>
                                        </StackPanel>
                                        <CheckBox Grid.Column="1" Style="{DynamicResource Switch}" IsChecked="{Binding KeepCache, Mode=TwoWay}"
                                                  AutomationProperties.Name="{Binding L[Set_Keep]}" Margin="8,0,0,0"/>
                                    </Grid>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <StackPanel>
                                            <TextBlock Text="{Binding L[Set_Deps]}" Style="{DynamicResource T.Label}"/>
                                            <TextBlock Text="{Binding L[Set_DepsHint]}" Style="{DynamicResource T.Hint}"/>
                                        </StackPanel>
                                        <CheckBox Grid.Column="1" Style="{DynamicResource Switch}" IsChecked="{Binding AutoDeps, Mode=TwoWay}"
                                                  AutomationProperties.Name="{Binding L[Set_Deps]}" Margin="8,0,0,0"/>
                                    </Grid>
                                </StackPanel>
                            </Border>

                            <Border Style="{DynamicResource Card.Section}">
                                <StackPanel>
                                    <TextBlock Text="{Binding L[Set_Engine]}" Style="{DynamicResource T.Section}"/>
                                    <Grid>
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="100"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>
                                        <TextBlock Grid.Row="0" Text="{Binding L[Set_Catalog]}" Foreground="{DynamicResource B.Text3}" FontSize="11.5" Margin="0,0,0,4"/>
                                        <TextBlock Grid.Row="0" Grid.Column="1" Text="{Binding CatalogInfo}" FontSize="11.5" TextWrapping="Wrap" Margin="0,0,0,4"/>
                                        <TextBlock Grid.Row="1" Text="{Binding L[Set_Index]}" Foreground="{DynamicResource B.Text3}" FontSize="11.5" Margin="0,0,0,4"/>
                                        <TextBlock Grid.Row="1" Grid.Column="1" Text="{Binding IndexInfo}" FontSize="11.5" TextWrapping="Wrap" Margin="0,0,0,4"/>
                                        <TextBlock Grid.Row="2" Text="{Binding L[Set_Runtime]}" Foreground="{DynamicResource B.Text3}" FontSize="11.5"/>
                                        <TextBlock Grid.Row="2" Grid.Column="1" Text="{Binding RuntimeInfo}" FontSize="11.5" TextWrapping="Wrap"/>
                                    </Grid>
                                    <Button Style="{DynamicResource Btn.Secondary}" Height="28" HorizontalAlignment="Left" Margin="0,12,0,0" Command="{Binding SelfTestCommand}">
                                        <StackPanel Orientation="Horizontal">
                                            <TextBlock Text="&#xE73E;" FontFamily="{DynamicResource F.Icon}" FontSize="11" Margin="0,0,7,0" VerticalAlignment="Center"/>
                                            <TextBlock Text="{Binding L[Set_SelfTest]}" VerticalAlignment="Center"/>
                                        </StackPanel>
                                    </Button>
                                </StackPanel>
                            </Border>
                        </StackPanel>
                    </Grid>
                </ScrollViewer>
            </Grid>

            <!-- Status bar -->
            <Border Grid.Row="2" Background="{DynamicResource B.Status}" BorderBrush="{DynamicResource B.Divider2}" BorderThickness="0,1,0,0">
                <Grid>
                    <ProgressBar Style="{DynamicResource Progress.Line}" VerticalAlignment="Top" Margin="0,-1,0,0"
                                 Value="{Binding ProgressValue, Mode=OneWay}" IsIndeterminate="{Binding ProgressIndeterminate, Mode=OneWay}"
                                 Visibility="{Binding ProgressVisibility}"/>
                    <DockPanel Margin="16,0,8,0" LastChildFill="True">
                        <Ellipse DockPanel.Dock="Left" Style="{DynamicResource Dot.Status}" Margin="0,0,8,0" VerticalAlignment="Center"/>
                        <Button DockPanel.Dock="Right" Style="{DynamicResource Btn.Small}" Command="{Binding CancelCommand}" Margin="8,0,0,0"
                                Visibility="{Binding CancelVisibility}" VerticalAlignment="Center">
                            <StackPanel Orientation="Horizontal">
                                <TextBlock Text="&#xE71A;" FontFamily="{DynamicResource F.Icon}" FontSize="9" Margin="0,0,6,0" VerticalAlignment="Center"/>
                                <TextBlock Text="{Binding L[Btn_Stop]}" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Button>
                        <TextBlock DockPanel.Dock="Right" Text="{Binding ProgressDetail}" FontSize="11" Foreground="{DynamicResource B.Text3}"
                                   VerticalAlignment="Center" Margin="8,0,0,0" Typography.NumeralAlignment="Tabular"/>
                        <TextBlock DockPanel.Dock="Right" Text="{Binding Settings.OutputRoot}" FontFamily="{DynamicResource F.Mono}" FontSize="10.5"
                                   Foreground="{DynamicResource B.Text3}" VerticalAlignment="Center" Margin="8,0,6,0" MaxWidth="260"
                                   TextTrimming="CharacterEllipsis" Visibility="{Binding IdleVisibility}" ToolTip="{Binding Settings.OutputRoot}"/>
                        <TextBlock Text="{Binding StatusText}" FontSize="11" Foreground="{DynamicResource B.Text2}" VerticalAlignment="Center"
                                   TextTrimming="CharacterEllipsis" ToolTip="{Binding StatusText}"/>
                    </DockPanel>
                </Grid>
            </Border>
        </Grid>

        <!-- Dialog -->
        <Grid Grid.ColumnSpan="2" Visibility="{Binding Dialog.Visibility}">
          <Grid DataContext="{Binding Dialog}">
            <Border Background="{DynamicResource B.Overlay}"/>
            <Border Width="404" HorizontalAlignment="Center" VerticalAlignment="Center" Background="{DynamicResource B.Popup}"
                    BorderBrush="{DynamicResource B.PopupLine}" BorderThickness="1" CornerRadius="10" Padding="20,18,20,16">
                <Border.Effect>
                    <DropShadowEffect BlurRadius="36" ShadowDepth="8" Opacity="0.5" Color="Black"/>
                </Border.Effect>
                <StackPanel>
                    <StackPanel Orientation="Horizontal">
                        <Border Style="{DynamicResource Dialog.IconBg}">
                            <TextBlock Text="{Binding Glyph}" FontFamily="{DynamicResource F.Icon}" FontSize="13" HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <TextBlock Text="{Binding Title}" FontSize="14" FontWeight="SemiBold" Margin="10,0,0,0" VerticalAlignment="Center"/>
                    </StackPanel>
                    <TextBlock Text="{Binding Message}" TextWrapping="Wrap" Foreground="{DynamicResource B.Text2}" Margin="0,12,0,0" LineHeight="17"
                               Visibility="{Binding MessageVisibility}"/>
                    <Border Margin="0,12,0,0" Padding="12,9" Background="{DynamicResource B.Detail}" BorderBrush="{DynamicResource B.HeadLine}"
                            BorderThickness="1" CornerRadius="7" Visibility="{Binding DetailsVisibility}">
                        <ItemsControl ItemsSource="{Binding Details}" Focusable="False">
                            <ItemsControl.ItemTemplate>
                                <DataTemplate>
                                    <Grid Margin="0,2,0,2">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="96"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <TextBlock Grid.Column="0" Text="{Binding Key}" FontSize="11.5" Foreground="{DynamicResource B.Text3}"/>
                                        <TextBlock Grid.Column="1" Text="{Binding Value}" FontSize="11.5" Style="{DynamicResource T.DetailValue}" ToolTip="{Binding Value}"/>
                                    </Grid>
                                </DataTemplate>
                            </ItemsControl.ItemTemplate>
                        </ItemsControl>
                    </Border>
                    <TextBlock Text="{Binding Note}" FontSize="11" Foreground="{DynamicResource B.Text3}" Margin="0,10,0,0" TextWrapping="Wrap"
                               Visibility="{Binding NoteVisibility}"/>
                    <StackPanel Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,16,0,0">
                        <Button x:Name="DlgCancel" Style="{DynamicResource Btn.Outline}" Content="{Binding CancelText}" Command="{Binding CancelCommand}"
                                Visibility="{Binding CancelVisibility}" Margin="0,0,8,0" Padding="14,0"/>
                        <Button x:Name="DlgOk" Style="{DynamicResource Btn.Primary}" Content="{Binding OkText}" Command="{Binding OkCommand}" MinWidth="78"/>
                    </StackPanel>
                </StackPanel>
            </Border>
          </Grid>
        </Grid>

        <!-- Window buttons sit above the dialog layer, so minimize / close work while a dialog is open -->
        <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Top">
            <Button x:Name="BtnMin" Style="{DynamicResource Btn.Caption}" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    ToolTip="{Binding L[Win_Min]}" AutomationProperties.Name="{Binding L[Win_Min]}">
                <TextBlock Text="&#xE921;" FontFamily="{DynamicResource F.Icon}" FontSize="10"/>
            </Button>
            <Button x:Name="BtnMax" Style="{DynamicResource Btn.Caption}" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    AutomationProperties.Name="{Binding L[Win_Max]}">
                <TextBlock x:Name="MaxGlyph" Text="&#xE922;" FontFamily="{DynamicResource F.Icon}" FontSize="10"/>
            </Button>
            <Button x:Name="BtnClose" Style="{DynamicResource Btn.CaptionClose}" shell:WindowChrome.IsHitTestVisibleInChrome="True"
                    ToolTip="{Binding L[Win_Close]}" AutomationProperties.Name="{Binding L[Win_Close]}">
                <TextBlock Text="&#xE8BB;" FontFamily="{DynamicResource F.Icon}" FontSize="10"/>
            </Button>
        </StackPanel>
    </Grid>
</Border>
'@

