# --- Pure helpers (independent of the UI) ---
function Format-Size {
    param([double]$Bytes)
    if ($Bytes -ge 1GB)     { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    elseif ($Bytes -ge 1MB) { return ('{0:N1} MB' -f ($Bytes / 1MB)) }
    elseif ($Bytes -ge 1KB) { return ('{0:N0} KB' -f ($Bytes / 1KB)) }
    return ('{0:N0} B' -f $Bytes)
}

function Get-PackageDestination {
    param([string]$TargetRoot, $Package)
    return (Join-Path (Join-Path $TargetRoot $Package.Architecture) $Package.RelativePath)
}

# Display name used in the log: amd64\tr-tr\lp.cab
function Get-FileDisplayName {
    param($File)
    if ($File.IsLanguagePack) { return "$($File.Architecture)\$($File.Language)\$($File.FileName)" }
    return "$($File.Architecture)\$($File.FileName)"
}

function Get-FileListText {
    param([object[]]$Files, [int]$Max = 3)
    $names = @($Files | ForEach-Object { Get-FileDisplayName $_ })
    if ($names.Count -le $Max) { return ($names -join ', ') }
    return (($names[0..($Max - 1)] -join ', ') + " +$($names.Count - $Max)")
}

function Get-ComponentDescription {
    param([string]$Name)
    $d = $script:OcDescriptions[$Name]
    if ($d) { return $d }
    return ''
}

# Converts the file list into a component model: "arch|component" -> main file + per-language files
function Get-ComponentModel {
    param([object[]]$Files)
    $model = @{}
    foreach ($f in $Files) {
        $key = "$($f.Architecture)|$($f.ComponentName)"
        $m = $model[$key]
        if (-not $m) {
            $m = [PSCustomObject]@{ Key = $key; Arch = $f.Architecture; Name = $f.ComponentName; Neutral = $null; Langs = @{} }
            $model[$key] = $m
        }
        if ($f.IsLanguagePack) { $m.Langs[$f.Language] = $f } else { $m.Neutral = $f }
    }
    return $model
}

# Files to download for a component, based on the selected languages
function Get-ComponentFiles {
    param($Component, [bool]$IncludeNeutral, [string[]]$Languages)
    if ($IncludeNeutral -and $Component.Neutral) { $Component.Neutral }
    foreach ($l in $Languages) {
        $f = $Component.Langs[$l]
        if ($f) { $f }
    }
}
