function Test-IsServerFOD {
    param (
        [Parameter(Mandatory=$true)]
        [string]$FileName,
        [Parameter(Mandatory=$false)]
        [string]$Language = ""
    )
    
    $serverPattern = 'Server-AppCompat|ServerManager|ServerCoreFonts|AzureStack|FailoverCluster|' +
                     'StorageMigrationService|StorageReplica|SystemInsights|Shielded-VM|' +
                     'ActiveDirectory-DS-LDS|StorageManagement-FoD|BitLocker-Recovery-Tools|' +
                     'CertificateServices-Tools|Console-Host-Legacy|DHCP-Tools|DNS-Tools|' +
                     'DirectoryServices-ADAM|EMS-SAC-Desktop|FileServices-Tools|GroupPolicy-Management|' +
                     'IPAM-Client|IRDA-Package|NetworkController-Tools|NetworkLoadBalancing-Tools|' +
                     'RasCMAK-Client|RasRip-Package|RemoteAccess-Management|RemoteDesktop-Services|' +
                     'SNMP-Client|TPM-Diagnostics|VolumeActivation-Tools|WMI-SNMP-Provider|WSUS-Tools'

    if ($FileName -match $serverPattern) {
        return $true
    }

    if ($script:ServerFODKeywords) {
        foreach ($keyword in $script:ServerFODKeywords) {
            if ($FileName -like "*$keyword*") {
                return $true
            }
        }
    }
    return $false
}

function Test-IsValidFileType {
    param (
        [Parameter(Mandatory=$true)]
        [string]$FileName,
        [Parameter(Mandatory=$true)]
        [string]$Language
    )
    
    $escapedLang = [regex]::Escape($Language)
    return ($FileName -match '\.cab$' -and $FileName -match $escapedLang) -or
           ($FileName -match '\.esd$' -and $FileName -match $escapedLang -and $FileName -match '(LanguagePack|_lp\.esd$)') -or
           ($FileName -match 'LanguageExperiencePack_.*\.appx$' -and $FileName -match $escapedLang)
}

# Unified file filtering function
function Filter-WindowsFiles {
    param (
        [Parameter(Mandatory=$true)]
        [PSObject]$File,
        [Parameter(Mandatory=$true)]
        [string]$Language,
        [Parameter(Mandatory=$false)]
        [bool]$IsServer = $false
    )
    
    # First check if it's a valid file type
    if (-not (Test-IsValidFileType -FileName $File.Name -Language $Language)) {
        return $false
    }
    
    # Client version selected: hide server FOD packages
    if (-not $IsServer -and (Test-IsServerFOD -FileName $File.Name -Language $Language)) {
        return $false
    }
    
    # Always hide specific ESD files
if ($File.Name -match 'core_.*\.esd$' -or 
    $File.Name -match 'professional_.*\.esd$' -or 
    $File.Name -match 'coren_.*\.esd$' -or 
    $File.Name -match 'professionaln_.*\.esd$' -or 
    $File.Name -match 'PPIPro_.*\.esd$' -or
