# --- UI bridge: status, log, cancellation, localization ---
$script:UI = $null

function L {
    param([string]$Key)
    if (-not ('WinPEOCs.Loc' -as [type])) { return $Key }
    return [WinPEOCs.Loc]::T($Key)
}

function LF {
    param([string]$Key)
    if (-not ('WinPEOCs.Loc' -as [type])) { return ((@($Key) + @($args)) -join ' ') }
    return [WinPEOCs.Loc]::F($Key, [object[]]$args)
}

function Set-UiStatus {
    param([string]$Text, [string]$Level = 'busy')
    if ($script:UI) { $script:UI.Status($Text, $Level) } else { Write-Verbose $Text }
}

function Write-UiLog {
    param([string]$Level, [string]$Message)
    if ($script:UI) { $script:UI.Log($Level, $Message) } else { Write-Verbose "[$Level] $Message" }
}

function Test-UiCancel {
    return [bool]($script:UI -and $script:UI.IsCancelRequested)
}

function Assert-UiNotCancelled {
    if (Test-UiCancel) { throw (New-Object System.OperationCanceledException) }
}

# Replaces Wait-WithDoEvents: the UI runs on its own thread, so no DoEvents is needed.
# The countdown is shown in the status bar and the Stop button ends the wait.
function Wait-UiDelay {
    param(
        [int]$Milliseconds,
        [string]$MessageKey,
        [object[]]$MessageArgs = @()
    )
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $lastSec = -1
    while ($sw.ElapsedMilliseconds -lt $Milliseconds) {
        Assert-UiNotCancelled
        if ($MessageKey) {
            $remSec = [Math]::Max(1, [int][Math]::Ceiling(($Milliseconds - $sw.ElapsedMilliseconds) / 1000.0))
            if ($remSec -ne $lastSec) {
                $lastSec = $remSec
                Set-UiStatus ([WinPEOCs.Loc]::F($MessageKey, [object[]](@($MessageArgs) + @($remSec)))) 'warn'
            }
        }
        Start-Sleep -Milliseconds 100
    }
}

# --- UUP / Microsoft FE3 engine ---
$script:UupMemoryCache     = @{}
$script:UupNoLinksCache    = @{}
$script:Fe3XmlMemoryCache  = @{}
$script:LocalManifestDir   = Join-Path $script:AppRoot 'Manifests'
try {
    if (-not (Test-Path -LiteralPath $script:LocalManifestDir)) { New-Item -Path $script:LocalManifestDir -ItemType Directory -Force -ErrorAction Stop | Out-Null }
    $probe = Join-Path $script:LocalManifestDir ('.w' + [guid]::NewGuid().ToString('N'))
    [System.IO.File]::WriteAllText($probe, '')
    Remove-Item -LiteralPath $probe -Force -ErrorAction SilentlyContinue
} catch {
    # Fall back to the user profile when the script folder is not writable (read-only share etc.)
    $script:LocalManifestDir = Join-Path $env:LOCALAPPDATA 'WinPEOCs\Manifests'
}
$script:ManifestDirs       = @(
    $script:LocalManifestDir,
    (Join-Path $env:LOCALAPPDATA 'WinPEOCs\Manifests'),
    (Join-Path $env:TEMP 'LPD_UUP_Cache')
) | Select-Object -Unique
$script:UupCacheDir        = $script:LocalManifestDir
$script:LastUupCallUtc     = [DateTime]::MinValue
$script:LastManifestSource = 'LocalCatalog'

function ConvertFrom-UupJson {
    param(
        [Parameter(Mandatory=$true)][string]$JsonText,
        [string]$Language = $null
    )
    $filteredJson = [WinPEOCs.JsonTools]::DeduplicateJsonKeys($JsonText, $Language)
    return ($filteredJson | ConvertFrom-Json -ErrorAction Stop)
}

function Test-UupCacheValid {
    param(
        $ResponseObj,
        [int]$MinRemainingSeconds = 90,
        [switch]$AllowNoLinks
    )
    if ($null -eq $ResponseObj -or -not $ResponseObj.response -or -not $ResponseObj.response.files) {
        return $false
    }
    $props = @($ResponseObj.response.files.PSObject.Properties)
    if ($props.Count -eq 0) { return $false }
    if ($AllowNoLinks) { return $true }
    $nowUnix = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    foreach ($p in $props) {
        if ([string]::IsNullOrWhiteSpace([string]$p.Value.url)) {
            return $false
        }
        if ($p.Value.expire) {
            if ([long]$p.Value.expire -le ($nowUnix + $MinRemainingSeconds)) {
                return $false
            }
            return $true
        }
    }
    return $true
}
# --- Direct Microsoft Windows Update engine (FE3 ClientWebService SOAP API) ---
function New-UupDeviceTicket {
    $tHeader = '13003002c377040014d5bcac7a66de0d50beddf9bba16c87edb9e019898000'
    $rng = New-Object System.Random
    $hexChars = '0123456789abcdef'
    $sb = New-Object System.Text.StringBuilder 1054
    for ($i = 0; $i -lt 1054; $i++) {
        [void]$sb.Append($hexChars[$rng.Next(0, 16)])
    }
    $fullHex = $tHeader + $sb.ToString() + 'b401'
    $bytes = New-Object byte[] ($fullHex.Length / 2)
    for ($i = 0; $i -lt $bytes.Length; $i++) {
        $bytes[$i] = [Convert]::ToByte($fullHex.Substring($i * 2, 2), 16)
    }
    $tValue = [Convert]::ToBase64String($bytes)
    $data = "t=$tValue&p="
    $utf16Bytes = [System.Text.Encoding]::Unicode.GetBytes($data)
    return [Convert]::ToBase64String($utf16Bytes)
}

function Get-UupBranchFromBuild {
    param([string]$Build)
    $parts = $Build -split '\.'
    $bldNum = 26100
    if ($parts.Count -ge 3) { [void][int]::TryParse($parts[2], [ref]$bldNum) }
    elseif ($parts.Count -ge 1) { [void][int]::TryParse($parts[0], [ref]$bldNum) }
    switch ($bldNum) {
        15063 { return 'rs2_release' }
        16299 { return 'rs3_release' }
        17134 { return 'rs4_release' }
        17763 { return 'rs5_release' }
        17784 { return 'rs5_release_svc_hci' }
        { $_ -in 18362, 18363 } { return '19h1_release' }
        { $_ -in 19041, 19042, 19043, 19044, 19045 } { return 'vb_release' }
        20279 { return 'fe_release_10x' }
        { $_ -in 20348, 20349 } { return 'fe_release' }
        22000 { return 'co_release' }
        { $_ -in 22621, 22631 } { return 'ni_release' }
        25398 { return 'zn_release' }
        { $_ -in 26100, 26200, 26300 } { return 'ge_release' }
        { $_ -in 28000, 28100 } { return 'br_release' }
        default { return 'rs_prerelease' }
    }
}

function New-UupDeviceAttributes {
    param(
        [string]$Build = '10.0.26100.1',
        [string]$Arch = 'amd64',
        [int]$Sku = 48,
        [string]$Ring = 'RETAIL',
        [string]$Branch = 'auto',
        [int]$TargetRelease = -1
    )
    if ($Arch -eq 'x64' -or [string]::IsNullOrWhiteSpace($Arch)) { $Arch = 'amd64' }
    if ([string]::IsNullOrWhiteSpace($Build)) { $Build = '10.0.26100.1' }
    if ($Build -notmatch '^\d+\.\d+\.') { $Build = "10.0.$Build" }
    if ($Sku -le 0) { $Sku = 48 }
    if ($Branch -eq 'auto' -or [string]::IsNullOrWhiteSpace($Branch)) {
        $Branch = Get-UupBranchFromBuild -Build $Build
    }
    $parts = $Build -split '\.'
    $bldNum = 26100
    if ($parts.Count -ge 3) { [void][int]::TryParse($parts[2], [ref]$bldNum) }

    $serverSkus = @(7, 8, 12, 13, 79, 80, 120, 145, 146, 147, 148, 159, 160, 406, 407, 408)
    $blockUpgrades = 0
    if ($Sku -in @(125, 126)) { $blockUpgrades = 1 }
    $dvcFamily = 'Windows.Desktop'
    $insType   = 'Client'
    $prodType  = 'WinNT'
    if ($Sku -eq 119) { $dvcFamily = 'Windows.Team' }
    if ($serverSkus -contains $Sku) {
        $dvcFamily = 'Windows.Server'
        $insType   = 'Server'
        $prodType  = 'ServerNT'
        $blockUpgrades = 1
    }

    $fltBranch = ''
    $fltRing = 'Retail'
    $flightEnabled = 0
    $isRetail = 1
    if ($Ring -ne 'RETAIL') {
        $fltRing = 'External'
        $flightEnabled = 1
        $isRetail = 0
        switch ($Ring.ToUpperInvariant()) {
            'WIF' { $fltBranch = 'Dev' }
            'DEV' { $fltBranch = 'Dev' }
            'WIS' { $fltBranch = 'Beta' }
            'BETA' { $fltBranch = 'Beta' }
            'RP'  { $fltBranch = 'ReleasePreview' }
            'RELEASEPREVIEW' { $fltBranch = 'ReleasePreview' }
            'CANARY' { $fltBranch = 'CanaryChannel' }
        }
    }

    $nowUnix = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $expEpoch = $nowUnix + 82800
    $tsEpoch  = $nowUnix - 3600

    $attrib = [System.Collections.Generic.List[string]]@(
        'App=WU_OS',
        "AppVer=$Build",
        'AttrDataVer=370',
        'AllowInPlaceUpgrade=1',
        'AllowOptionalContent=1',
        'AllowUpgradesWithUnsupportedTPMOrCPU=1',
        'AllowWindowsServerFeatureUpdate=1',
        "BlockFeatureUpdates=$blockUpgrades",
        'BranchReadinessLevel=CB',
        'CIOptin=1',
        "CurrentBranch=$Branch",
        "DataExpDateEpoch_GE26H2=$expEpoch",
        "DataExpDateEpoch_GE25H2=$expEpoch",
        "DataExpDateEpoch_GE24H2=$expEpoch",
        "DataExpDateEpoch_GE24H2Setup=$expEpoch",
        "DataExpDateEpoch_NI23H2=$expEpoch",
        "DataExpDateEpoch_NI22H2=$expEpoch",
        "DataExpDateEpoch_NI22H2Setup=$expEpoch",
        "DataExpDateEpoch_CO21H2=$expEpoch",
        "DataExpDateEpoch_CO21H2Setup=$expEpoch",
        "DataExpDateEpoch_22H2=$expEpoch",
        "DataExpDateEpoch_21H2=$expEpoch",
        "DataExpDateEpoch_21H1=$expEpoch",
        "DataExpDateEpoch_20H1=$expEpoch",
        "DataExpDateEpoch_20H1Setup=$expEpoch",
        "DataExpDateEpoch_19H1=$expEpoch",
        "DataExpDateEpoch_19H1Setup=$expEpoch",
        'DataVer_RS5=2000000000',
        'DefaultUserRegion=191',
        "DeviceFamily=$dvcFamily",
        'DeviceInfoGatherSuccessful=1',
        'EKB19H2InstallCount=1',
        'EKB19H2InstallTimeEpoch=1255000000',
        "FlightingBranchName=$fltBranch",
        "FlightRing=$fltRing",
