function Invoke-GuiClean {
    param($Req, [string]$Kind)
    $root = $Req.GetString('Root')
    if ([string]::IsNullOrWhiteSpace($root)) { throw (L 'Off_NoOutput') }
    if ($Kind -eq 'pe') {
        $dirs = @(Join-Path $root 'WinPE')
        $patterns = @('*.cab', '*.esd', '*.part')
    } else {
        $dirs = @((Join-Path $root 'Langs'), (Join-Path $root 'OnDemand'))
        $patterns = @('*.cab', '*.esd', '*.appx', '*.part')
    }
    $count = 0
    $bytes = [long]0
    foreach ($d in $dirs) {
        if (-not (Test-Path -LiteralPath $d)) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $d -Recurse -File -Force -Include $patterns -ErrorAction SilentlyContinue)) {
            try {
                $len = $f.Length
                Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop
                $count++
                $bytes += $len
            } catch {
                Write-UiLog 'warn' "$($f.FullName): $($_.Exception.Message)"
            }
        }
    }
    $msg = LF 'Job_CleanDone' $count (Format-Size $bytes)
    $script:UI.Done($Req, $true, $msg, 'ok')
}

function Test-FileHashMatch {
    param($Item, [string]$Path, [string]$Sha1 = '')
    $expected = if ($Sha1) { $Sha1 } else { [string]$Item.Sha1 }
    if ($Item) { $Item.SetState('Verifying') }
    Set-UiStatus (LF 'Job_Verify' ([System.IO.Path]::GetFileName($Path)))
    $obs = if ($Item) { $script:UI.HashObserver($Item) } else { $null }
    $h = [WinPEOCs.Net]::HashFile($Path, 'SHA1', $script:UI.Cancel, $obs)
    if ($null -eq $h) { throw (New-Object System.OperationCanceledException) }
    return ($h -eq $expected.ToLowerInvariant())
}

# --- Repository archives (.bin): AES-256 encrypted entries with an encrypted XML manifest ---
# Layout of the repository folder (Repo next to the script):
#   <version slug>_<arch>_<lang>.bin   language packs, language features and FODs of one UUP row and
#                                      language (e.g. w11_26h2_x64_de-de.bin; w11_26h2_x64.bin of the tr-tr
#                                      design keeps serving the language of its manifest)
#   winpe_<buildId>_<arch>.bin         neutral Windows PE packages of one ADK build
#   winpe_<buildId>_<arch>_<lang>.bin  Windows PE language packages
#   _temp\                          downloads in progress (resumed on the next attempt)
# Missing files are downloaded once from Microsoft (FE3 / ADK CDN), verified with the SHA-1 of the
# catalog and added to the archive; after that the repository works without an internet connection.
# Loose files are found as well: <sha1>.<ext> in Repo\Lang / Repo\WinPE (zip distribution) and files
# with their real name in Repo\Lang, Lang or <slug>\Repo\Lang (size must match, always SHA-1 checked).
$script:BinArchiveSource = @'
namespace WinPEOCs.Archive
{
    using System;
    using System.Collections.Generic;
    using System.Globalization;
    using System.IO;
    using System.IO.Compression;
    using System.Security.Cryptography;
    using System.Text;
    using System.Xml;

    // .bin repository archive, format version 1:
    //   "WPEB" | int32 version | int32 manifest cipher length | 16-byte manifest IV | manifest cipher | entry blobs
    // The manifest is UTF-8 XML encrypted with AES-256-CBC; every entry blob is AES-256-CBC (own IV) over the
    // file bytes, gzip-compressed first when that makes it smaller. Offsets in the manifest are absolute.
    // The key is built into the script, so the encryption hides the content from casual browsing only;
    // integrity comes from the SHA-1 of every entry, which is checked on every extraction.
    public class BinFileEntry
    {
        public string Name;
        public string Sha1;
        public string Category;
        public string Arch;
        public long Offset;
        public long Length;
        public long OriginalSize;
        public string IvBase64;
        public bool IsGzip;

        // Set while reading: the archive this entry belongs to
        public string BinPath;
    }

    public sealed class BinArchiveInfo
    {
        public string Path;
        public string Slug;
        public string Language;
        public string Arch;
        public string UpdateId;
        public string Kind;
        public string BuildId;
        public string Label;
        public string Created;
        public long TotalBytes;
        public long FileLength;
        public DateTime LastWriteUtc;
        public List<BinFileEntry> Files = new List<BinFileEntry>();
    }

    public static class BinArchive
    {
        public const int FormatVersion = 1;
        internal const int HeaderBase = 4 + 4 + 4 + 16;
        internal const int MaxManifestBytes = 64 * 1024 * 1024;
        private static readonly byte[] Magic = new byte[] { (byte)'W', (byte)'P', (byte)'E', (byte)'B' };
        private static readonly byte[] StaticKey = ComputeKey();

        private static byte[] ComputeKey()
        {
            using (SHA256 sha = SHA256.Create())
            {
                return sha.ComputeHash(Encoding.UTF8.GetBytes("WinPEOCs.Offline.Repo.2026.SecretKey"));
            }
        }

        internal static byte[] GenerateIV()
        {
            byte[] iv = new byte[16];
            using (RandomNumberGenerator rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(iv);
            }
            return iv;
        }

        internal static Aes NewAes(byte[] iv)
        {
            Aes aes = Aes.Create();
            aes.Key = StaticKey;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            return aes;
        }

        public static byte[] Encrypt(byte[] plain, byte[] iv)
        {
            using (Aes aes = NewAes(iv))
            using (ICryptoTransform t = aes.CreateEncryptor())
            {
                return t.TransformFinalBlock(plain, 0, plain.Length);
            }
        }

        public static byte[] Decrypt(byte[] cipher, byte[] iv)
        {
            using (Aes aes = NewAes(iv))
            using (ICryptoTransform t = aes.CreateDecryptor())
            {
                return t.TransformFinalBlock(cipher, 0, cipher.Length);
            }
        }

        internal static string Hex(byte[] hash)
        {
            StringBuilder sb = new StringBuilder(hash.Length * 2);
            foreach (byte b in hash) sb.Append(b.ToString("x2", CultureInfo.InvariantCulture));
            return sb.ToString();
        }

        internal static void ReadExact(Stream s, byte[] buf, int count)
        {
            int read = 0;
            while (read < count)
            {
                int n = s.Read(buf, read, count - read);
                if (n <= 0) throw new InvalidDataException("Unexpected end of archive");
                read += n;
            }
        }

        public static bool IsBinArchive(string binPath)
        {
            try
            {
                using (FileStream fs = new FileStream(binPath, FileMode.Open, FileAccess.Read, FileShare.Read))
                {
                    if (fs.Length < HeaderBase) return false;
                    byte[] m = new byte[4];
                    ReadExact(fs, m, 4);
                    for (int i = 0; i < 4; i++) if (m[i] != Magic[i]) return false;
                    return true;
                }
            }
            catch { return false; }
        }

        private static byte[] ReadManifestCipher(FileStream fs, out byte[] iv)
        {
            byte[] head = new byte[HeaderBase];
            ReadExact(fs, head, HeaderBase);
            for (int i = 0; i < 4; i++) if (head[i] != Magic[i]) throw new InvalidDataException("Not a WinPE OCs .bin archive (bad magic)");
            int ver = BitConverter.ToInt32(head, 4);
            if (ver != FormatVersion) throw new InvalidDataException("Unsupported .bin version: " + ver.ToString(CultureInfo.InvariantCulture));
            int len = BitConverter.ToInt32(head, 8);
            if (len < 16 || len % 16 != 0 || len > MaxManifestBytes || HeaderBase + (long)len > fs.Length)
                throw new InvalidDataException("Damaged .bin archive (manifest length)");
            iv = new byte[16];
            Buffer.BlockCopy(head, 12, iv, 0, 16);
            byte[] cipher = new byte[len];
            ReadExact(fs, cipher, len);
            return cipher;
        }

        private static string DecryptManifest(byte[] cipher, byte[] iv)
        {
            try
            {
                return Encoding.UTF8.GetString(Decrypt(cipher, iv));
            }
            catch (CryptographicException)
            {
                throw new InvalidDataException("Damaged .bin archive (manifest cannot be decrypted)");
            }
        }

        public static string ReadXmlManifest(string binPath)
        {
            if (!File.Exists(binPath)) return null;
            using (FileStream fs = new FileStream(binPath, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                byte[] iv;
                byte[] cipher = ReadManifestCipher(fs, out iv);
                return DecryptManifest(cipher, iv);
            }
        }

        private static string Attr(XmlElement el, string name)
        {
            return el == null ? string.Empty : el.GetAttribute(name);
        }

        private static long ParseLong(string s)
        {
            long v;
            if (!long.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out v)) throw new InvalidDataException("Damaged .bin archive (number: " + s + ")");
            return v;
        }

        public static BinArchiveInfo ReadInfo(string binPath)
        {
            string full = System.IO.Path.GetFullPath(binPath);
            FileInfo fi = new FileInfo(full);
            if (!fi.Exists) throw new FileNotFoundException("Archive not found", full);
            string xml;
            long headerLen;
            using (FileStream fs = new FileStream(full, FileMode.Open, FileAccess.Read, FileShare.Read))
            {
                byte[] iv;
                byte[] cipher = ReadManifestCipher(fs, out iv);
                headerLen = HeaderBase + (long)cipher.Length;
                xml = DecryptManifest(cipher, iv);
            }

            XmlDocument doc = new XmlDocument();
            doc.XmlResolver = null;
            XmlReaderSettings rs = new XmlReaderSettings();
            rs.DtdProcessing = DtdProcessing.Prohibit;
            rs.XmlResolver = null;
            using (StringReader sr = new StringReader(xml))
            using (XmlReader xr = XmlReader.Create(sr, rs))
            {
                doc.Load(xr);
            }

            BinArchiveInfo info = new BinArchiveInfo();
            info.Path = full;
            info.FileLength = fi.Length;
            info.LastWriteUtc = fi.LastWriteTimeUtc;
            XmlElement root = doc.DocumentElement;
            if (root == null || root.Name != "WinPEOCsRepo") throw new InvalidDataException("Damaged .bin archive (manifest root)");
            info.Created = Attr(root, "Created");
            XmlElement meta = root.SelectSingleNode("Metadata") as XmlElement;
            info.Slug = Attr(meta, "Slug");
            info.Language = Attr(meta, "Language");
            info.Arch = Attr(meta, "Arch");
            info.UpdateId = Attr(meta, "UpdateId");
            info.Kind = Attr(meta, "Kind");
            info.BuildId = Attr(meta, "BuildId");
            info.Label = Attr(meta, "Label");

            XmlNodeList nodes = root.SelectNodes("Files/File");
            if (nodes != null)
            {
                foreach (XmlNode n in nodes)
                {
                    XmlElement el = n as XmlElement;
                    if (el == null) continue;
                    BinFileEntry e = new BinFileEntry();
                    e.Name = el.GetAttribute("Name");
                    e.Sha1 = el.GetAttribute("Sha1").ToLowerInvariant();
                    e.Category = el.GetAttribute("Category");
                    e.Arch = el.GetAttribute("Arch");
                    e.Offset = ParseLong(el.GetAttribute("Offset"));
                    e.Length = ParseLong(el.GetAttribute("Length"));
                    e.OriginalSize = ParseLong(el.GetAttribute("OriginalSize"));
                    e.IvBase64 = el.GetAttribute("Iv");
                    e.IsGzip = el.GetAttribute("Compressed") == "1";
                    e.BinPath = full;
                    if (string.IsNullOrEmpty(e.Name) || e.Length <= 0 || e.Length % 16 != 0 || e.Offset < headerLen || e.Offset + e.Length > fi.Length)
                        throw new InvalidDataException("Damaged .bin archive (entry " + e.Name + ")");
                    info.Files.Add(e);
                    info.TotalBytes += e.OriginalSize;
                }
            }
            return info;
        }

        public static List<BinFileEntry> ReadIndex(string binPath)
        {
            if (!File.Exists(binPath)) return new List<BinFileEntry>();
            return ReadInfo(binPath).Files;
        }

        // Read-only stream with the original file bytes of one entry (decrypted and, if needed, decompressed).
        public static Stream OpenEntry(BinFileEntry entry)
        {
            return OpenEntry(entry.BinPath, entry);
        }

        public static Stream OpenEntry(string binPath, BinFileEntry entry)
        {
            if (entry == null) throw new ArgumentNullException("entry");
            FileStream fs = new FileStream(binPath, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 16);
            try
            {
                if (entry.Offset + entry.Length > fs.Length) throw new InvalidDataException("Damaged .bin archive (entry " + entry.Name + " is truncated)");
                fs.Seek(entry.Offset, SeekOrigin.Begin);
                Stream slice = new SliceStream(fs, entry.Length);
                Aes aes = NewAes(Convert.FromBase64String(entry.IvBase64));
                Stream plain = new CryptoStream(slice, aes.CreateDecryptor(), CryptoStreamMode.Read);
                if (entry.IsGzip) plain = new GZipStream(plain, CompressionMode.Decompress);
                return new OwnerStream(plain, fs, aes, entry.Name);
            }
            catch
            {
                fs.Dispose();
                throw;
            }
        }

        public static BinFileEntry FindEntry(string binPath, string fileNameOrSha1)
        {
            foreach (BinFileEntry e in ReadIndex(binPath))
            {
                if (string.Equals(e.Sha1, fileNameOrSha1, StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(e.Name, fileNameOrSha1, StringComparison.OrdinalIgnoreCase))
                    return e;
            }
            return null;
        }

        // Extracts one entry through a .part file; the file is kept only when size and SHA-1 match the manifest.
        public static void ExtractEntry(BinFileEntry entry, string destPath)
        {
            string dir = System.IO.Path.GetDirectoryName(destPath);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            string part = destPath + ".part";
            try
            {
                long done = 0;
                string hex;
                using (SHA1 h = SHA1.Create())
                {
                    using (Stream src = OpenEntry(entry))
                    using (FileStream dst = new FileStream(part, FileMode.Create, FileAccess.Write, FileShare.None, 1 << 20))
                    {
                        byte[] buf = new byte[1 << 20];
                        int n;
                        while ((n = src.Read(buf, 0, buf.Length)) > 0)
                        {
                            h.TransformBlock(buf, 0, n, null, 0);
                            dst.Write(buf, 0, n);
                            done += n;
                        }
                    }
                    h.TransformFinalBlock(new byte[0], 0, 0);
                    hex = Hex(h.Hash);
                }
                if (done != entry.OriginalSize) throw new InvalidDataException("Size mismatch in archive entry " + entry.Name);
                if (!string.IsNullOrEmpty(entry.Sha1) && !string.Equals(hex, entry.Sha1, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidDataException("SHA-1 mismatch in archive entry " + entry.Name);
                if (File.Exists(destPath)) File.Delete(destPath);
                File.Move(part, destPath);
            }
            catch (CryptographicException)
            {
                TryDelete(part);
                throw new InvalidDataException("Archive entry cannot be decrypted (damaged .bin): " + entry.Name);
            }
            catch
            {
                TryDelete(part);
                throw;
            }
        }

        public static bool ExtractFile(string binPath, string fileNameOrSha1, string destPath)
        {
            BinFileEntry target = FindEntry(binPath, fileNameOrSha1);
            if (target == null) return false;
            ExtractEntry(target, destPath);
            return true;
        }

        // SHA-1 of the decrypted entry bytes (repository check); throws on damaged data.
        public static string HashEntry(BinFileEntry entry)
        {
            try
            {
                using (SHA1 h = SHA1.Create())
                using (Stream src = OpenEntry(entry))
                {
                    byte[] buf = new byte[1 << 20];
                    long done = 0;
                    int n;
                    while ((n = src.Read(buf, 0, buf.Length)) > 0) { h.TransformBlock(buf, 0, n, null, 0); done += n; }
                    h.TransformFinalBlock(new byte[0], 0, 0);
                    if (done != entry.OriginalSize) throw new InvalidDataException("Size mismatch in archive entry " + entry.Name);
                    return Hex(h.Hash);
                }
            }
            catch (CryptographicException)
            {
                throw new InvalidDataException("Archive entry cannot be decrypted (damaged .bin): " + entry.Name);
            }
        }

        public static void CreateArchive(string binPath, string slug, string lang, string arch, string updateId, IEnumerable<Tuple<string, string, string, string>> fileList)
        {
            // fileList items: Tuple<LocalFilePath, Name, Category, Arch>
            using (BinArchiveWriter w = new BinArchiveWriter(binPath))
            {
                w.Slug = slug; w.Language = lang; w.Arch = arch; w.UpdateId = updateId; w.Kind = "lang";
                foreach (Tuple<string, string, string, string> item in fileList)
                {
                    if (!File.Exists(item.Item1)) continue;
                    w.Add(item.Item1, item.Item2, item.Item3, item.Item4);
                }
                w.Commit();
            }
        }

        internal static void TryDelete(string path)
        {
            try { if (File.Exists(path)) File.Delete(path); } catch { }
        }

        internal static bool ShouldCompress(string name, long size)
        {
            if (size <= 0 || size > 64L * 1024 * 1024) return false;
            string ext = (System.IO.Path.GetExtension(name) ?? string.Empty).ToLowerInvariant();
            // Cabinets, ESD/WIM images and packages are already compressed
            switch (ext)
            {
                case ".cab": case ".esd": case ".wim": case ".zip": case ".appx": case ".msix":
                case ".appxbundle": case ".msixbundle": case ".7z": case ".gz": case ".msu": case ".psf":
                    return false;
            }
            return true;
        }

        internal static byte[] BuildManifest(BinArchiveWriter w, List<BinFileEntry> entries, long headerLen, long[] relOffsets)
        {
            XmlDocument doc = new XmlDocument();
            XmlElement root = doc.CreateElement("WinPEOCsRepo");
            root.SetAttribute("Version", "1.0");
            root.SetAttribute("Created", DateTime.UtcNow.ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture));
            doc.AppendChild(root);

            long totalBytes = 0;
            foreach (BinFileEntry e in entries) totalBytes += e.OriginalSize;
            XmlElement meta = doc.CreateElement("Metadata");
            meta.SetAttribute("Slug", w.Slug ?? string.Empty);
            meta.SetAttribute("Language", w.Language ?? string.Empty);
            meta.SetAttribute("Arch", w.Arch ?? string.Empty);
            meta.SetAttribute("UpdateId", w.UpdateId ?? string.Empty);
            meta.SetAttribute("Kind", w.Kind ?? string.Empty);
            meta.SetAttribute("BuildId", w.BuildId ?? string.Empty);
            meta.SetAttribute("Label", w.Label ?? string.Empty);
            meta.SetAttribute("TotalFiles", entries.Count.ToString(CultureInfo.InvariantCulture));
            meta.SetAttribute("TotalBytes", totalBytes.ToString(CultureInfo.InvariantCulture));
            root.AppendChild(meta);

            XmlElement filesNode = doc.CreateElement("Files");
            root.AppendChild(filesNode);
            for (int i = 0; i < entries.Count; i++)
            {
                BinFileEntry e = entries[i];
                XmlElement el = doc.CreateElement("File");
                el.SetAttribute("Name", e.Name);
                el.SetAttribute("Sha1", e.Sha1 ?? string.Empty);
                el.SetAttribute("Category", e.Category ?? string.Empty);
                el.SetAttribute("Arch", e.Arch ?? string.Empty);
                el.SetAttribute("Offset", (headerLen + relOffsets[i]).ToString(CultureInfo.InvariantCulture));
                el.SetAttribute("Length", e.Length.ToString(CultureInfo.InvariantCulture));
                el.SetAttribute("OriginalSize", e.OriginalSize.ToString(CultureInfo.InvariantCulture));
                el.SetAttribute("Iv", e.IvBase64);
                el.SetAttribute("Compressed", e.IsGzip ? "1" : "0");
                filesNode.AppendChild(el);
            }
            return Encoding.UTF8.GetBytes(doc.OuterXml);
        }

        internal static void WriteHeader(Stream s, byte[] iv, byte[] cipher)
        {
            s.Write(Magic, 0, 4);
            s.Write(BitConverter.GetBytes(FormatVersion), 0, 4);
            s.Write(BitConverter.GetBytes(cipher.Length), 0, 4);
            s.Write(iv, 0, 16);
            s.Write(cipher, 0, cipher.Length);
        }

        internal static void CopyRange(Stream src, long offset, long length, Stream dst, byte[] buf)
        {
            src.Seek(offset, SeekOrigin.Begin);
            long left = length;
            while (left > 0)
            {
                int n = src.Read(buf, 0, (int)Math.Min(buf.Length, left));
                if (n <= 0) throw new InvalidDataException("Unexpected end of archive data");
                dst.Write(buf, 0, n);
                left -= n;
            }
        }
    }

    // Builds a .bin archive: existing entries can be kept (copied as they are, without re-encryption),
    // new files are encrypted into a temporary data file, Commit() writes the archive atomically.
    public sealed class BinArchiveWriter : IDisposable
    {
        private sealed class Slot
        {
            public BinFileEntry Entry;
            public string Source;       // archive to copy from (kept entry) or the temp data file
            public long SourceOffset;
        }

        private readonly string _binPath;
        private readonly string _dataPath;
        private FileStream _data;
        private readonly List<Slot> _slots = new List<Slot>();
        private bool _committed;

        public string Slug, Language, Arch, UpdateId, Kind, BuildId, Label;

        public BinArchiveWriter(string binPath)
        {
            _binPath = System.IO.Path.GetFullPath(binPath);
            string dir = System.IO.Path.GetDirectoryName(_binPath);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            _dataPath = _binPath + ".data.tmp";
            _data = new FileStream(_dataPath, FileMode.Create, FileAccess.ReadWrite, FileShare.None, 1 << 20);
        }

        public int Count { get { return _slots.Count; } }

        public bool Contains(string name)
        {
            return IndexOf(name) >= 0;
        }

        private int IndexOf(string name)
        {
            for (int i = 0; i < _slots.Count; i++)
                if (string.Equals(_slots[i].Entry.Name, name, StringComparison.OrdinalIgnoreCase)) return i;
            return -1;
        }

        // Keeps every entry of an existing archive (metadata fields that are still empty are taken over).
        public int KeepFrom(string existingBin)
        {
            BinArchiveInfo info = BinArchive.ReadInfo(existingBin);
            if (string.IsNullOrEmpty(Slug)) Slug = info.Slug;
            if (string.IsNullOrEmpty(Language)) Language = info.Language;
            if (string.IsNullOrEmpty(Arch)) Arch = info.Arch;
            if (string.IsNullOrEmpty(UpdateId)) UpdateId = info.UpdateId;
            if (string.IsNullOrEmpty(Kind)) Kind = info.Kind;
            if (string.IsNullOrEmpty(BuildId)) BuildId = info.BuildId;
            if (string.IsNullOrEmpty(Label)) Label = info.Label;
            int kept = 0;
            foreach (BinFileEntry e in info.Files)
            {
                if (Contains(e.Name)) continue;
                Slot s = new Slot();
                s.Entry = e;
                s.Source = info.Path;
                s.SourceOffset = e.Offset;
                _slots.Add(s);
                kept++;
            }
            return kept;
        }

        // Copies an entry of another archive (encrypted bytes as they are) under the given name;
        // an entry with the same name is replaced.
        public BinFileEntry CopyEntry(BinFileEntry source, string name, string category, string arch)
        {
            if (_committed) throw new InvalidOperationException("Archive already committed");
            if (source == null || string.IsNullOrEmpty(source.BinPath)) throw new ArgumentException("source");
            BinFileEntry e = new BinFileEntry();
            e.Name = string.IsNullOrEmpty(name) ? source.Name : name;
            e.Sha1 = source.Sha1;
            e.Category = category ?? source.Category;
            e.Arch = arch ?? source.Arch;
            e.Length = source.Length;
            e.OriginalSize = source.OriginalSize;
            e.IvBase64 = source.IvBase64;
            e.IsGzip = source.IsGzip;
            Slot s = new Slot();
            s.Entry = e;
            s.Source = source.BinPath;
            s.SourceOffset = source.Offset;
            int at = IndexOf(e.Name);
            if (at >= 0) _slots[at] = s; else _slots.Add(s);
            return e;
        }

        // Drops an entry (kept or added) from the archive being written.
        public bool Remove(string name)
        {
            int at = IndexOf(name);
            if (at < 0) return false;
            _slots.RemoveAt(at);
            return true;
        }

        // Encrypts a local file into the archive; an entry with the same name is replaced.
        public BinFileEntry Add(string localPath, string name, string category, string arch)
        {
            if (_committed) throw new InvalidOperationException("Archive already committed");
            if (string.IsNullOrEmpty(name)) throw new ArgumentException("name");
            FileInfo fi = new FileInfo(localPath);
            if (!fi.Exists) throw new FileNotFoundException("File not found", localPath);

            byte[] iv = BinArchive.GenerateIV();
            bool gzip = false;
            byte[] packed = null;
            if (BinArchive.ShouldCompress(name, fi.Length))
            {
                using (MemoryStream ms = new MemoryStream())
                {
                    using (GZipStream gz = new GZipStream(ms, CompressionLevel.Optimal, true))
                    using (FileStream src = new FileStream(localPath, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 20))
                    {
                        src.CopyTo(gz);
                    }
                    if (ms.Length < fi.Length - fi.Length / 50) { gzip = true; packed = ms.ToArray(); }
                }
            }

            long start = _data.Seek(0, SeekOrigin.End);
            string sha1;
            long size = 0;
            using (SHA1 h = SHA1.Create())
            {
                using (Aes aes = BinArchive.NewAes(iv))
                using (ICryptoTransform enc = aes.CreateEncryptor())
                {
                    CryptoStream cs = new CryptoStream(new KeepOpenStream(_data), enc, CryptoStreamMode.Write);
                    byte[] buf = new byte[1 << 20];
                    using (FileStream src = new FileStream(localPath, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 20))
                    {
                        int n;
                        while ((n = src.Read(buf, 0, buf.Length)) > 0)
                        {
                            h.TransformBlock(buf, 0, n, null, 0);
                            size += n;
                            if (!gzip) cs.Write(buf, 0, n);
                        }
                    }
                    if (gzip) cs.Write(packed, 0, packed.Length);
                    cs.FlushFinalBlock();
                    cs.Dispose();
                }
                h.TransformFinalBlock(new byte[0], 0, 0);
                sha1 = BinArchive.Hex(h.Hash);
            }

            BinFileEntry e = new BinFileEntry();
            e.Name = name;
            e.Sha1 = sha1;
            e.Category = category ?? string.Empty;
            e.Arch = arch ?? string.Empty;
            e.Length = _data.Position - start;
            e.OriginalSize = size;
            e.IvBase64 = Convert.ToBase64String(iv);
            e.IsGzip = gzip;

            Slot s = new Slot();
            s.Entry = e;
            s.Source = null;
            s.SourceOffset = start;
            int at = IndexOf(name);
            if (at >= 0) _slots[at] = s; else _slots.Add(s);
            return e;
        }

        public void Commit()
        {
            if (_committed) throw new InvalidOperationException("Archive already committed");
            _data.Flush();

            List<BinFileEntry> entries = new List<BinFileEntry>();
            long[] rel = new long[_slots.Count];
            long pos = 0;
            for (int i = 0; i < _slots.Count; i++)
            {
                entries.Add(_slots[i].Entry);
                rel[i] = pos;
                pos += _slots[i].Entry.Length;
            }

            // The manifest holds absolute offsets, so its own length decides where the data starts: repeat until
            // the length is stable (offsets only grow, so this converges after a few rounds).
            byte[] iv = BinArchive.GenerateIV();
            long headerLen = BinArchive.HeaderBase;
            byte[] cipher = null;
            for (int round = 0; round < 32; round++)
            {
                cipher = BinArchive.Encrypt(BinArchive.BuildManifest(this, entries, headerLen, rel), iv);
                long need = BinArchive.HeaderBase + (long)cipher.Length;
                if (need == headerLen) break;
                headerLen = need;
            }
            if (BinArchive.HeaderBase + (long)cipher.Length != headerLen) throw new InvalidOperationException("Manifest length did not converge");
            if (cipher.Length > BinArchive.MaxManifestBytes) throw new InvalidOperationException("Manifest too large");

            string newPath = _binPath + ".new";
            Dictionary<string, FileStream> sources = new Dictionary<string, FileStream>(StringComparer.OrdinalIgnoreCase);
            try
            {
                using (FileStream outFs = new FileStream(newPath, FileMode.Create, FileAccess.Write, FileShare.None, 1 << 20))
                {
                    BinArchive.WriteHeader(outFs, iv, cipher);
                    byte[] buf = new byte[1 << 20];
                    foreach (Slot s in _slots)
                    {
                        Stream src;
                        if (s.Source == null)
                        {
                            src = _data;
                        }
                        else
                        {
                            FileStream fs;
                            if (!sources.TryGetValue(s.Source, out fs))
                            {
                                fs = new FileStream(s.Source, FileMode.Open, FileAccess.Read, FileShare.Read, 1 << 20);
                                sources[s.Source] = fs;
                            }
                            src = fs;
                        }
                        BinArchive.CopyRange(src, s.SourceOffset, s.Entry.Length, outFs, buf);
                    }
                    outFs.Flush();
                }
            }
            catch
            {
                foreach (FileStream fs in sources.Values) fs.Dispose();
                BinArchive.TryDelete(newPath);
                throw;
            }
            foreach (FileStream fs in sources.Values) fs.Dispose();

            _data.Dispose();
            _data = null;
            BinArchive.TryDelete(_dataPath);
            if (File.Exists(_binPath))
            {
                try { File.Replace(newPath, _binPath, null, true); }
                catch (PlatformNotSupportedException) { File.Delete(_binPath); File.Move(newPath, _binPath); }
                catch (IOException) { File.Delete(_binPath); File.Move(newPath, _binPath); }
            }
            else
            {
                File.Move(newPath, _binPath);
            }
            _committed = true;
        }

        public void Dispose()
        {
            if (_data != null) { try { _data.Dispose(); } catch { } _data = null; }
            BinArchive.TryDelete(_dataPath);
            if (!_committed) BinArchive.TryDelete(_binPath + ".new");
        }
    }

    // Passes writes through to a stream that must stay open after the CryptoStream is disposed
    internal sealed class KeepOpenStream : Stream
    {
        private readonly Stream _inner;
        public KeepOpenStream(Stream inner) { _inner = inner; }
        public override bool CanRead { get { return false; } }
        public override bool CanSeek { get { return false; } }
        public override bool CanWrite { get { return true; } }
        public override long Length { get { throw new NotSupportedException(); } }
        public override long Position { get { throw new NotSupportedException(); } set { throw new NotSupportedException(); } }
        public override void Flush() { _inner.Flush(); }
        public override int Read(byte[] buffer, int offset, int count) { throw new NotSupportedException(); }
        public override long Seek(long offset, SeekOrigin origin) { throw new NotSupportedException(); }
        public override void SetLength(long value) { throw new NotSupportedException(); }
        public override void Write(byte[] buffer, int offset, int count) { _inner.Write(buffer, offset, count); }
        protected override void Dispose(bool disposing) { }
    }

    // Reads at most 'length' bytes from the current position of the inner stream; owns the inner stream
    internal sealed class SliceStream : Stream
    {
        private readonly Stream _inner;
        private long _left;
        public SliceStream(Stream inner, long length) { _inner = inner; _left = length; }
        public override bool CanRead { get { return true; } }
        public override bool CanSeek { get { return false; } }
        public override bool CanWrite { get { return false; } }
        public override long Length { get { throw new NotSupportedException(); } }
        public override long Position { get { throw new NotSupportedException(); } set { throw new NotSupportedException(); } }
        public override void Flush() { }
        public override int Read(byte[] buffer, int offset, int count)
        {
            if (_left <= 0) return 0;
            int n = _inner.Read(buffer, offset, (int)Math.Min(count, _left));
            if (n <= 0) throw new InvalidDataException("Unexpected end of archive data");
            _left -= n;
            return n;
        }
        public override long Seek(long offset, SeekOrigin origin) { throw new NotSupportedException(); }
        public override void SetLength(long value) { throw new NotSupportedException(); }
        public override void Write(byte[] buffer, int offset, int count) { throw new NotSupportedException(); }
        protected override void Dispose(bool disposing) { if (disposing) _inner.Dispose(); base.Dispose(disposing); }
    }

    // Read stream returned by OpenEntry. Disposing it always closes the archive file, also when the
    // decryptor throws because the entry was not read to the end (cancelled copy).
    internal sealed class OwnerStream : Stream
    {
        private readonly Stream _inner;
        private readonly Stream _file;
        private readonly IDisposable _owned;
        private readonly string _name;
        public OwnerStream(Stream inner, Stream file, IDisposable owned, string name) { _inner = inner; _file = file; _owned = owned; _name = name; }
        public override bool CanRead { get { return true; } }
        public override bool CanSeek { get { return false; } }
        public override bool CanWrite { get { return false; } }
        public override long Length { get { throw new NotSupportedException(); } }
        public override long Position { get { throw new NotSupportedException(); } set { throw new NotSupportedException(); } }
        public override void Flush() { }
        public override int Read(byte[] buffer, int offset, int count)
        {
            try { return _inner.Read(buffer, offset, count); }
            catch (CryptographicException) { throw new InvalidDataException("Archive entry cannot be decrypted (damaged .bin): " + _name); }
        }
        public override long Seek(long offset, SeekOrigin origin) { throw new NotSupportedException(); }
        public override void SetLength(long value) { throw new NotSupportedException(); }
        public override void Write(byte[] buffer, int offset, int count) { throw new NotSupportedException(); }
        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                try { _inner.Dispose(); }
                catch (CryptographicException) { }
                catch (InvalidDataException) { }
                finally
                {
                    try { _file.Dispose(); } catch { }
                    try { _owned.Dispose(); } catch { }
                }
            }
            base.Dispose(disposing);
        }
    }
}
'@

$script:BinArchiveError = $null

function Ensure-BinArchiveCompiled {
    if ('WinPEOCs.Archive.BinArchive' -as [type]) {
        # The first offline design used the same type name without the writer; types cannot be replaced
        if (-not ('WinPEOCs.Archive.BinArchiveWriter' -as [type])) {
            throw 'Bu PowerShell oturumunda BinArchive bileşeninin eski bir sürümü yüklü; çevrimdışı sürümü yeni bir PowerShell penceresinde başlatın. / An older BinArchive is loaded in this PowerShell session; start the offline edition in a new PowerShell window.'
        }
        return
    }
    if ($script:BinArchiveError) { throw "BinArchive: $script:BinArchiveError" }
    try {
        if ($PSVersionTable.PSEdition -eq 'Core') {
            Add-Type -TypeDefinition $script:BinArchiveSource -IgnoreWarnings -WarningAction SilentlyContinue -ErrorAction Stop
        } else {
            $refs = @('System.dll', 'System.Core.dll', 'System.Xml.dll', 'System.IO.Compression.dll')
            Add-Type -TypeDefinition $script:BinArchiveSource -ReferencedAssemblies $refs -IgnoreWarnings -WarningAction SilentlyContinue -ErrorAction Stop
        }
    } catch {
        $script:BinArchiveError = $_.Exception.Message
        throw "BinArchive: $script:BinArchiveError"
    }
}

$script:BinInfoCache = @{}        # full path (lower) -> @{ Stamp; Info }
$script:BinArchives  = @{}        # full path (lower) -> BinArchiveInfo
$script:BinBySha1    = @{}        # sha1 -> BinFileEntry (first archive wins; equal hash = equal content)
$script:BinByName    = @{}        # full path (lower) -> @{ entry name (lower) -> BinFileEntry }
$script:BinWarned    = @{}
$script:LooseByName  = @{}        # file name (lower) -> list of @{ Path; Length }

function Get-BinArchiveInfo {
    param([string]$BinPath)
    if (-not [System.IO.File]::Exists($BinPath)) { return $null }
    Ensure-BinArchiveCompiled
    $fi = New-Object System.IO.FileInfo($BinPath)
    $key = $fi.FullName.ToLowerInvariant()
    $stamp = '{0}|{1}' -f $fi.Length, $fi.LastWriteTimeUtc.Ticks
    $c = $script:BinInfoCache[$key]
    if ($c -and $c.Stamp -eq $stamp) { return $c.Info }
    try {
        $info = [WinPEOCs.Archive.BinArchive]::ReadInfo($fi.FullName)
        $script:BinInfoCache[$key] = @{ Stamp = $stamp; Info = $info }
        return $info
    } catch {
        $script:BinInfoCache.Remove($key)
        $msg = $_.Exception.Message
        if ($_.Exception.InnerException) { $msg = $_.Exception.InnerException.Message }
        if (-not $script:BinWarned.ContainsKey("$key|$stamp")) {
            $script:BinWarned["$key|$stamp"] = $true
            Write-UiLog 'error' (LF 'Off_BinError' $fi.Name $msg)
        }
        return $null
    }
}

# Name / SHA-1 map of one archive (kept for callers of the first offline design)
function Get-BinArchiveEntries {
    param([string]$BinPath)
    $info = Get-BinArchiveInfo $BinPath
    if (-not $info) { return $null }
    $map = @{}
    foreach ($e in $info.Files) {
        $map[$e.Name.ToLowerInvariant()] = $e
        if ($e.Sha1) { $map[$e.Sha1] = $e }
    }
    return $map
}

function Get-OfflineBinDirs {
    $dirs = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    $cands = @()
    if ($script:RepoIndex -and $script:RepoIndex.Dir) { $cands += $script:RepoIndex.Dir }
    if ($script:RepoDir) { $cands += $script:RepoDir }
    if ($script:AppRoot) { $cands += $script:AppRoot; $cands += (Join-Path $script:AppRoot 'Repo') }
    foreach ($d in $cands) {
        if (-not $d -or -not [System.IO.Directory]::Exists($d)) { continue }
        $k = [System.IO.Path]::GetFullPath($d).TrimEnd([char[]]@('\', '/')).ToLowerInvariant()
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        $dirs.Add($d)
    }
    return ,$dirs.ToArray()
}

function Refresh-UnifiedBinIndex {
    $script:BinArchives = @{}
    $script:BinBySha1 = @{}
    $script:BinByName = @{}
    foreach ($d in (Get-OfflineBinDirs)) {
        foreach ($bf in @(Get-ChildItem -LiteralPath $d -Filter '*.bin' -File -ErrorAction SilentlyContinue)) {
            if ($bf.Extension -ne '.bin') { continue }
            $k = $bf.FullName.ToLowerInvariant()
            if ($script:BinArchives.ContainsKey($k)) { continue }
            $info = Get-BinArchiveInfo $bf.FullName
            if (-not $info) { continue }
            $script:BinArchives[$k] = $info
            $names = @{}
            foreach ($e in $info.Files) {
                $names[$e.Name.ToLowerInvariant()] = $e
                if ($e.Sha1 -and -not $script:BinBySha1.ContainsKey($e.Sha1)) { $script:BinBySha1[$e.Sha1] = $e }
            }
            $script:BinByName[$k] = $names
        }
    }
}

# Loose files: Lang / WinPE / Repo\Lang / Repo\WinPE under every root and <slug>\Repo\Lang, <slug>\Lang
function Refresh-OfflineLooseFiles {
    $script:LooseByName = @{}
    if (-not $script:RepoIndex) { return }
    $slugs = @{}
    foreach ($r in $script:RepoIndex.Rows) { $slugs[(Get-VersionSlug -VersionText $r.Version)] = $true }
    $dirs = New-Object System.Collections.Generic.List[string]
    foreach ($root in $script:RepoIndex.Roots) {
        if (-not [System.IO.Directory]::Exists($root)) { continue }
        foreach ($sub in @(@('Lang'), @('WinPE'), @('Repo', 'Lang'), @('Repo', 'WinPE'))) {
            $p = $root
            foreach ($s in $sub) { $p = Join-Path $p $s }
            $dirs.Add($p)
        }
        try {
            foreach ($sd in [System.IO.Directory]::GetDirectories($root)) {
                if (-not $slugs.ContainsKey([System.IO.Path]::GetFileName($sd).ToLowerInvariant())) { continue }
                $dirs.Add((Join-Path (Join-Path $sd 'Repo') 'Lang'))
                $dirs.Add((Join-Path $sd 'Lang'))
            }
        } catch { }
    }
    $seen = @{}
    foreach ($d in $dirs) {
        if (-not [System.IO.Directory]::Exists($d)) { continue }
        $k = [System.IO.Path]::GetFullPath($d).ToLowerInvariant()
        if ($seen.ContainsKey($k)) { continue }
        $seen[$k] = $true
        try {
            foreach ($f in (New-Object System.IO.DirectoryInfo($d)).GetFiles()) {
                $ext = $f.Extension.ToLowerInvariant()
                if ($ext -ne '.cab' -and $ext -ne '.esd' -and $ext -ne '.appx') { continue }
                $n = $f.Name.ToLowerInvariant()
                if (-not $script:LooseByName.ContainsKey($n)) { $script:LooseByName[$n] = New-Object System.Collections.Generic.List[object] }
                $script:LooseByName[$n].Add([PSCustomObject]@{ Path = $f.FullName; Length = $f.Length })
            }
        } catch { }
    }
}

function Update-OfflineSources {
    Update-OfflineRepoRoots
    Refresh-UnifiedBinIndex
    Refresh-OfflineLooseFiles
}

function Get-VersionSlug {
    param([string]$VersionText, [string]$BuildId = '')
    if ($BuildId) { return $BuildId.ToLowerInvariant() }
    if ([string]::IsNullOrWhiteSpace($VersionText)) { return 'unknown' }
    $v = $VersionText.Trim().ToLowerInvariant()
    if ($v -match 'w11\s*26h2') { return 'w11_26h2' }
    if ($v -match 'w11\s*26h1') { return 'w11_26h1' }
    if ($v -match 'w11\s*25h2') { return 'w11_25h2' }
    if ($v -match 'w11\s*24h2') { return 'w11_24h2' }
    if ($v -match 'w11\s*22h2|w11\s*23h2') { return 'w11_22h2' }
    if ($v -match 'w11\s*21h2') { return 'w11_21h2' }
    if ($v -match 'server\s*2025|26100') { return 'ws2025_26100' }
    if ($v -match 'server\s*23h2|25398') { return 'ws23h2_25398' }
    if ($v -match 'server\s*2022|20348') { return 'ws2022_20348' }
    if ($v -match 'server\s*20h2|19042') { return 'ws20h2_19042' }
    if ($v -match 'server\s*2004|19041') { return 'ws2004_19041' }
    if ($v -match 'server\s*1909|18363') { return 'ws1909_18363' }
    if ($v -match 'server\s*1903|18362') { return 'ws1903_18362' }
    if ($v -match 'server\s*1809|17763') { return 'ws1809_17763' }
    if ($v -match 'server\s*1803|17134') { return 'ws1803_17134' }
    if ($v -match 'server\s*1709|16299') { return 'ws1709_16299' }
    if ($v -match 'server\s*2016|14393') { return 'ws2016_14393' }
    if ($v -match 'w10\s*22h2') { return 'w10_22h2' }
    if ($v -match 'w10\s*2004|w10\s*20h2|w10\s*21h1|w10\s*21h2') { return 'w10_2004_22h2' }
    if ($v -match 'w10\s*1903|w10\s*1909') { return 'w10_1903_1909' }
    if ($v -match 'w10\s*1809') { return 'w10_1809' }
    if ($v -match 'w10\s*1803') { return 'w10_1803' }
    if ($v -match 'w10\s*1709') { return 'w10_1709' }
    return ($v -replace '[^a-z0-9]+', '_').Trim('_')
}

# Archives: one per UUP row, architecture and language (w11_26h2_x64_de-de.bin). The first offline design
# (tr-tr only) named them <slug>_<arch>.bin; such an archive keeps serving the language of its manifest.
function Get-LangBinPath {
    param([string]$Version, [string]$Arch, [string]$Language)
    $slug = Get-VersionSlug -VersionText $Version
    $new = Join-Path $script:RepoIndex.Dir (('{0}_{1}_{2}.bin' -f $slug, $Arch, $Language).ToLowerInvariant())
    if ([System.IO.File]::Exists($new)) { return $new }
    $legacy = Join-Path $script:RepoIndex.Dir (('{0}_{1}.bin' -f $slug, $Arch).ToLowerInvariant())
    if ([System.IO.File]::Exists($legacy)) {
        $info = Get-BinArchiveInfo $legacy
        if ($info -and $info.Language -eq $Language) { return $legacy }
    }
    return $new
}

# Windows PE: neutral packages in winpe_<build>_<arch>.bin, language packages in winpe_<build>_<arch>_<lang>.bin.
# The tr-tr design kept both in winpe_<build>_<arch>.bin; such an archive keeps serving its language.
function Get-PeBinPath {
    param([string]$BuildId, [string]$Arch, [string]$Language = 'neutral')
    $base = Join-Path $script:RepoIndex.Dir (('winpe_{0}_{1}.bin' -f $BuildId, $Arch).ToLowerInvariant())
    if (-not $Language -or $Language -eq 'neutral') { return $base }
    $new = Join-Path $script:RepoIndex.Dir (('winpe_{0}_{1}_{2}.bin' -f $BuildId, $Arch, $Language).ToLowerInvariant())
    if ([System.IO.File]::Exists($new)) { return $new }
    if ([System.IO.File]::Exists($base)) {
        $info = Get-BinArchiveInfo $base
        if ($info -and $info.Language -eq $Language) { return $base }
    }
    return $new
}

